-- SRS review-card backfill — BATCH 7 of 10 (768 rows).
-- Run each batch on its own in the Supabase SQL Editor; order does not matter and
-- each is idempotent. Together the 10 batches equal backfill_srs_payload.sql.
-- Covers Top 2 preboards/mocks/reviewer + main-app banks + Top 2 banks.
WITH d(qid, patch) AS (
  VALUES
  ('1e4541ae-2p','{"options": ["Timolol", "Albuterol", "Epinephrine", "Betaxolol"], "correct": 0, "explanation": "With hypertension but NO asthma, a nonselective beta-blocker like timolol is the standard first-line antiglaucoma drug; it lowers IOP and its systemic beta-blockade is neutral-to-helpful for blood pressure. Epinephrine would raise blood pressure. Albuterol is a beta-2 agonist bronchodilator, not an antiglaucoma agent. Betaxolol (cardioselective) is reserved for when airway disease is present. Compare the asthma version of this item, where betaxolol wins."}'),
  ('cd748884-1z','{"options": ["increase in pulse rate", "decrease in salivation", "decrease GI motility", "constriction of pupil"], "correct": 3, "explanation": "Anticholinergics DILATE the pupil (block the iris sphincter), so ''constriction of pupil'' is NOT one of their effects. Their genuine major responses are tachycardia (increased pulse), dry mouth (decreased salivation), and slowed gut (decreased GI motility). Everything antimuscarinic points to drying up and speeding the heart while widening the pupil."}'),
  ('e6a04685-1w','{"options": ["Potassium sparing", "Diuretics", "Carbonic Anhydrase Inhibitors", "Osmotics"], "correct": 3, "explanation": "Osmotic agents (mannitol, glycerol) raise plasma osmolarity and pull water out of the brain and eye, rapidly lowering both intracranial and intraocular pressure. Potassium-sparing diuretics are weak and act at the kidney, plain ''diuretics'' is too vague and slow for acute pressure, and carbonic anhydrase inhibitors mainly reduce aqueous humor formation. For an acute pressure spike, reach for an osmotic."}'),
  ('d2c9a32a-1q','{"options": ["rewetting drops", "daily cleaner", "saline", "disinfectant"], "correct": 0, "explanation": "Rewetting (lubricating) drops are optional comfort products; a wearer can skip them and still care for the lens safely. Daily cleaner (removes deposits), saline (rinsing), and disinfectant (kills microbes) are core, essential steps of a lens-care regimen. If leaving it out does not compromise safety or cleaning, it is accessory."}'),
  ('be3bae53-12','{"options": ["analgesic property", "antipruritic property", "hypnotic property", "anti-inflammatory property"], "correct": 0, "explanation": "Paracetamol (acetaminophen) is primarily an analgesic and antipyretic; it relieves pain and fever centrally. It is NOT meaningfully anti-inflammatory (that is the NSAID/aspirin distinction), not antipruritic (antihistamines), and not hypnotic (sedatives). Key contrast: paracetamol = pain + fever only; NSAIDs add anti-inflammatory."}'),
  ('58d5a2e0-1j','{"options": ["Causes irritation at 2% solution", "Permits penetration with epithelial breaks", "Causes transient staining", "Does not stain cells"], "correct": 0, "explanation": "Fluorescein is well tolerated and does NOT cause irritation at 2% (that reputation belongs to Rose Bengal, which stings devitalized tissue), so statement A is the false one. The correct facts: fluorescein penetrates and pools where the epithelium is broken (B), its staining is transient and washes out (C), and it stains defects/spaces rather than living cells themselves (D). Fluorescein fills gaps; it does not sting or vitally stain cells."}'),
  ('67fe9b93-3d','{"options": ["centrally align", "with complete coverage", "tight fitting", "flat fitting"], "correct": 2, "explanation": "A bright central pool of fluorescein means tears are POOLING under the lens center (apical clearance), which is the signature of a STEEP/tight fit. A flat fit shows central bearing/touch that appears DARK (thin/absent fluorescein), and an aligned fit shows an even, moderate film. Bright/green pooling = steep; dark central touch = flat."}'),
  ('207e7d97-2i','{"options": ["dendritic pattern", "filmy and doughnut pattern", "punctate opacity", "slick and greasy"], "correct": 1, "explanation": "Protein deposits (from tear lysozyme/albumin) form a hazy, filmy coating and raised ''jelly bump''/doughnut-shaped mounds on the lens. A slick, greasy film points to LIPID deposits instead; a dendritic pattern suggests herpetic epithelial disease, and punctate opacity is a corneal not a deposit finding. Protein = filmy haze and doughnut bumps; lipid = greasy slick."}'),
  ('8cb161a7-35','{"options": ["disinfectant", "chelating agent", "cidal preservative", "static preservative"], "correct": 2, "explanation": "A cidal preservative actively KILLS organisms that get introduced into the bottle after it is opened, keeping the in-use solution sterile. A static preservative only inhibits growth without killing. A disinfectant acts on the LENS during soaking rather than guarding the bottle, and a chelating agent (like EDTA) binds metal ions to boost other preservatives, not a killer itself. ''Cidal'' = kills; ''static'' = merely stops growth."}'),
  ('e0bb238a-1a','{"options": ["Allopurinol", "Colchicine", "Probenecid", "Carbachol"], "correct": 1, "explanation": "For an ACUTE gout attack, colchicine (or an NSAID) is the first-line drug; it blocks neutrophil microtubules to shut down the urate-crystal inflammation fast. Allopurinol (xanthine oxidase inhibitor) and probenecid (uricosuric) are for LONG-TERM urate lowering and can actually worsen an acute flare if started during it. Carbachol is a cholinergic eye drug, unrelated. Acute gout = colchicine now; allopurinol later for prevention."}'),
  ('98fcf1c1-1u','{"options": ["Rheumatoid arthritis", "Fever", "Myalgia", "Peptic ulcer"], "correct": 3, "explanation": "Aspirin inhibits COX-1, stripping the stomach of protective prostaglandins and adding antiplatelet bleeding risk, so it is contraindicated in peptic ulcer disease. Rheumatoid arthritis, fever, and myalgia are actually indications for aspirin''s anti-inflammatory, antipyretic, and analgesic actions. If the gut is already ulcerated, aspirin can push it to bleed."}'),
  ('e1ef5c5a-3t','{"options": ["It causes gain in weight", "It may cause vision disorders", "It may cause serious liver damage", "Does not need prescription order from a doctor"], "correct": 2, "explanation": "Tacrine''s major drawback is hepatotoxicity (elevated liver enzymes), which required frequent monitoring and is the main reason it fell out of use in favor of donepezil, rivastigmine, and galantamine. It is not associated with weight gain or vision disorders as its defining problem, and it certainly requires a prescription. Tacrine = Toxic to the liver."}'),
  ('311593ba-2l','{"options": ["penicillinase-resistant penicillin", "broad-spectrum penicillin", "extended spectrum penicillin", "beta-lactamase inhibitor"], "correct": 1, "explanation": "Amoxicillin (like ampicillin) is an aminopenicillin, classified as a BROAD-spectrum penicillin that adds gram-negative coverage over natural penicillin. Penicillinase-resistant penicillins are the anti-staph agents (oxacillin, cloxacillin, methicillin). EXTENDED-spectrum penicillins are the antipseudomonal ones (piperacillin, ticarcillin). A beta-lactamase inhibitor is clavulanate/sulbactam, a partner drug, not amoxicillin itself. Amino = broad; anti-staph = penicillinase-resistant; anti-pseudomonal = extended."}'),
  ('f71fd2a6-16','{"options": ["acidic and is within ocular comfort range", "acidic and may cause slight ocular discomfort", "basic and is within ocular comfort range", "neutral and will cause no ocular discomfort"], "correct": 0, "explanation": "pH 6.5 is below 7.0, so it is (mildly) ACIDIC, not basic or neutral, which eliminates C and D. The eye tolerates a fairly wide buffered range (commonly cited as roughly 6.5 to 7.8), so a well-buffered 6.5 solution generally sits at the lower edge of the comfort range. VERIFY: some sources set the comfortable floor at 6.6 and would call 6.5 ''slightly uncomfortable'' (option B), so check which range your key uses. Tear pH itself is about 7.4."}'),
  ('b573fc5f-2a','{"options": ["Myopia", "punctate corneal opacity", "retinal hemorrhage", "Red - green color defects"], "correct": 0, "explanation": "NSAIDs can cause corneal deposits/punctate keratopathy, retinal hemorrhages (via their antiplatelet effect), and color-vision disturbance, but transient MYOPIA is not a typical NSAID effect (it belongs to sulfonamides, topiramate, and, as in an earlier item, isotretinoin). So myopia is the EXCEPT. Keep the drug-myopia list separate from the NSAID ocular-toxicity list."}'),
  ('b49610d4-2i','{"options": ["action of medication", "Route of administration", "Dose of drug", "adverse effects"], "correct": 2, "explanation": "Sedative and hypnotic are often the SAME drug at different doses: a low dose calms (sedation), a higher dose induces sleep (hypnosis). So the differentiating factor is the DOSE, not the route, the adverse effect, or a different mechanism. Same molecule, dial the dose: soothe low, sleep high."}'),
  ('4a901591-2t','{"options": ["Apraclonidine", "Timolol", "Carbacol", "Epinephrine borate"], "correct": 0, "explanation": "Apraclonidine (Iopidine), an alpha-2 agonist, is THE agent given to blunt the IOP spike after anterior-segment laser/surgery, so on clinical use it is the intended answer. Caveat: strictly, apraclonidine is a clonidine derivative, not a classic prodrug; the true ''prodrug'' of this family is dipivefrin (converted to epinephrine), which is not listed. Timolol and carbachol are not prodrugs, and epinephrine borate is just a buffered salt. VERIFY: the ''prodrug'' wording in this item is loose."}'),
  ('22c59c01-22','{"options": ["Brand and Trade name", "Generic or approved name", "Non-proprietary name", "Chemical name"], "correct": 0, "explanation": "Proprietary BRAND/trade names are capitalized (they are registered names, like Tylenol, Ventolin). Generic/non-proprietary names (acetaminophen, salbutamol) and chemical names are written in lower case. Capital letter = the company''s trademarked brand."}'),
  ('cb814094-44','{"options": ["Gramicidin", "Kanamycin", "Neomycin", "Tobramycin"], "correct": 3, "explanation": "Tobramycin is the aminoglycoside noted for GREATER anti-Pseudomonas potency than gentamicin, while being comparatively WEAKER against Serratia. Gramicidin is a topical gram-positive agent, and kanamycin/neomycin lack tobramycin''s Pseudomonas edge. Tobramycin = the Pseudomonas-preferring aminoglycoside."}'),
  ('8fb48c36-1q','{"options": ["platinum-coated disc", "sodium thiosulfate", "poly vinyl Alcohol", "sodium transferate"], "correct": 0, "explanation": "The AOSept (one-step) system neutralizes its 3% hydrogen peroxide with a PLATINUM-COATED catalytic disc built into the case; the platinum decomposes H2O2 into water and oxygen while the lens soaks. Chemical neutralizers like sodium thiosulfate, catalase, or sodium pyruvate are used in TWO-step systems instead. Polyvinyl alcohol is a wetting/viscosity agent, unrelated. AOSept = platinum disc catalyst."}'),
  ('e709ab4b-30','{"options": ["reflex tearing", "dry eyes", "blurred vision", "irritating vision"], "correct": 0, "explanation": "A drop whose pH is far from the tear film''s 7.4 stings/irritates the ocular surface, and the immediate reflex is REFLEX TEARING (lacrimation) to dilute and wash out the irritant. That reflex flush also dilutes the drug and shortens contact time. It does not cause dry eyes or true blurred vision as the first response. Big pH mismatch = sting = reflex tears."}'),
  ('780c66f6-22','{"options": ["Lipase", "CYP3A4", "CYP450", "Amylase"], "correct": 2, "explanation": "Phase I metabolism (oxidation, reduction, hydrolysis) is dominated by the cytochrome P450 (CYP450) enzyme SYSTEM in the liver. CYP3A4 is the single most abundant individual isoform, but it is a MEMBER of the CYP450 system, so the ''system'' answer is CYP450. Lipase and amylase are digestive enzymes, not drug-metabolizing. System = CYP450; biggest single member = CYP3A4."}'),
  ('8710604e-24','{"options": ["Bloody stools", "Myelosuppressions", "Difficulty to ingest food due to mucosites", "Nausea and vomiting"], "correct": 1, "explanation": "As in the earlier duplicate, myelosuppression is the most life-threatening chemotherapy toxicity: neutropenia opens the door to fatal infection and thrombocytopenia to serious bleeding. Bloody stools, mucositis, and nausea/vomiting are morbid but rarely the direct cause of death. Bone-marrow suppression is the dose-limiting, potentially fatal effect."}'),
  ('b1f8e5ba-2m','{"options": ["nicotinic effect", "cholinesterase effect", "muscarinic effect", "ganglionic blocking"], "correct": 2, "explanation": "At autonomic EFFECTOR organs (heart, glands, smooth muscle, the targets of postganglionic parasympathetic fibers), acetylcholine acts on MUSCARINIC receptors, so this is a muscarinic effect. Nicotinic effects occur at autonomic GANGLIA and the neuromuscular junction, cholinesterase is the enzyme that degrades ACh (not a receptor effect), and ganglionic blocking is the opposite of stimulation. Effector organ = muscarinic; ganglion/muscle = nicotinic."}'),
  ('3c0b700d-4y','{"options": ["Moderate paralysis of the face", "Fever aches and chills", "Difficulty swallowing, ptosis, and blurred vision", "Spasms and pain on the face"], "correct": 2, "explanation": "Difficulty swallowing, drooping lids (ptosis), and blurred vision signal that the botulinum toxin has SPREAD beyond the injection site toward systemic botulism, a medical emergency threatening the airway, so it must be reported at once. Local facial paralysis is the intended effect, and mild fever/soreness at the site is expected. Distant weakness (swallow, lids, eyes) = toxin spread = urgent."}'),
  ('a01ffab2-23','{"options": ["Oxybuprocaine", "Benoxinate", "Tetracaine", "Lidocaine"], "correct": 3, "explanation": "Trap item: oxybuprocaine and benoxinate are the SAME drug (two names for the same ester anesthetic), and together with tetracaine they are ester-type TOPICAL ocular anesthetics. Lidocaine is the odd one out as an AMIDE-type anesthetic used mainly by injection, so if the group means ''topical ester ocular anesthetics,'' lidocaine does not belong. VERIFY: strictly all four are local anesthetics, so the item is loose; the intended answer keys on lidocaine being the non-topical/non-ester member."}'),
  ('1ae3c3a4-1r','{"options": ["exerts physiological effect to the body", "has natural chemical substance", "has endogenous molecules", "has effective man-made substance"], "correct": 2, "explanation": "A drug is by definition EXOGENOUS (taken from outside the body), so calling it ''endogenous molecules'' is the incorrect statement. Drugs do exert physiological effects, and they can be natural (plant/animal-derived) or man-made (synthetic). Endogenous substances (like our own hormones) become ''drugs'' only when given from outside. Drug = from outside, not made by the body."}'),
  ('1a930505-22','{"options": ["Pseudomonas aeruginosa", "Candida albicans", "Staphylococcus aureus", "Acanthamoeba"], "correct": 3, "explanation": "Homemade saline (salt tablets in tap/well water) is the classic source of ACANTHAMOEBA, a free-living water amoeba that causes a painful, sight-threatening keratitis in contact-lens wearers. This history is exactly why homemade saline was banned for lens care. Pseudomonas is more tied to commercial fluorescein/water, and Candida/Staph are not the homemade-saline signature. Homemade saline + tap water = Acanthamoeba."}'),
  ('e49b4100-1y','{"options": ["modified drug", "prodrug", "exipient", "enteric coated"], "correct": 1, "explanation": "A prodrug is given in an inactive or weakly active form and is converted by the body''s metabolism into the ACTIVE metabolite that does the work (for example dipivefrin to epinephrine, or enalapril to enalaprilat). An excipient is an inert filler, enteric coating just delays where a tablet dissolves, and ''modified drug'' is vague. Prodrug = activated after you take it."}'),
  ('80808dbe-1l','{"options": ["red blood cells", "CD4+ T lymphocytes", "gonadocytes", "islet cells"], "correct": 1, "explanation": "HIV targets cells bearing the CD4 receptor, above all CD4+ T-helper lymphocytes, so the cell that IS affected (the EXCEPT to ''not affected'') is the CD4+ T lymphocyte. Red blood cells lack a nucleus and CD4, gonadocytes and islet cells are not primary HIV targets. HIV homes to CD4 = helper T cells."}'),
  ('4721bdce-1q','{"options": ["Due to proliferation", "Loss of pericytes", "Endothelial damage", "Basement membrane thickening"], "correct": 1, "explanation": "The inner blood-retinal barrier depends on retinal capillary endothelial tight junctions that are supported by PERICYTES. In diabetic retinopathy, the earliest lesion is selective pericyte loss, which weakens the wall, produces microaneurysms, and lets the barrier leak. Proliferation is a later (neovascular) stage, and basement-membrane thickening is a related change but not the trigger. VERIFY: ''endothelial damage'' is also a defensible answer since the tight junctions are endothelial, so confirm the intended key. Earliest DR change = pericyte dropout."}'),
  ('18a6bb9a-4w','{"options": ["Liver disorder", "Gout", "Kidney failure", "Spleen dysfunction"], "correct": 1, "explanation": "Joint pain plus elevated serum urate and uric-acid deposition is textbook GOUT, where monosodium urate crystals precipitate in joints and trigger acute arthritis (classically the big toe, but any joint can be hit). Liver, kidney, and spleen disorders do not present this urate-driven joint picture as the primary diagnosis. High uric acid + hot painful joint = gout."}'),
  ('b0d6f13f-1y','{"options": ["2% Homatropine", "1% Thymoxamine", "2% cocaine", "1% hydroxyamphetamine"], "correct": 2, "explanation": "The cocaine test is the SCREENING test for Horner''s: cocaine blocks norepinephrine reuptake, so a normal pupil dilates while a Horner''s pupil (deficient norepinephrine release) fails to dilate. Hydroxyamphetamine is the LOCALIZING (follow-up) test that separates preganglionic from postganglionic lesions, not the screen. Homatropine and thymoxamine are not diagnostic here. VERIFY: cocaine is usually 4% to 10% for this test, so the ''2%'' figure may be a source typo. Cocaine screens; hydroxyamphetamine localizes."}'),
  ('4376037d-2b','{"options": ["Hypertension", "Congestive heart failure", "Bronchial asthma", "Myocardial infarction"], "correct": 2, "explanation": "Phenylephrine is an alpha-1 sympathomimetic, so its cardiovascular cautions are hypertension, congestive heart failure, and myocardial infarction (it can spike blood pressure). BRONCHIAL ASTHMA is not a phenylephrine contraindication (that caution belongs to beta-blockers), so it is the NOT-included one. Match phenylephrine to heart/BP risks, not the airway."}'),
  ('96ace0b4-19','{"options": ["stomach", "large intestine", "small intestine", "liver"], "correct": 2, "explanation": "A weak BASE stays un-ionized (and therefore membrane-permeable) in an ALKALINE environment, so it is absorbed best in the small intestine, whose pH is near neutral-to-alkaline and whose huge surface area dominates absorption anyway. Weak ACIDS are the ones favored by the acidic stomach. The liver metabolizes, it does not absorb from the gut lumen. Bases like it basic: small intestine."}'),
  ('7e72dce9-26','{"options": ["LD 50", "Ceiling dose", "Potency", "Therapeutic index"], "correct": 2, "explanation": "The dose that yields half of a drug''s maximal effect is the ED50 (median effective dose), and ED50 is the direct measure of POTENCY (a lower ED50 means more potent). LD50 is the median LETHAL dose, the ceiling dose is where more drug gives no further effect (efficacy plateau), and therapeutic index is the LD50/ED50 safety ratio. VERIFY: the precise term is ED50; among the choices, potency is the concept it defines. Half-max effect dose = ED50 = potency yardstick."}'),
  ('745a674b-1c','{"options": ["Increasing preload and reducing after load", "Reducing preload and increasing after load", "Reducing preload only", "Increasing preload only"], "correct": 2, "explanation": "Nitroglycerin is mainly a VENODILATOR: pooling blood in the veins REDUCES preload (venous return), so the heart does less work and needs less oxygen, relieving angina. At higher doses it adds mild arterial dilation (some afterload reduction), but the board-level mechanism is preload reduction. It never increases preload or afterload. Nitrates = venodilate = drop preload = less cardiac oxygen demand."}'),
  ('4545632a-3g','{"options": ["Peak blood sample", "Gastric fluid at the time of symptoms", "Urine at the time of symptoms", "Trough blood sample"], "correct": 0, "explanation": "When TOXICITY is suspected, you want the PEAK blood level, drawn near the time of symptoms, because that is when the concentration is highest and most likely to confirm a toxic level. Trough levels are for checking that you are staying above the minimum EFFECTIVE level (efficacy), not for catching toxicity. Gastric fluid and urine are less direct for a blood-borne toxic level. Toxicity check = peak; efficacy check = trough."}'),
  ('2520d73a-26','{"options": ["mistakes", "all of these", "lapses", "slips"], "correct": 1, "explanation": "Human-error theory classifies prescribing errors into slips (attention failures during a routine action), lapses (memory failures), and mistakes (flawed knowledge/planning), so ALL OF THESE are sources of prescription error. Since each of the other three is a genuine error type, the inclusive answer is correct. Slips, lapses, and mistakes are the standard error triad."}'),
  ('59d0670a-1u','{"options": ["congestive heart failure", "myocardial infarction", "hypertension", "bronchial asthma"], "correct": 3, "explanation": "Same principle as the earlier phenylephrine item: as an alpha-1 pressor, phenylephrine is contraindicated in congestive heart failure, myocardial infarction, and hypertension, but BRONCHIAL ASTHMA is not on its contraindication list (asthma is the beta-blocker caution). So bronchial asthma is the EXCEPT. Phenylephrine cautions track the heart and blood pressure."}'),
  ('94e3536d-3p','{"options": ["blood urea nitrogen", "creatinine clearance", "glomerular filtration rate", "renal clearance"], "correct": 2, "explanation": "Glomerular filtration rate (GFR) is the single best overall index of kidney function, so it is the most accurate answer conceptually. In practice GFR is estimated by CREATININE CLEARANCE, which is why some keys mark creatinine clearance instead. Blood urea nitrogen is influenced by diet, hydration, and protein breakdown, so it is the least specific. VERIFY: GFR vs creatinine clearance depends on whether the key wants the parameter or the practical test. BUN is the weakest choice either way."}'),
  ('7c5c5582-1l','{"options": ["Ionized drugs", "Highly protein bound drugs", "Lipid-soluble drugs", "Water-soluble drugs"], "correct": 2, "explanation": "The blood-brain barrier is a tight lipid membrane, so only LIPID-SOLUBLE (non-polar, un-ionized, free) drugs cross it readily. Ionized (charged) drugs, highly protein-bound drugs (the bound fraction is too big to cross), and water-soluble drugs are all held back. Fat-soluble and free = gets into the brain."}'),
  ('e7e5e6c9-3h','{"options": ["increase lacrimal secretion", "dry eyes syndrome", "normal tear film", "blockage at lacrimal passage"], "correct": 3, "explanation": "If irrigating saline brings back fluid still HEAVILY stained with the fluorescein instilled minutes earlier, the dye had been sitting POOLED in the sac instead of draining, and it regurgitates on lavage, pointing to obstruction of the lacrimal passage. In a fully patent system the dye would already have cleared to the nose, so the return would be scant or clear. VERIFY: some interpret ''recovered stained fluid reaching the nose'' as proof of patency (a positive Jones), so confirm which scenario your key intends. Pooled/regurgitated stained fluid = blocked drainage."}'),
  ('af6f8a4d-1l','{"options": ["Intrinsic factor", "Water insoluble", "Pernicious anemia", "Schilling test"], "correct": 1, "explanation": "Vitamin B12 is WATER-soluble, so ''water insoluble'' is the false/unassociated statement. The genuine B12 associations are intrinsic factor (needed for its absorption in the ileum), pernicious anemia (the megaloblastic anemia from B12 deficiency), and the Schilling test (the classic assay of B12 absorption). All B vitamins and vitamin C are water-soluble; the fat-soluble ones are A, D, E, K."}'),
  ('1eb4780f-1p','{"options": ["band keratopathy", "papilledema", "macular degeneration", "optic neuritis"], "correct": 0, "explanation": "Thimerosal is a MERCURY-containing preservative, and chronic ocular exposure to mercurial preservatives deposits mercury in the cornea, producing band keratopathy (a horizontal band of calcific/mercurial change across the interpalpebral cornea). Thimerosal''s more common problem is delayed hypersensitivity conjunctivitis, but the classic PROLONGED-use structural effect is band keratopathy. It does not cause papilledema, macular degeneration, or optic neuritis. VERIFY: many texts stress the hypersensitivity reaction first. Mercury preservative + chronic use = band keratopathy."}'),
  ('c838a33f-2s','{"options": ["Cycloplegics", "Diamox", "Mydriatics", "Miotics"], "correct": 3, "explanation": "Miotics (pilocarpine) contract the iris sphincter and pull the peripheral iris away from the drainage angle, which OPENS/deepens the angle and stretches the trabecular outflow channels to boost aqueous drainage, the basis of their use in angle-closure glaucoma. Cycloplegics and mydriatics dilate the pupil and tend to CROWD the angle. Diamox (acetazolamide) reduces aqueous production rather than acting mechanically on the angle. VERIFY: the item''s wording is awkward; the outflow-opening action points to miotics."}'),
  ('c1b3c5d1-18','{"options": ["Transcription", "Subscription", "Superscription", "Inscription"], "correct": 2, "explanation": "The Rx symbol (from Latin ''recipe,'' meaning ''take thou'') sits in the SUPERSCRIPTION, the heading of the prescription. The inscription names the drug and strength, the subscription gives dispensing/compounding directions to the pharmacist, and the transcription/signa is the patient instructions. Superscription = the Rx heading at the top."}'),
  ('3b62aa7e-1i','{"options": ["Subscription", "Transcription", "Superscription", "Inscription"], "correct": 0, "explanation": "The SUBSCRIPTION is the part of the prescription addressed to the pharmacist telling how to prepare/compound and how much to dispense. The superscription carries the Rx symbol, the inscription lists the drug and dose, and the transcription/signa is the directions to the patient. ''Sub'' = instructions below, to the pharmacist, on preparation."}'),
  ('ed0fd3cc-1o','{"options": ["Superscription", "Transcription", "Inscription", "Subscription"], "correct": 2, "explanation": "The INSCRIPTION is the body of the prescription that states the drug name and its dose/strength (what and how much). The superscription is the Rx heading, the subscription is the pharmacist''s dispensing instructions, and the transcription/signa is the patient''s directions. Inscription = the actual drug and amount."}'),
  ('49817bc3-2e','{"options": ["Sympathetics", "Miotics", "Anesthetics", "Anticholinergics"], "correct": 2, "explanation": "Measuring IOP by (Goldmann) applanation requires a topical ANESTHETIC, usually combined with fluorescein, so the cornea can be touched painlessly by the tonometer. Sympathetics/anticholinergics dilate the pupil and miotics constrict it, none of which is needed to read pressure. Tonometry prep = anesthetic (plus fluorescein)."}'),
  ('626b0427-24','{"options": ["Naphazoline hydrochloride", "Carbacol", "Cyclopentolate", "Atropine sulfate"], "correct": 0, "explanation": "Naphazoline is an alpha-adrenergic (sympathomimetic) agent, so it dilates via the sympathetic pathway (stimulating the iris dilator) and also whitens the eye by vasoconstriction. Cyclopentolate and atropine ALSO dilate, but they are antimuscarinics (parasympatholytics), not sympathomimetics. Carbachol is a cholinergic MIOTIC (constrictor). The only sympathomimetic here is naphazoline. Dilation by two roads: stimulate sympathetic (phenylephrine, naphazoline) OR block parasympathetic (atropine, cyclopentolate)."}'),
  ('01671f47-2t','{"options": ["Naphazoline", "Pontocaine", "Acetazolamide", "Atropine"], "correct": 1, "explanation": "Pontocaine is the trade name for tetracaine, a topical local anesthetic that numbs the corneal surface so a foreign body can be removed painlessly. Naphazoline is a decongestant/mydriatic, acetazolamide is an oral carbonic anhydrase inhibitor for IOP, and atropine is a cycloplegic. Pontocaine = tetracaine = surface anesthetic."}'),
  ('e63cebb2-2f','{"options": ["Atropine", "Homatropine", "Scopolamine", "Tropicamide"], "correct": 0, "explanation": "In a young child with accommodative esotropia, ATROPINE is the cycloplegic of choice because it gives the deepest, most complete cycloplegia, fully relaxing accommodation to reveal the total hyperopia driving the eso deviation. Homatropine and tropicamide give weaker/shorter cycloplegia that can miss latent hyperopia, and scopolamine has more central side effects in children. Young accommodative eso = full cycloplegia = atropine."}'),
  ('42b65753-3t','{"options": ["Homatropine", "Scopolamine", "Tropicamide", "Atropine"], "correct": 3, "explanation": "For amblyopia you need the MOST accurate, most complete cycloplegic refraction to catch every diopter of latent hyperopia, and atropine gives the maximal cycloplegia, so among these it is the BEST choice. Homatropine and tropicamide are weaker/incomplete, and scopolamine is used less in children. VERIFY: in real practice cyclopentolate is the usual cycloplegic for this age (long-acting atropine is often reserved for younger accommodative esotropes), but cyclopentolate is not offered, so atropine is the best listed option for completeness of cycloplegia."}'),
  ('07697507-y','{"options": ["Miotics are direct-acting cholinergics", "Anesthetics are anticholinergic agents", "Mydriatics are anticholinesterase agents", "Cycloplegics are anticholinergic agents"], "correct": 2, "explanation": "Anticholinesterases INCREASE acetylcholine, so they cause MIOSIS (they are miotics like echothiophate), which makes ''Mydriatics are anticholinesterase agents'' backwards and untrue: mydriatics are antimuscarinics or sympathomimetics. Cycloplegics are indeed anticholinergic (D true) and miotics do include direct cholinergics (A true). VERIFY: option B (''Anesthetics are anticholinergic agents'') is ALSO false (anesthetics block sodium channels), so this item has two wrong statements; the intended NOT TRUE is the mydriatic/anticholinesterase reversal. Anticholinesterase = miotic, never mydriatic."}'),
  ('9c84071f-1k','{"options": ["Neither cortisol nor aldosterone", "Cortisol", "Both cortisol and aldosterone", "Aldosterone"], "correct": 3, "explanation": "Angiotensin II acts on the adrenal zona glomerulosa to release ALDOSTERONE, the salt-retaining mineralocorticoid, as the final step of the renin-angiotensin-aldosterone system. Cortisol (a glucocorticoid from the zona fasciculata) is driven mainly by ACTH, not angiotensin II. RAAS ends in aldosterone."}'),
  ('3e0deccd-1o','{"options": ["Both cortisol and aldosterone", "Neither cortisol nor aldosterone", "Cortisol", "Aldosterone"], "correct": 0, "explanation": "Both cortisol and aldosterone are STEROID hormones that use intracellular (nuclear) receptors; once bound, the hormone-receptor complex uses its DNA-binding domain to switch genes on or off. Because they share the steroid mechanism, BOTH have receptors with a DNA-binding domain. Steroid hormones talk directly to DNA."}'),
  ('bfa11208-1z','{"options": ["Cortisol", "Neither cortisol nor aldosterone", "Aldosterone", "Both cortisol and aldosterone"], "correct": 1, "explanation": "Steroid hormones act through intracellular receptors and gene transcription, NOT through membrane-bound second-messenger systems (cAMP, IP3, calcium), so NEITHER cortisol nor aldosterone works via a second messenger. Second messengers are the tool of peptide/amine hormones (like epinephrine or glucagon) that cannot enter the cell. Steroids skip second messengers and go to the nucleus."}'),
  ('277e3375-11','{"options": ["Phenobarbital", "Morphine", "Demerol", "Codeine"], "correct": 3, "explanation": "Codeine is the classic ANTITUSSIVE, acting on the medullary cough center to suppress cough at doses lower than needed for analgesia. Morphine and Demerol (meperidine) are opioids used mainly for pain, and phenobarbital is a barbiturate sedative/anticonvulsant. Codeine = cough."}'),
  ('1e8e72d0-1m','{"options": ["Morphine", "Codeine", "Demerol", "Phenobarbital"], "correct": 0, "explanation": "Morphine is the prototype respiratory depressant: it directly blunts the medullary response to carbon dioxide, decreasing both the RATE and DEPTH of breathing, which is the classic cause of death in opioid overdose. The other opioids depress respiration too, but morphine is the archetype the item is matching (and phenobarbital depresses respiration mainly at toxic doses). Opioid overdose kills by respiratory depression, morphine first."}'),
  ('de64e480-27','{"options": ["Phenobarbital", "Demerol", "Morphine", "Codeine"], "correct": 2, "explanation": "Morphine is used in acute (cardiogenic) pulmonary edema: it venodilates to drop preload, relieves the intense air-hunger/anxiety, and reduces the work of breathing. That combined anti-anxiety and preload-reducing action is why morphine, not phenobarbital, Demerol, or codeine, is the matched answer. Morphine in flash pulmonary edema calms the patient and unloads the heart."}'),
  ('98272377-1n','{"options": ["Optic neuritis", "Nail pigmentation", "Diarrhea", "Nephritis"], "correct": 1, "explanation": "In this matching set the distinctive antiviral effect is NAIL (and skin) PIGMENTATION, the hyperpigmentation classically caused by the antiretroviral zidovudine (AZT). That leaves optic neuritis for ethambutol and diarrhea for antibiotics in the companion items. VERIFY: acyclovir-type antivirals also famously cause NEPHRITIS/crystalluria, so nephritis is a defensible antiviral answer too; the item keys on nail pigmentation to keep a clean one-to-one match. AZT = nail/skin darkening."}'),
  ('124000cf-2a','{"options": ["Diarrhea", "Nail pigmentation", "Mydriasis", "Optic neuritis"], "correct": 3, "explanation": "Ethambutol''s signature toxicity is OPTIC NEURITIS (retrobulbar), causing decreased acuity and red-green color-vision loss, which is why vision is monitored during TB therapy. It does not characteristically cause diarrhea, nail pigmentation, or mydriasis. Ethambutol = Eye (optic neuritis); memory: ''ethambutol affects the EYE.''"}'),
  ('26c4990a-15','{"options": ["Nail pigmentation", "Mydriasis", "Optic neuritis", "Diarrhea"], "correct": 3, "explanation": "Broad-spectrum antibiotics disrupt normal gut flora, commonly causing antibiotic-associated DIARRHEA (up to and including Clostridioides difficile colitis). Nail pigmentation points to antivirals (AZT), optic neuritis to ethambutol, and mydriasis to antimuscarinics. Antibiotics wipe out gut flora = diarrhea."}'),
  ('e9a78316-25','{"options": ["Tonometry", "Jones I Test", "Tear Break-Up Test", "Angiography"], "correct": 1, "explanation": "The Jones I (dye) test checks whether the nasolacrimal DRAINAGE passage is open: fluorescein is instilled and, if patent, dye is recovered from the nose within a few minutes. Tonometry measures IOP, TBUT measures tear-film stability, and angiography images blood vessels. Jones = drainage patency."}'),
  ('74edbef8-2p','{"options": ["Tear Break-Up Test", "Tonometry", "Angiography", "Jones I Test"], "correct": 0, "explanation": "The Tear Break-Up Time depends on the innermost MUCIN layer that lets the tear film wet and cling to the cornea; when mucin is deficient the film destabilizes and breaks up quickly (short TBUT), so TBUT is the test for mucin-deficiency dry eye. Tonometry (IOP), angiography (vessels), and Jones (drainage) do not assess mucin. Short TBUT = unstable film = mucin problem."}'),
  ('40b96d89-3e','{"options": ["Tear Break-Up Test", "Jones I Test", "Angiography", "Tonometry"], "correct": 2, "explanation": "Fluorescein ANGIOGRAPHY photographs the dye as it transits the retinal and choroidal vessels, revealing blockages, leakage, and hemorrhage patterns. TBUT and Jones are tear/drainage tests, and tonometry measures pressure. To map retinal vessels and leaks, use angiography."}'),
  ('aceac410-50','{"options": ["II", "IV", "III", "I"], "correct": 3, "explanation": "Sorbic acid is a PRESERVATIVE (item I): it is a milder, less allergenic antimicrobial preservative used in contact-lens solutions in place of thimerosal. So its function matches I, which is option D here. It is not a viscosity agent (II), tonicity agent (III), or pH adjuster (IV). Sorbic acid = gentle preservative."}'),
  ('f1751c91-2x','{"options": ["III", "IV", "I", "II"], "correct": 2, "explanation": "As in the paired item, sorbic acid is a PRESERVATIVE, which is item I, printed here as option C. It preserves the solution by inhibiting microbial growth and is favored for being less sensitizing than mercurial preservatives. It does not thicken (II), set tonicity (III), or buffer pH (IV). Sorbic acid = preservative (I)."}'),
  ('4bb4a241-44','{"options": ["III", "II", "I", "IV"], "correct": 1, "explanation": "Methylcellulose is a VISCOSITY (thickening/wetting) agent, item II, shown here as option B. Raising viscosity makes the solution cling and lubricate, prolonging contact and comfort. It is not a preservative (I), tonicity agent (III), or pH buffer (IV). Cellulose thickens = viscosity agent."}'),
  ('78095cc3-52','{"options": ["II", "IV", "I", "III"], "correct": 0, "explanation": "The physical breakup of a tablet/capsule into smaller fragments is DISINTEGRATION, item II, option A here. It is the first step after swallowing, before dissolution (I) turns the fragments into solution, absorption (IV) moves drug into blood, and biotransformation (III) metabolizes it. Sequence: disintegration then dissolution then absorption then biotransformation."}'),
  ('e364daf4-4l','{"options": ["III", "IV", "I", "II"], "correct": 2, "explanation": "Once a tablet has disintegrated, DISSOLUTION (item I, option C here) is the dissolving of those particles into the GI fluid so the drug is in solution and ready to be absorbed. Disintegration (II) precedes it, absorption (IV) follows, and biotransformation (III) is later hepatic metabolism. Dissolve before you absorb: dissolution is item I."}'),
  ('24ae13df-4i','{"options": ["I", "III", "II", "IV"], "correct": 3, "explanation": "Movement of dissolved drug from the gut lumen into the blood/body fluids is ABSORPTION, item IV, option D here. Dissolution (I) and disintegration (II) prepare the drug, and biotransformation (III) alters it after absorption. Crossing the gut wall into the body = absorption (IV)."}'),
  ('2ab4f596-3n','{"options": ["at 10:20AM", "at 10:40 AM", "at 12 noon", "at 2:00 PM"], "correct": 3, "explanation": "0.5% Tropicamide''s mydriasis/cycloplegia lasts about 4 to 6 hours, so a pupil dilated at 10 AM recovers its light response around 2:00 PM (about 4 hours later). At 10:20 and 10:40 the drop is just reaching peak effect, and at 12 noon (2 hours) the pupil is still dilated. Tropicamide is the shortest-acting mydriatic (recovery in hours), unlike atropine (days). This mirrors the Set 1 item keyed at 8 AM to noon, the same 4-hour recovery."}'),
  ('5e44e1e6-1t','{"options": ["prevent anterior uveitis", "accommodative esotropia", "cycloplegic refraction", "angle closure glaucoma"], "correct": 3, "explanation": "Atropine is a mydriatic/cycloplegic and is CONTRAINDICATED in angle-closure glaucoma, because dilating the pupil crowds the drainage angle and can trigger an acute pressure crisis, so angle-closure glaucoma is the EXCEPT. Its legitimate uses include cyclorefraction, controlling accommodative esotropia, and (as a cycloplegic) resting the eye and breaking/preventing synechiae in anterior uveitis. Never dilate an eye at risk of angle closure."}'),
  ('7710f8d9-32','{"options": ["Scopolamine", "Atropine", "Homatropine", "Tropicamide"], "correct": 1, "explanation": "As with the earlier young-child esotropia item, ATROPINE is the agent of choice for a 5-year-old suspected of accommodative esotropia because it delivers the deepest cycloplegia needed to uncover the full hyperopia driving the crossing. Homatropine and tropicamide are too weak/short to fully relax a child''s strong accommodation, and scopolamine carries more CNS effect. Young accommodative eso = atropine for complete cycloplegia."}'),
  ('6f7ae01c-z','{"options": ["idoxuridine", "rimantidine", "amantidine", "ribavirine"], "correct": 2, "explanation": "Amantadine (and its relative rimantadine) blocks the M2 ion channel of influenza A, the classic drug for the common flu. Idoxuridine treats herpes, ribavirin treats RSV/hepatitis C."}'),
  ('7e07106d-14','{"options": ["spectinomycin", "streptomycin", "kanamycin", "neomycin"], "correct": 2, "explanation": "Among injectable anti-TB agents, kanamycin is a second-line IM drug (with amikacin and capreomycin), used when streptomycin or oral drugs fail. Streptomycin is the older first-line injectable."}'),
  ('a26ae125-1f','{"options": ["local ester anesthesia", "CNS stimulant", "mydriatic agent", "sympathomimetic agent"], "correct": 3, "explanation": "Cocaine is in fact an ester local anesthetic, a CNS stimulant, and (by blocking norepinephrine reuptake) an indirect sympathomimetic that dilates the pupil, so every option describes a real effect and the item is defective. VERIFY: the likely intended ''exception'' is sympathomimetic agent, treated as a mechanism term rather than a listed effect. All four are genuinely true of cocaine."}'),
  ('9dffccb0-z','{"options": ["palliative drug", "prophylactic drug", "protective drug", "curative medication"], "correct": 3, "explanation": "Metformin directly treats the disease process (hyperglycemia in type 2 diabetes), so it is classed as a curative/therapeutic drug rather than mere symptom relief. Contrast Q29, where mefenamic acid only relieves the headache symptom (palliative). VERIFY: since diabetes is chronic and not truly cured, some keys label this palliative, so confirm the intended class."}'),
  ('c259bdeb-o','{"options": ["MD can prescribe controlled substance 2 prohibited drugs", "MD can prescribe all controlled substances prohibited drugs", "MD can prescribe controlled substance 2-5 prohibited drugs", "MD can prescribe all controlled substances prohibited drugs even without prescription"], "correct": 1, "explanation": "The PDEA S2 license authorizes a physician to prescribe controlled/dangerous (prohibited) drugs. Option d is wrong because a prescription is always still required. VERIFY: the exact wording of the schedule range varies by reviewer, so confirm whether the key wants ''all controlled substances'' or a specific schedule range."}'),
  ('93a392b5-29','{"options": ["30 minutes", "60 minutes", "15 seconds", "20 minutes"], "correct": 1, "explanation": "Full corneal sensitivity returns roughly 60 minutes after a drop of benoxinate, even though the working anesthesia lasts only about 15 to 20 minutes. The 15-second option is onset, not recovery. VERIFY: recovery time varies by source (some cite about 30 minutes), so confirm the value your reviewer uses."}'),
  ('f63f5c2f-28','{"options": ["benzalkonium chloride", "ethylene diamine tetra acetate", "benoxinate", "bicarbonate"], "correct": 0, "explanation": "The antimicrobial preservative in Fluress guards against Pseudomonas aeruginosa contamination of fluorescein, and among these options benzalkonium chloride is the preservative. EDTA is a chelator, benoxinate the anesthetic, bicarbonate a buffer. VERIFY: actual Fluress is preserved with chlorobutanol, which is not listed, so confirm the intended answer."}'),
  ('220d7dc7-31','{"options": ["collagen fibrils", "glycosaminoglycans", "phospholipids", "keratocytes"], "correct": 1, "explanation": "The corneal stroma''s GLYCOSAMINOGLYCANS (GAGs/proteoglycans) carry fixed NEGATIVE charges (anions) that bind cations and water, governing stromal HYDRATION (and the swelling pressure the endothelium counteracts). Collagen gives transparency/strength; keratocytes maintain matrix. Hydration control = GAGs."}'),
  ('0858e3a8-2k','{"options": ["polyhedral cells", "surface cells", "basal cells", "all of the above"], "correct": 1, "explanation": "The corneal SURFACE (squamous) epithelial cells are flat, spindle/polygonal cells with MICROVILLI that hold the tear film and act as a smooth convex mirror (the first refracting surface). Basal cells divide; polyhedral (wing) cells are intermediate. Outer mirror layer = surface cells."}'),
  ('350a2447-1r','{"options": ["condensation of RPE", "rod and cone fibers", "fibers of Mueller cells", "axons of ganglion cells"], "correct": 2, "explanation": "MÜLLER CELL fibers (radial glia) form both the external and internal LIMITING MEMBRANES of the retina (their footplates/junctions). RPE, photoreceptor fibers, and ganglion axons form other layers. Limiting membranes = Müller cell fibers."}'),
  ('59b5f5de-1p','{"options": ["ora serrata", "macula lutea", "optic disc", "physiologic cup"], "correct": 1, "explanation": "The MACULA LUTEA has multiple (5-7) layers of GANGLION cells (vs a single layer peripherally) — supporting high-acuity central vision. Ora serrata/disc/cup lack this. Thick ganglion layer = macula."}'),
  ('6446b1e5-10','{"options": ["oculomotor nerve", "sympathetic nerve facial nerve", "trigeminal nerve"], "correct": 0, "explanation": "[Source-flagged.] The CILIARY MUSCLE receives parasympathetic MOTOR innervation from the OCULOMOTOR nerve (CN III, via the ciliary ganglion/short ciliary nerves) — driving accommodation. Sympathetics relax it; CN V is sensory. Ciliary muscle = CN III (parasympathetic). Cross-link: accommodation/miosis are cholinergic (CN III)."}'),
  ('94784d36-ct','{"options": ["palliative.", "protective.", "diagnostic.", "curative."], "correct": 3, "explanation": "By USE, an antibiotic like CLARITHROMYCIN given to treat the (bacterial) pneumonia is CURATIVE — it eradicates the causative organism. Palliative = symptom relief; protective = prevention; diagnostic = aids dx. Antibiotic that cures the infection = curative."}'),
  ('f294d63b-2d','{"options": ["palliative", "diagnostic", "protective", "curative"], "correct": 0, "explanation": "PARACETAMOL (antipyretic/analgesic) for the FEVER is PALLIATIVE — it relieves the symptom (fever/pain) without curing the underlying pneumonia. Symptom relief = palliative. Contrast the curative antibiotic (Q6)."}'),
  ('496ca3f8-1z','{"options": ["paracetamol.", "phenobarbital.", "amoxicillin .", "mefenamic acid."], "correct": 0, "explanation": "PARACETAMOL (acetaminophen) is the most commonly ABUSED/overused OTC medication (and a leading cause of accidental hepatotoxic overdose). Phenobarbital/clarithromycin are prescription; mefenamic acid less so. Most-abused OTC = paracetamol."}'),
  ('d52fb629-1t','{"options": ["paracetamol", "ibuprofen", "Clarithromycin", "ascorbic acid"], "correct": 2, "explanation": "CLARITHROMYCIN (a prescription macrolide antibiotic) is NON-OTC (Rx only). Paracetamol, ibuprofen, and ascorbic acid are OTC. Prescription-only here = clarithromycin."}'),
  ('5266d999-1p','{"options": ["N-acetyl-para amino Phenol", "acetaminophen", "N-acetyl butyl Bromide", "alpha tocopherol"], "correct": 1, "explanation": "Paracetamol''s international/US market name is ACETAMINOPHEN (same drug, N-acetyl-para-aminophenol chemically). ''N-acetyl-para-aminophenol'' is the chemical name, not the market name; alpha-tocopherol is vitamin E. Market name = acetaminophen."}'),
  ('fba2cc9a-by','{"options": ["intravenous injection", "subcutaneous injection", "sublingual route", "intramuscular injection"], "correct": 2, "explanation": "To IMMEDIATELY lower a hypertensive emergency, Clonidine is given by the rapid SUBLINGUAL route (fast absorption via oral mucosa, avoids first-pass) — used for quick BP reduction. IV/IM/SC are other routes; sublingual gives the immediate effect described. Rapid oral-mucosal route = sublingual."}'),
  ('2b57e1e6-n','{"options": ["palliative,", "diagnostic ,", "protective,", "curative,"], "correct": 2, "explanation": "Long-term oral antihypertensives (clonidine for ongoing control) are PROTECTIVE — they PREVENT complications by controlling a chronic condition (not curing it). Curative eradicates disease; palliative relieves symptoms. Chronic-control drug = protective."}'),
  ('424a4df5-z','{"options": ["intravenous injection", "subcutaneous injection", "sublingual route", "intramuscular injection"], "correct": 1, "explanation": "INSULIN is most commonly given SUBCUTANEOUSLY (SC) — slow steady absorption for daily glycemic control (IV reserved for emergencies/DKA). SC = the standard insulin route."}'),
  ('96eba519-g','{"options": ["palliative..", "diagnostic ..", "protective..", "curative.."], "correct": 2, "explanation": "INSULIN for lifelong diabetes control is PROTECTIVE — it controls a chronic disease and prevents complications, without curing diabetes. Chronic-control = protective (same class as the antihypertensives, Q12)."}'),
  ('92495195-k','{"options": ["palliative …", "diagnostic ..", "protective…", "curative…"], "correct": 2, "explanation": "TELMISARTAN (an ARB antihypertensive for lifelong BP control) is PROTECTIVE — chronic-disease control preventing cardiovascular complications. Long-term control drugs = protective."}'),
  ('6fadf6bf-18','{"options": ["palliative,,", "diagnostic ,,", "protective,,", "curative,,"], "correct": 2, "explanation": "Oral METOPROLOL (beta-blocker) for chronic hypertension is PROTECTIVE — controls BP long-term, preventing complications. Same use-class as the other lifelong antihypertensives. Chronic control = protective."}'),
  ('ce122ac0-4f','{"options": ["generic name", "chemical name", "generic drug", "propriety name"], "correct": 0, "explanation": "The GENERIC name designates the ACTIVE INGREDIENT of a drug product (the nonproprietary name of the actual therapeutic substance). The chemical name describes structure; proprietary/brand is the trademark; ''generic drug'' is a product. Active ingredient name = generic name."}'),
  ('9b8fae14-2a','{"options": ["pH of more than 7.5", "unionized form", "polar form", "uncharged form"], "correct": 2, "explanation": "EXCEPT (not a feature of lipid-soluble drug forms). Lipid-soluble drugs are UNIONIZED/UNCHARGED (cross membranes easily) and favored at appropriate pH. The POLAR form is water-soluble/ionized — the opposite — so ''polar form'' is the exception. Lipid-soluble = nonpolar, unionized, uncharged."}'),
  ('ce6e0fc0-1v','{"options": ["simple diffusion", "facilitated diffusion", "active transport", "phagocytosis"], "correct": 0, "explanation": "Lipid-soluble drugs are absorbed by SIMPLE (passive) DIFFUSION down their concentration gradient across the lipid membrane — no carrier or energy needed. Facilitated/active transport are for polar molecules. Lipid-soluble absorption = simple diffusion."}'),
  ('e00560c8-1b','{"options": ["carrier mediated mechanism", "requires energy", "movement is from higher to lower concentration", "absorbed drug in polar form"], "correct": 1, "explanation": "EXCEPT. Facilitated diffusion is carrier-mediated, moves DOWN the gradient (high→low), and handles polar drugs — but it does NOT require ENERGY (that''s active transport). So ''requires energy'' is the exception. Facilitated diffusion = carrier-mediated but passive (no ATP)."}'),
  ('456f17b0-1m','{"options": ["biotransformation", "bioavailability", "pharmacologic effects", "elimination"], "correct": 2, "explanation": "Pharmacologic EFFECTS do not belong to pharmacokinetics, effects are pharmacoDYNAMICS. Biotransformation, bioavailability, and elimination are all kinetic (ADME). Hint: anything about the drug''s ACTION/effect is dynamics, not kinetics."}'),
  ('6c2902ec-1g','{"options": ["pharmacologic effect", "side effect", "adverse effect", "untoward effect"], "correct": 2, "explanation": "An ADVERSE effect is a harmful, unintended effect — here from OVERDOSE (toxic, dose-related harm). A ''side effect'' is a predictable minor effect at normal dose; pharmacologic effect is the intended action. Overdose harm = adverse effect."}'),
  ('53d95ec3-13','{"options": ["active transport", "facilitated diffusion", "simple diffusion", "phagocytosis"], "correct": 0, "explanation": "SODIUM CHLORIDE (ions) is absorbed by ACTIVE TRANSPORT (carrier + energy, against/with gradients via pumps) — being charged/polar it can''t simply diffuse through lipid. Lipid-soluble drugs use simple diffusion (Q19). Ion transport = active transport."}'),
  ('55a14dc0-1w','{"options": ["lactating mammary glands", "lacrimal glands", "salivary glands", "sweat glands"], "correct": 0, "explanation": "The LACTATING MAMMARY glands excrete the highest drug concentration (lipophilic/basic drugs concentrate in breast milk) — a key concern for drugs in nursing mothers. Lacrimal/salivary/sweat excrete less. Highest drug excretion gland = lactating breast."}'),
  ('298e346e-13','{"options": ["active transport", "facilitated diffusion", "simple diffusion", "phagocytosis"], "correct": 2, "explanation": "PROPARACAINE (a lipophilic topical ester anesthetic) is absorbed by SIMPLE DIFFUSION across the corneal epithelium (lipid). Active/facilitated transport are for polar agents. Lipid-soluble anesthetic = simple diffusion."}'),
  ('94a5b812-1f','{"options": ["proparacaine", "alkaloids", "carbachol", "corticosteroids"], "correct": 2, "explanation": "EXCEPT (not highly lipid-soluble). Proparacaine, alkaloids, and corticosteroids are lipophilic; CARBACHOL is a quaternary, highly POLAR/charged molecule (poor lipid solubility, poor corneal penetration — needs BAK to penetrate, Q96). Carbachol = poorly lipid-soluble."}'),
  ('d2580f2c-2c','{"options": ["variance", "potency", "efficacy", "affinity"], "correct": 2, "explanation": "EFFICACY = the MAXIMUM effect a drug can produce regardless of dose (the ceiling of response). POTENCY = the dose needed for a given effect; affinity = receptor binding strength. Maximum achievable effect = efficacy."}'),
  ('13a15be0-28','{"options": ["lungs", "liver", "adrenal glands", "kidneys"], "correct": 2, "explanation": "EXCEPT (not a metabolism/excretion organ). The LIVER (metabolism) and KIDNEYS (excretion), and lungs (volatile excretion/some metabolism) handle drug clearance; the ADRENAL glands are endocrine, not clearance organs. Clearance = liver/kidney/lung; adrenal = exception."}'),
  ('1e72f78c-3e','{"options": ["maintenance dose", "continuos dose", "multiple dose", "loading dose"], "correct": 3, "explanation": "A LOADING dose is a large initial dose to rapidly reach therapeutic blood concentration at the start of therapy (then maintenance doses sustain it). Maintenance/continuous/multiple doses keep levels steady. Big first dose = loading dose."}'),
  ('37120945-2r','{"options": ["maintenance", "continuos dose", "multiple dose", "single dose"], "correct": 3, "explanation": "A single pre-extraction lidocaine gum injection is a SINGLE-DOSE regimen (one administration for one procedure). Maintenance/continuous/multiple imply repeated dosing. One-off = single dose."}'),
  ('315d6607-8m','{"options": ["tolerance", "tachyphylaxis", "developed immunity to med", "all of the above"], "correct": 1, "explanation": "Rapidly DIMINISHING response to repeated Salbutamol over hours = TACHYPHYLAXIS (acute, fast tolerance from receptor desensitization/down-regulation, e.g., beta-2). ''Tolerance'' is the broader/slower term; immunity is irrelevant. Fast acute loss of effect = tachyphylaxis."}'),
  ('3545ad11-2d','{"options": ["increasing the next doses", "shift to another medication to relieve attack", "increase the frequency of using the medication", "A & B only"], "correct": 3, "explanation": "Prevent Salbutamol tolerance by NOT escalating dose/frequency — instead use it appropriately and, if attacks persist, SHIFT to/add another agent (A & B): don''t just increase doses/frequency (which worsens desensitization). Avoid overuse + switch/add controller. Beta-agonist overuse → tachyphylaxis."}'),
  ('b7dc9b97-14','{"options": [".palliative", ".protective", ".diagnostic", ".curative"], "correct": 0, "explanation": "SALBUTAMOL (a rescue bronchodilator relieving the acute asthma symptom) is PALLIATIVE — symptom relief during an attack, not cure or long-term prevention. Reliever = palliative. (Controllers/preventers would be protective.)"}'),
  ('38666756-2r','{"options": ["posology", "toxicology", "pharmacognosy", "pharmacological calculation"], "correct": 2, "explanation": "PHARMACOGNOSY is the study of drugs from NATURAL sources (plants/leaves, etc.) — fitting the boiled-leaf/vapor folk remedy. Posology = dosing; toxicology = poisons; pharmaceutical calculation = math. Natural-source drugs = pharmacognosy."}'),
  ('eeb40433-bw','{"options": ["allergy to one of the component of CL solution", "CL she used in not FDA approved", "probably she failed to remove the CL at bedtime", "none of the above"], "correct": 0, "explanation": "Recurrent conjunctivitis only with a new CL solution containing multiple preservatives (BAK, thimerosal, chlorobutanol...) = ALLERGY/hypersensitivity to a component of the solution. Not non-FDA lenses or overnight wear by default. Solution-linked recurrent reaction = preservative allergy."}'),
  ('ec7dbbaa-f','{"options": ["A., palliative", "B., protective", "C., diagnostic", "D., curative"], "correct": 0, "explanation": "EYE MO (a decongestant/vasoconstrictor giving temporary redness relief) is PALLIATIVE — symptomatic relief only, not treating the cause. Temporary symptom relief = palliative. (Overuse risks rebound hyperemia.)"}'),
  ('78006c69-2v','{"options": ["Benzalkonium chloride", "thimerosal", "EDTA", "chlorobutanol"], "correct": 1, "explanation": "THIMEROSAL (a mercurial preservative) can cause sensitivity and, with calcium deposition at Bowman''s membrane, BAND KERATOPATHY (a leukoma/white opacity). BAK/EDTA/chlorobutanol have other roles. Thimerosal + calcium at Bowman''s = band keratopathy/leukoma."}'),
  ('abf3f4ea-29','{"options": ["Benzalkonium chloride", "thimerosal", "EDTA", "chlorobutanol"], "correct": 2, "explanation": "EDTA is added (a CHELATING agent) to bind calcium and PREVENT calcium deposition/band keratopathy from thimerosal solutions. BAK/chlorobutanol are preservatives. Anti-calcium chelator = EDTA. Cross-link: EDTA chelation (Q39)."}'),
  ('02cefb64-10','{"options": ["wetting agent.", "antibiotic .", "lubricate the eyes.", "chelating agent."], "correct": 3, "explanation": "EDTA combined with thimerosal acts as a CHELATING agent (binds di-/poly-valent cations like Ca²⁺/Mg²⁺), boosting preservative efficacy and preventing calcium deposits. Not a wetting/antibiotic/lubricant. EDTA = chelator."}'),
  ('521d7894-1c','{"options": ["wetting agent", "lubricate the eyes", "preservative", "chelating agent"], "correct": 2, "explanation": "In CL solutions, Benzalkonium chloride (BAK) functions as a WETTING agent/surfactant (and preservative) — it lowers surface tension to spread solution and disrupts microbes. [Note: BAK is classically a PRESERVATIVE/antimicrobial; the source emphasizes its wetting/surfactant action here.] BAK = surfactant-preservative."}'),
  ('eda2ea5c-p','{"options": ["diluent", "enhances drug penetration", "lubricate the eyes", "prevent calcium corneal deposits"], "correct": 1, "explanation": "BAK ENHANCES DRUG (corneal) PENETRATION by disrupting the epithelial barrier/tight junctions (surfactant action) — useful for poorly-penetrating drugs (e.g., carbachol, Q96) but toxic with chronic use. Penetration enhancer = BAK."}'),
  ('c847c376-w','{"options": ["wetting agent", "preservative", "lubricate the eyes", "chelating agent"], "correct": 1, "explanation": "THIMEROSAL''s role in CL solution is as a PRESERVATIVE (antimicrobial mercurial). Its downside is sensitivity/band keratopathy (Q37). Thimerosal = preservative."}'),
  ('20e768a0-1n','{"options": ["calcium deposition at Bowman’s membrane", "calcium deposition at corneal stroma", "corneal edema", "cataract formation"], "correct": 0, "explanation": "Thimerosal-related LEUKOMA arises from CALCIUM DEPOSITION at BOWMAN''S MEMBRANE = band keratopathy (a sub-epithelial calcific white opacity). Not stromal calcium, edema, or cataract. Mechanism = Ca at Bowman''s. Cross-link: prevent with EDTA (Q38)."}'),
  ('53e90677-21','{"options": ["glaucoma", "Band keratopathy", "diabetic retinopathy", "cataract"], "correct": 1, "explanation": "Calcium deposition in BOWMAN''S membrane of the cornea = BAND KERATOPATHY (a horizontal interpalpebral calcific band). Not glaucoma/retinopathy/cataract. Ca at Bowman''s = band keratopathy."}'),
  ('f292b1a7-1x','{"options": ["anti-mycotic agent", "anti-helminthic agents", "anti-neoplastic agent", "antibiotic"], "correct": 2, "explanation": "Infiltrating ductal CARCINOMA (cancer) is treated with ANTI-NEOPLASTIC (chemotherapeutic) agents. Anti-mycotic/anti-helminthic/antibiotics target infections. Cancer drug = antineoplastic."}'),
  ('5954cbc4-1b','{"options": ["-diagnostic", "curative"], "correct": 1, "explanation": "Chemotherapy for infiltrating ductal carcinoma is given with CURATIVE intent (to eradicate the malignancy) — though regimens can also be palliative in advanced disease. Use-class for treating the cancer = curative. [Extraction missed the marked option; answer = curative.]"}'),
  ('bdaaa398-38','{"options": ["anti-mycotic agent", "anti-neoplastic agent", "anti-helminthic agent", "antibiotic"], "correct": 0, "explanation": "Oral CANDIDIASIS (a fungal side effect of chemo immunosuppression) is treated with an ANTI-MYCOTIC (antifungal) agent (e.g., nystatin). Antineoplastic/anthelmintic/antibiotics don''t treat fungi. Fungus = antimycotic."}'),
  ('25fe2efd-29','{"options": ["palliative -", "diagnostic -", "protective-", "placebo-"], "correct": 3, "explanation": "An inert injection (distilled water/NSS) given for a psychosomatic reaction is a PLACEBO — no active drug, relying on the expectation/psychological effect. Not palliative/diagnostic/protective. Inert ''treatment'' = placebo."}'),
  ('e5d9ab6e-2f','{"options": ["ofloxacin", "tropicamide", "proparacaine", "fluorescein dye"], "correct": 0, "explanation": "EXCEPT (not a DPA). Philippine optometry DPAs (diagnostic pharmaceutical agents) include tropicamide (mydriatic), proparacaine (anesthetic), and fluorescein (dye). OFLOXACIN is a therapeutic ANTIBIOTIC (a TPA), not a diagnostic agent. DPAs = diagnostic only; ofloxacin = exception."}'),
  ('af3cbf1a-y','{"options": ["mydriasis and cycloplegia", "stain the ocular tissue", "local ester anesthesia", "destroy foreign bodies"], "correct": 0, "explanation": "TROPICAMIDE (antimuscarinic) produces MYDRIASIS and (weak, short) CYCLOPLEGIA for fundus exam/refraction. It doesn''t stain, anesthetize, or remove foreign bodies. Tropicamide = mydriatic + mild cycloplegic."}'),
  ('d4fa32a6-1g','{"options": ["phenylephrine", "pilocarpine", "tropicamide", "cyclopentolate"], "correct": 1, "explanation": "Does NOT cause mydriasis = answer. Phenylephrine, tropicamide, and cyclopentolate dilate; PILOCARPINE is a MIOTIC (cholinergic) — it CONSTRICTS the pupil. The miotic among DPAs/agents = pilocarpine. Cross-link: pilocarpine lowers IOP via miosis (Q89)."}'),
  ('32e993a1-1o','{"options": ["dispensing", "procurement", "preparation", "prescribing"], "correct": 3, "explanation": "NOT a pharmacist function = answer. Pharmacists dispense, procure, and prepare/compound medications — but PRESCRIBING is the physician''s/authorized prescriber''s role, not the pharmacist''s. Pharmacist ≠ prescriber."}'),
  ('0da69962-28','{"options": ["dispensing .", "inject medication", "instill medication", "prescribing."], "correct": 1, "explanation": "NOT a function of a DPA-licensed optometrist = answer. They prescribe, instill, and dispense diagnostic agents — but they do NOT INJECT medications (injection is outside the DPA scope). Optometrist DPA scope excludes injections."}'),
  ('5fae7dcc-2n','{"options": ["presence of foods at the stomach", "first pass effect", "lipid solubility of the medication", "amount of ingested water"], "correct": 3, "explanation": "EXCEPT (doesn''t cause time-effect variability). Paracetamol''s onset varies with stomach food, first-pass metabolism, and lipid solubility (absorption factors). The AMOUNT of water ingested has negligible effect on its time-action — the exception. Absorption variability ≠ water volume."}'),
  ('5feeedf9-2c','{"options": ["pruritic at the site of injection", ">2mm diameter from the marker to edge of erythema", "> 10mm diameter of erythema lesions", "no erythema after 30 minutes"], "correct": 3, "explanation": "EXCEPT (not a positive skin test sign). A POSITIVE allergy skin test shows pruritus, erythema/wheal >2 mm (or >10 mm) at the site. NO erythema after 30 minutes is a NEGATIVE result — the exception. Positive = wheal/flare; no reaction = negative."}'),
  ('18f1519d-1i','{"options": ["deltoid muscles", "vastus lateralis muscles", "gluteus muscles", "rectus abdominis"], "correct": 1, "explanation": "IM injection in the THIGH uses the VASTUS LATERALIS muscle (preferred in infants; large, safe). Deltoid = arm; gluteus = buttock. Thigh IM = vastus lateralis."}'),
  ('d84a22ff-1m','{"options": ["deltoid muscles", "gluteus muscles", "vastus lateralis muscles", "rectus abdominis"], "correct": 0, "explanation": "IM injection in the UPPER ARM uses the DELTOID muscle (common for vaccines). Thigh = vastus lateralis; buttock = gluteus. Arm IM = deltoid."}'),
  ('c9498ab5-1k','{"options": ["deltoid muscles", "gluteus muscles", "vastus lateralis muscles", "rectus abdominis"], "correct": 1, "explanation": "IM injection in the BUTTOCK uses the GLUTEUS (dorsogluteal/ventrogluteal) muscle for larger volumes. Deltoid = arm; vastus lateralis = thigh. Buttock IM = gluteus."}'),
  ('c145501d-2b','{"options": ["forearm", "thigh", "upper arm", "buttocks"], "correct": 3, "explanation": "EXCEPT (not a subcutaneous site). SC and IM both can use forearm, thigh, upper arm regions; the BUTTOCK is IM-only (deep gluteal), not a routine SC site. Buttock = IM, not SC."}'),
  ('bc1b96f4-21','{"options": ["intracardiac", "intraperitoneal", "intravenous", "subcutaneous"], "correct": 1, "explanation": "EXCEPT (not given at 45°). SC injections use ~45° (or 90° for short needles); IV and intracardiac use shallow/specific angles; the INTRAPERITONEAL route doesn''t use the 45° technique described. (SC classically ~45°.) Intraperitoneal = the exception here."}'),
  ('cc6de73b-2m','{"options": ["receptor", "bond", "bound form", "A & B only"], "correct": 3, "explanation": "For a drug to act it must reach the receptor AND BIND it (form a drug-receptor complex) — so ''receptor and bond'' (A & B). Affinity (binding) + the receptor target are both required to produce the effect. Action requires receptor + binding."}'),
  ('44646c00-1v','{"options": ["cell membrane", "cytoplasm", "nucleus", "cytoplasmic organelles"], "correct": 0, "explanation": "Most drug RECEPTORS sit on the CELL MEMBRANE (surface) — GPCRs, ion channels, enzyme-linked receptors. Intracellular (cytoplasm/nucleus) receptors exist for lipophilic hormones/steroids but are fewer. Common receptor site = cell membrane."}'),
  ('688828cb-1g','{"options": ["medication is not miscible to diluent that is why it has to be shake before usage", "medication is equally distributed to the diluent so no need to shake vigorously", "semisolid vehicle is lipid soluble & melts when it comes in contact with the eyes", "made of high viscosity acrylics to prolong the contact time of medication"], "correct": 0, "explanation": "A SUSPENSION has the drug NOT dissolved (immiscible particles) in the vehicle, so it must be SHAKEN before use to redistribute the particles. A solution is fully dissolved (homogeneous, no shaking). Shake-before-use = suspension."}'),
  ('d72daac2-33','{"options": ["cyanide", "ethylmercury", "oxalic acid", "boric acid"], "correct": 1, "explanation": "Thimerosal''s toxic metabolite is ETHYLMERCURY (organomercurial), which drives the allergic contact/sensitivity reactions (and the calcium/band keratopathy link). Not cyanide/oxalic/boric acid. Thimerosal → ethylmercury."}'),
  ('c975d9ab-1u','{"options": ["dehydration and electrolytes imbalance", "dry eyes", "secondary open angle glaucoma", "anterior sub-capsular lens opacity"], "correct": 1, "explanation": "Dry eyes. Diuretics like HCTZ reduce body fluid and tear volume, giving dry-eye symptoms on chronic use (HCTZ can also cause transient myopia and sulfa-type acute angle closure). The ''anterior subcapsular opacity'' distractor belongs to chlorpromazine, and posterior subcapsular belongs to steroids. Hint: diuretic = less fluid everywhere, including the tear film."}'),
  ('89caf6a9-29','{"options": ["secondary open angle glaucoma", "posterior sub-capsular lens opacity", "Hyperopia", "anterior uveitis"], "correct": 1, "explanation": "Posterior sub-capsular cataract. Statins (simvastatin) have been linked to lens opacities, classically posterior subcapsular. Not glaucoma, not uveitis, not simple hyperopia. Hint: PSC cataract is the ''drug cataract'' pattern, shared by steroids and statins."}'),
  ('0e20d254-30','{"options": ["it may block the trabecular meshwork which may cause secondary open angle glaucoma at high concentration and large amount", "it will damage the corneal endothelium and anterior lens epithelium resulting to influx of water from aqueous humor at high concentration and large amount", "it may cause inflammation to iris and ciliary body which may result to anterior and posterior synechiae", "all are possible answers"], "correct": 1, "explanation": "Intracameral TRYPAN BLUE must be small/dilute because at high concentration/volume it DAMAGES the CORNEAL ENDOTHELIUM and anterior lens epithelium, drawing water in (corneal/lens edema). It''s used sparingly to stain the capsule. Trypan blue toxicity = endothelial/epithelial damage."}'),
  ('0b02b200-2g','{"options": ["additive", "synergism", "Antagonism", "potentiation"], "correct": 1, "explanation": "Synergism. Apraclonidine (alpha-2 agonist, lowers aqueous production) plus pilocarpine (cholinergic, increases outflow) act by DIFFERENT mechanisms, so IOP lowering is greater than the sum. Hint: same rule as Q47, different-mechanism glaucoma combos = synergism."}'),
  ('3cb48bc9-2m','{"options": ["enhance aqueous humor outflow by opening the trabecular meshwork", "enhance aqueous humor outflow and decrease aqueous humor secretions", "decrease aqueous humor secretion from the ciliary process", "does not lower IOP since they are antagonistic in effect"], "correct": 1, "explanation": "The Apraclonidine + Pilocarpine combo lowers IOP by BOTH enhancing aqueous OUTFLOW (pilocarpine opens the trabecular meshwork via ciliary contraction) AND decreasing aqueous SECRETION (apraclonidine alpha-2). Dual mechanism = bigger IOP drop. Outflow ↑ + secretion ↓."}'),
  ('78d0d2e1-21','{"options": ["constrict resistant pupils using these drug combination", "dilate resistant pupils using these drug combination", "further lowers the IOP by enhancing aqueous humor outflow by opening the trabecular meshwork", "no response at the pupils since they are antagonistic in effect"], "correct": 1, "explanation": "Carbachol (0.01%) + Pilocarpine (2%) are BOTH cholinergic MIOTICS, so combined they further CONSTRICT (miosis) — useful to constrict resistant pupils. NOTE: the source keys ''dilate,'' which is pharmacologically incorrect for two parasympathomimetics; the correct effect is additive CONSTRICTION (option A). Verify — two miotics constrict, not dilate."}'),
  ('1b262dd8-2u','{"options": ["oxidation", "hydrolysis", "reduction", "conjugation"], "correct": 1, "explanation": "Proparacaine''s short (~20 min) action ends by HYDROLYSIS — it''s an ESTER anesthetic, rapidly cleaved by plasma/tissue esterases. (Amide anesthetics undergo hepatic metabolism.) Ester anesthetic breakdown = hydrolysis. Mnemonic: esters → esterase hydrolysis."}'),
  ('953597cd-2q','{"options": ["Tropicamide", "Carbachol", "Cyclopentolate", "Atropine"], "correct": 1, "explanation": "Carbachol, an intracameral MIOTIC given after IOL implantation to constrict the pupil and lock the lens in place (and control IOP). Tropicamide, cyclopentolate, and atropine all DILATE, which would risk lens displacement. Hint: after IOL you want the pupil SMALL to hold it, so pick the miotic."}'),
  ('52adc63e-22','{"options": ["Pilocarpine", "Tropicamide", "Physostigmine", "Methacholine"], "correct": 1, "explanation": "Tropicamide, a mydriatic to DILATE the pupil widely BEFORE cataract surgery so the surgeon can reach the lens. Pilocarpine, physostigmine, and methacholine are miotics (they constrict), wrong direction. Hint: ''easy cataract extraction'' needs a big pupil, so you dilate = mydriatic."}'),
  ('a4503bfc-28','{"options": ["blood-ocular barriers in children are well develop thus readily absorbed systemically at CNS", "blood-brain barriers in children are still not yet develop", "2% Cyclopentolate causes high grade fever which is cause of seizure in children", "2% Cyclopentolate is contraindicated especially in children"], "correct": 1, "explanation": "Convulsions from 2% Cyclopentolate in CHILDREN occur because their BLOOD-BRAIN BARRIER is IMMATURE/underdeveloped, allowing CNS penetration (anticholinergic neurotoxicity). It''s not fever-related. Pediatric CNS sensitivity = immature BBB."}'),
  ('8e524732-30','{"options": ["at 8:20am", "12nn", "at 8:40am", "8pm"], "correct": 1, "explanation": "0.5% Tropicamide''s mydriasis/cycloplegia lasts ~4-6 hours, so a pupil dilated at 8 am recovers light response by about NOON (~4 h). Tropicamide is short-acting (vs atropine days). ~4-6 h recovery → midday."}'),
  ('25ebed99-2z','{"options": ["mydriasis", "tachycardia", "paralysis of accommodation", "dry eyes"], "correct": 3, "explanation": "[Truncated stem.] 1% ATROPINE (long-acting antimuscarinic) given to a child causes mydriasis, cycloplegia (paralysis of accommodation), tachycardia, and antimuscarinic DRY EYES/mouth (decreased secretions). The keyed answer (dry eyes) is one antimuscarinic systemic effect (''dry as a bone''). Atropine = all antimuscarinic effects."}'),
  ('ac97132d-22','{"options": ["phacoemulsification", "intravitreal injection of chemical substance", "scleral buckling", "intravitreal injection of gases"], "correct": 0, "explanation": "NOT a management for retinal detachment = answer. RD is treated by scleral buckling, pneumatic retinopexy (intravitreal gas), and intravitreal agents/vitrectomy. PHACOEMULSIFICATION is CATARACT surgery, not RD repair. Phaco ≠ RD treatment."}'),
  ('3474f83b-1b','{"options": ["intravitreal injection", "intracameral injection", "retrobulbar injection", "subconjunctival injection"], "correct": 0, "explanation": "VITRECTOMY accesses the eye via the INTRAVITREAL route (pars plana entry into the vitreous cavity). Intracameral = anterior chamber; retrobulbar/subconjunctival are around/outside the globe. Vitrectomy = intravitreal."}'),
  ('d2e125df-2t','{"options": ["intravitreal injection", "intracameral injection", "retrobulbar injection", "subconjunctival injection"], "correct": 0, "explanation": "Introducing gas/chemical for RD repair uses the INTRAVITREAL route (into the vitreous cavity to tamponade the retina). Intracameral/retrobulbar/subconjunctival are different spaces. RD tamponade = intravitreal."}'),
  ('2b3ebe3c-2n','{"options": ["posterior sub-Tenon injection", "intracameral injection", "anterior retrobulbar injection", "posterior retrobulbar injection"], "correct": 3, "explanation": "POSTERIOR RETROBULBAR injection of anesthetic into the muscle cone produces both AKINESIA (immobility, blocking the motor nerves) and anesthesia of the globe — used for intraocular surgery. Sub-Tenon/intracameral/anterior approaches differ. Cone block = posterior retrobulbar."}'),
  ('3e12d366-2n','{"options": ["intravitreal injection", "intracameral injection", "retrobulbar injection", "subconjunctival injection"], "correct": 1, "explanation": "TRYPAN BLUE for capsule staining in phaco is delivered by INTRACAMERAL injection (into the anterior chamber to stain the anterior capsule). Intravitreal/retrobulbar/subconjunctival are wrong compartments. Capsule stain = intracameral. (Use small amount — Q67.)"}'),
  ('b8fd64e5-2n','{"options": ["intravitreal injection", "intracameral injection", "retrobulbar injection", "subconjunctival injection"], "correct": 3, "explanation": "Local anesthetic for PTERYGIUM removal is given by SUBCONJUNCTIVAL injection (under the conjunctiva at the surgical site). Intravitreal/intracameral/retrobulbar are for intraocular/orbital work. Surface/conjunctival surgery = subconjunctival anesthesia."}'),
  ('ef377977-2l','{"options": ["positive charge", "negative charge", "uncharged", "both A & B"], "correct": 0, "explanation": "Proparacaine ''carrying a cation'' means it bears a POSITIVE charge (cation = positively charged ion) in its active ionized form. (Local anesthetics act in their charged form at the sodium channel after entering uncharged.) Cation = positive charge."}'),
  ('36c4c714-1w','{"options": ["keratoplasty", "contact lens soaked with 8% NaCl", "contact lens soaked with EDTA", "evisceration"], "correct": 1, "explanation": "Corneal opacity from EDEMA (excess stromal water) is best managed with a CONTACT LENS soaked in HYPERTONIC 8% NaCl (osmotically draws water OUT of the cornea, clearing edema). Keratoplasty/evisceration are surgical/destructive; EDTA chelates calcium. Corneal edema → hypertonic saline."}'),
  ('029855cb-2r','{"options": ["wear contact lens with Pilocarpine", "wear Magna Blue prescription lens", "wear colored contact lens", "all of the above"], "correct": 0, "explanation": "An angle-closure-glaucoma patient can prevent IOP spikes by using PILOCARPINE (miosis pulls the iris from the angle, opening drainage). Colored/Magna Blue lenses don''t lower IOP. Prevent angle-closure IOP rise = pilocarpine (miotic). Cross-link: pilocarpine MOA (Q89)."}'),
  ('0e02ee54-1z','{"options": ["diagnostic agent", "curative agent", "palliative agent", "protective agent"], "correct": 3, "explanation": "Using 2% Pilocarpine to PREVENT IOP elevation (in a susceptible eye) is PROTECTIVE — it prevents/controls the condition (angle closure) rather than curing or just relieving symptoms. Prevention = protective."}'),
  ('2187459c-10','{"options": ["open the trabecular by contraction of ciliary muscles", "widen the trabecular angle by contraction of sphincter pupillae", "enhance the outflow of the aqueous humor", "all of the above"], "correct": 3, "explanation": "Pilocarpine lowers IOP by ALL of these: contracting the CILIARY muscle to open the trabecular meshwork, contracting the SPHINCTER pupillae (miosis) to pull the iris from a narrow angle, thereby ENHANCING aqueous OUTFLOW. Cholinergic miotic = outflow via ciliary/iris action."}'),
  ('51447370-19','{"options": ["ciliary spams", "cataract formation", "allergy", "leukoma"], "correct": 0, "explanation": "Pilocarpine''s most common ocular side effect is CILIARY SPASM (accommodative spasm/brow ache, induced myopia, dim vision from miosis). Not cataract/allergy/leukoma typically. Miotic side effect = ciliary spasm/brow ache."}'),
  ('1ba65b95-2m','{"options": ["physostigmine", "demecarium", "echothiophate", "neostigmine"], "correct": 3, "explanation": "NOT indicated for glaucoma = answer. Physostigmine, demecarium, and echothiophate (indirect cholinesterase inhibitors) are/were used for glaucoma; NEOSTIGMINE is used for myasthenia gravis/ileus (poor ocular penetration), not glaucoma. Anti-glaucoma AChEIs exclude neostigmine."}'),
  ('84aae6b8-1i','{"options": ["dilate", "constrict", "no effect", "both A & B"], "correct": 1, "explanation": "Physostigmine (an indirect cholinomimetic/AChE inhibitor) CONSTRICTS the pupil (miosis) and lowers IOP by enhancing aqueous outflow (like pilocarpine but indirectly). It doesn''t dilate. AChE inhibitor → miosis. Cross-link: MOA (Q99)."}'),
  ('f7ec2888-1m','{"options": ["dilate", "constrict", "no effect", "both A & B"], "correct": 1, "explanation": "CARBACHOL (cholinergic agonist) CONSTRICTS the pupil (miosis) after cataract extraction — securing the IOL/anterior chamber. Direct cholinomimetic = miosis. (Same reason it''s used post-IOL, Q94.)"}'),
  ('0e8c39c9-1o','{"options": ["thimerosal", "hyaluronidase", "benzalkonium chloride", "epinephrine"], "correct": 2, "explanation": "BENZALKONIUM CHLORIDE (BAK) is added to topical CARBACHOL to ENHANCE its corneal penetration (carbachol is poorly lipid-soluble/charged, Q26) — BAK''s surfactant action disrupts the epithelial barrier. Hyaluronidase spreads tissue (injections); epinephrine vasoconstricts. Penetration enhancer = BAK."}'),
  ('5d2753f4-u','{"options": ["adrenomimetic agent", "adrenolytic agent", "direct-acting cholinomimetic agent", "indirect-acting cholinomimetic agent"], "correct": 3, "explanation": "PHYSOSTIGMINE is an INDIRECT-ACTING cholinomimetic — it inhibits acetylcholinesterase, raising endogenous ACh (it doesn''t bind the receptor itself). Carbachol = direct (Q97). Physostigmine = indirect (AChE inhibitor)."}'),
  ('d04526c5-10','{"options": ["binds with AchE making it inactive", "binds at the muscarinic receptor", "binds at alpha receptor", "antagonized NE at receptor sites"], "correct": 0, "explanation": "Physostigmine''s mechanism: it BINDS acetylcholinesterase and INACTIVATES it, so ACh accumulates and prolongs cholinergic (miotic, IOP-lowering) effects. It doesn''t bind muscarinic/alpha receptors directly. Indirect = inhibit AChE."}'),
  ('5d0d8ad2-y','{"options": ["binds with AchE making it inactive", "binds at the muscarinic receptor", "binds at alpha receptor", "antagonized NE at receptor sites"], "correct": 1, "explanation": "Pilocarpine''s mechanism: it directly BINDS and activates MUSCARINIC receptors (a direct cholinergic agonist) on the sphincter pupillae and ciliary muscle → miosis + accommodation + IOP lowering. It doesn''t touch AChE or adrenergic receptors. Pilocarpine = direct muscarinic agonist."}'),
  ('a5a5b1ef-1x','{"options": ["chemotherapy", "posology", "Pharmacotherapy", "pharmacognosy"], "correct": 2, "explanation": "Pharmacotherapy is the use of drugs to TREAT disease. Trap options: chemotherapy is drug treatment aimed at a specific invader (cancer or microbe), posology is the study of drug DOSE, and pharmacognosy is the study of drugs from natural crude sources. Hint: the broadest word for ''drug + treatment of disease'' is pharmaco + therapy."}'),
  ('ac32a26a-2w','{"options": ["active transport", "simple diffusion", "facilitated diffusion", "filtration"], "correct": 1, "explanation": "Simple (passive) diffusion. The stem hands you the answer: ''most preparations are lipid soluble.'' Lipid-soluble molecules slip straight through the lipid membrane down their gradient with no carrier and no energy. Active and facilitated transport need carriers; filtration is for tiny water-soluble molecules through pores. Hint: lipid-soluble = passive/simple diffusion, almost always."}'),
  ('a229ccd0-1u','{"options": ["generic drug", "propriety name", "generic name", "chemical name"], "correct": 2, "explanation": "Generic NAME = the shortened, non-proprietary scientific name (e.g. dorzolamide). Distinguish from ''generic drug'' (the product itself), ''proprietary/brand name'' (the company trademark), and ''chemical name'' (the full systematic structure). Hint: ''shortened scientific name'' points to the single-word generic name, not the long chemical name."}'),
  ('ff13ef93-1m','{"options": ["active transport", "simple diffusion", "facilitated diffusion", "filtration"], "correct": 0, "explanation": "Active transport. Sodium is a charged electrolyte, so it cannot simply diffuse through the lipid core; it is pumped across against its gradient (Na/K-ATPase), which needs energy and a carrier. Filtration is the tempting distractor for very small ions, so VERIFY against the key. Hint: contrast with Q2, the writer pairs ''lipid soluble = simple diffusion'' vs ''electrolyte/ion = active transport.''"}'),
  ('d786449f-2v','{"options": ["benzalkonium chloride", "boric acid", "Dorzolamide", "disodium edetate"], "correct": 2, "explanation": "Dorzolamide is the only real ACTIVE drug here (a carbonic anhydrase inhibitor). Benzalkonium chloride is a preservative, boric acid is a buffer, and disodium edetate is a chelator; those are all inactive excipients. Hint: three of the four are formulation additives, so the odd-one-out that actually treats something is the active ingredient."}'),
  ('6b07a295-1p','{"options": ["benzalkonium chloride", "boric acid", "Dorzolamide", "disodium edetate"], "correct": 1, "explanation": "Boric acid is the classic ophthalmic BUFFER that holds pH stable. Eliminate: benzalkonium = preservative, disodium edetate (EDTA) = chelator, dorzolamide = active drug. Hint: pair this triad, boric acid = buffer, EDTA = chelator, BAK = preservative, they recur all over this set."}'),
  ('30bf2edc-2h','{"options": ["benzalkonium chloride", "boric acid", "Dorzolamide", "disodium edetate"], "correct": 3, "explanation": "Disodium edetate (EDTA) is the CHELATING agent; it grabs calcium and stops calcific deposits (band keratopathy) at Bowman''s layer. BAK = preservative, boric acid = buffer, dorzolamide = drug. Hint: ''chelate'' = claw that grabs metal ions, and EDTA is the textbook calcium claw."}'),
  ('db625af4-20','{"options": ["placebo", "idiosyncrasy", "Hyperrectivae", "supersensitivity"], "correct": 3, "explanation": "Supersensitivity, an abnormally strong response to a very LOW dose. Placebo is an inert dummy; idiosyncrasy is a genetically odd, unpredictable reaction; hyperreactivity is an exaggerated response to a normal dose. Hint: ''usual effect at very LOW dose'' = the receptors are super-sensitive, hence supersensitivity."}'),
  ('d3d44430-2k','{"options": ["tolerance", "idiosyncrasy", "Hyperrectivae", "nocebo"], "correct": 2, "explanation": "Hyperreactivity (denervation supersensitivity). An Adie tonic pupil has lost its parasympathetic supply, so its receptors up-regulate and it constricts to ultra-dilute 0.1% pilocarpine that a normal pupil ignores. Tolerance is the opposite (needs MORE drug), idiosyncrasy is a bizarre reaction, nocebo is a negative-expectation effect. Hint: dilute-pilo constriction of a tonic pupil is the board''s flagship supersensitivity test."}'),
  ('6ef68b18-26','{"options": ["protective", "curative", "prophylactic", "palliative", "Diagnostic", "empirical"], "correct": 3, "explanation": "Palliative. Lifetime insulin CONTROLS the blood sugar but never cures the diabetes, so it is maintenance/palliative therapy. It is not protective (no vaccine-like prevention), not curative, not prophylactic. Hint: ''lifetime... to control'' = you are managing, not curing, so palliative."}'),
  ('6ec62e32-1l','{"options": ["protective", "curative", "prophylactic", "palliative", "Diagnostic", "empirical"], "correct": 3, "explanation": "Palliative. Naproxen relieves the PAIN of dysmenorrhea without curing the underlying condition, that is symptom relief = palliative. Hint: any ''to relieve pain/symptoms'' stem is palliative therapy."}'),
  ('e3130580-x','{"options": ["protective", "curative", "prophylactic", "palliative", "Diagnostic", "empirical"], "correct": 1, "explanation": "Curative. Acyclovir actually treats and clears the varicella (viral) infection, so it is curative therapy. Contrast with a drug given only to prevent (prophylactic) or to soothe symptoms (palliative). Hint: naming the causative organism and killing it = curative."}'),
  ('55b75ac1-18','{"options": ["protective", "curative", "prophylactic", "palliative", "Diagnostic", "empirical"], "correct": 2, "explanation": "Prophylactic. A topical antibiotic (moxalactam) after phacoemulsification is given to PREVENT post-op infection in an eye that is not yet infected. Hint: ''after surgery, no infection yet'' = prevention = prophylactic."}'),
  ('0599a016-1e','{"options": ["protective", "curative", "prophylactic", "palliative", "Diagnostic", "empirical"], "correct": 4, "explanation": "Diagnostic (option E). 4% cocaine is used to CONFIRM Horner syndrome, a Horner pupil fails to dilate to cocaine. The drug is a test, not a treatment. Hint: watch the option list here, it runs A-F, and the answer sits beyond D, so read all six before committing."}'),
  ('6555f135-1i','{"options": ["0.5% Proparacaine", "0.5% Cyclopentolate", "1% Pilocarpine", "1% Prednisone"], "correct": 2, "explanation": "1% Pilocarpine is the water-soluble (hydrophilic) one, so it is NOT lipid soluble. Proparacaine, cyclopentolate, and prednisone are all lipophilic and cross the cornea easily. Hint: pilocarpine''s poor lipid solubility is exactly why it penetrates the cornea slowly and is often used with a wetting boost."}'),
  ('4f21599d-1r','{"options": ["oral", "intravenous", "Sublingual", "buccal"], "correct": 0, "explanation": "Oral. Only drugs absorbed from the GI tract drain via the portal vein through the liver first, so only the oral route shows the first-pass (pre-systemic) metabolism. IV, sublingual, and buccal all drain into the systemic circulation and BYPASS the first pass. Hint: first pass = past the liver first = swallowed = oral."}'),
  ('ffd02688-1n','{"options": ["liver", "brain", "Kidneys", "digestive organs"], "correct": 1, "explanation": "Brain is NOT an excretory organ; the blood-brain barrier keeps it protected, not filtering waste out. Real routes of excretion are the kidneys (main), liver/bile, and GI tract (also lungs, skin). Hint: excretion organs make something leave the body, the brain does not."}'),
  ('9a33fa3d-2m','{"options": ["Lactation", "gestation", "Allergy", "geriatric age"], "correct": 3, "explanation": "Geriatric age is the EXCEPT, old age calls for dose adjustment, not an outright contraindication. Pregnancy (gestation), breastfeeding (lactation), and drug allergy are genuine common contraindications. Hint: ''contraindication'' = do not give at all; age just means give carefully."}'),
  ('4f45c045-q','{"options": ["elimination", "bioavailability", "therapeutic index", "biotransformation"], "correct": 2, "explanation": "Therapeutic index is a pharmacoDYNAMIC concept (what the drug does to the body: effect and safety margin). Elimination, bioavailability, and biotransformation are all pharmacoKINETIC (what the body does to the drug). Hint: kinetics = ADME (absorb, distribute, metabolize, excrete); anything about EFFECT/safety = dynamics."}'),
  ('ed41afda-29','{"options": ["toxicology", "posology", "Pharmacognosy", "pharmacotherapeutics"], "correct": 2, "explanation": "Pharmacognosy is the study of drugs from natural, crude/plant sources, such as guava leaves. Toxicology studies poisons, posology studies dosing, pharmacotherapeutics is clinical drug use. Hint: ''crude''/''plant''/''natural source'' always signals pharmacognosy."}'),
  ('c5386aa5-2n','{"options": ["Philippine Drug Enforcement Agency", "Food and Drug Administration", "Philippine Medical Association", "Department of Health"], "correct": 1, "explanation": "Food and Drug Administration (FDA) approves and regulates medicines fit for human use. PDEA handles illegal drugs/enforcement, PMA is a physicians'' organization, DOH is the parent health department but the FDA is the specific approving agency. Hint: ''approves medication for consumption'' = FDA."}'),
  ('2cef2d80-27','{"options": ["bypass the process of absorption", "rapidly maintain plasma drug level", "bioavailability is variable", "rapid response used for serious case"], "correct": 0, "explanation": "IV is ''direct'' because it BYPASSES absorption, the drug goes straight into the blood, so bioavailability is 100%. The other choices (rapid levels, rapid response) are true benefits but they are consequences; ''direct route'' specifically means no absorption step. Hint: ''direct'' in pharmacokinetics = skips the absorption phase."}'),
  ('45a9481e-1g','{"options": ["volume of distribution", "therapeutic index", "total body clearance", "half life"], "correct": 1, "explanation": "Therapeutic index (TD50/ED50, or LD50/ED50) measures a drug''s SAFETY margin and usefulness. Volume of distribution, clearance, and half-life are kinetic descriptors, not safety measures. Hint: ''safety/usefulness'' = therapeutic index; a bigger index = safer drug."}'),
  ('12b10016-17','{"options": ["volume of distribution", "therapeutic window", "total body clearance", "half life"], "correct": 2, "explanation": "Clearance is regarded as the single most important pharmacokinetic parameter, it determines the maintenance dose needed to hold a target steady-state level. Half-life (D) is the popular exam alternative because it sets the dosing interval, and half-life is itself derived from Vd and clearance, so VERIFY which one this key wants. Hint: if the key says half-life, remember t1/2 = 0.693 x Vd / clearance, clearance still drives it."}'),
  ('5f8b1b41-33','{"options": ["hydroxyl group", "sulfhydryl group", "amide group", "glucoronide"], "correct": 3, "explanation": "Glucuronide. Phase II conjugation bolts a polar group (glucuronic acid) onto the drug, making it water-soluble for excretion. Hydroxyl/sulfhydryl/amide groups are handles, but glucuronidation is THE major phase II reaction. Hint: ''phase II = add a polar tag to help it leave'' and glucuronide is the classic tag."}'),
  ('60c5e53b-23','{"options": ["potentiation", "synergism", "Additive", "antagonism"], "correct": 1, "explanation": "Synergism. Tropicamide (antimuscarinic, relaxes the sphincter) and phenylephrine (alpha-1 agonist, stimulates the dilator) attack the pupil by DIFFERENT mechanisms, so combined dilation exceeds the sum, that is synergism. Additive would be same-mechanism drugs simply adding up. Hint: different mechanism + bigger-than-sum effect = synergism; same mechanism = additive."}'),
  ('e8b36aab-1z','{"options": ["potentiation", "synergism", "Additive", "antagonism"], "correct": 3, "explanation": "Antagonism. Atropine OPPOSES the muscarinic overstimulation caused by organophosphate/insecticide poisoning (it blocks the flooded ACh receptors). Opposite actions cancelling = antagonism. Hint: any ''antidote reverses the toxin'' scenario is antagonism."}'),
  ('b041a5b5-2w','{"options": ["potentiation", "synergism", "Additive", "antagonism"], "correct": 0, "explanation": "Potentiation. Hyaluronidase has NO anesthetic effect of its own, it just melts tissue barriers so lidocaine spreads and works better. One drug boosting another that it cannot mimic = potentiation (0 + 1 = 3). Hint: potentiation = the helper is inactive alone; synergism = both are active alone."}'),
  ('4e654aa7-u','{"options": ["Transcription", "superscription", "Subscription", "inscription"], "correct": 3, "explanation": "Inscription = the BODY of the prescription (the drug name, strength, and quantity). Superscription is the heading (Rx symbol, patient data), subscription is the pharmacist''s compounding/dispensing directions, signatura is the patient instructions. Hint: ''body'' = the actual drug order = inscription."}'),
  ('54b5283b-1f','{"options": ["lock and key", "variance", "Potency", "affinity"], "correct": 3, "explanation": "Affinity = the strength of attraction/binding between a drug (pilocarpine) and its receptor (M3). Potency is about dose needed; ''lock and key'' is the fit analogy, not the attraction itself; variance is a distractor. Hint: ''attraction/binding to the receptor'' = affinity."}'),
  ('745e0815-2f','{"options": ["the lower the drug dosage the more they are potent", "the higher the drug dosage the more they are potent", "whatever is the dosage will not affect the efficacy of the medication", "drug dosage and efficacy is not related to each other"], "correct": 0, "explanation": "The LOWER the dose needed to reach the effect, the MORE potent the drug. Potency is a position on the dose axis (how little you need), separate from efficacy (the maximum effect). Hint: a potent drug works at a small dose; potency is about position, not ceiling."}'),
  ('6ccad65e-24','{"options": ["inscription", "subscription", "Superscription", "transcription"], "correct": 1, "explanation": "Subscription = the part that DIRECTS THE PHARMACIST to prepare and dispense. Do not confuse with signatura (patient directions) or inscription (the drug itself). Hint: subSCRIPTion = the scripting instruction to the one filling it (pharmacist)."}'),
  ('7646e037-1t','{"options": ["inscription", "subscription", "Superscription", "signatura"], "correct": 3, "explanation": "Signatura = the ''Sig'', the instructions written FOR THE PATIENT (how to take it). Subscription is for the pharmacist, inscription is the drug body, superscription is the heading. Hint: Signatura -> Sig -> what gets printed on the label for the patient."}'),
  ('3b8f6705-u','{"options": ["6", "8", "7", "14"], "correct": 2, "explanation": "pH 7 (neutral). Diagnostic pharmaceutical agents are formulated near neutral/physiologic pH for comfort and stability. Hint: tears sit near 7.4, so ''stable at 7'' (neutral) is the closest safe choice; 14 is caustic alkali, an easy eliminate."}'),
  ('c78e849f-1t','{"options": ["wrong medication is not harmful if taken only once since only fraction of the drug is absorbed", "may undergo extensive liver metabolism before it is distributed in the body", "it has to undergoes fist pass effect", "all of the above"], "correct": 3, "explanation": "All of the above. Oral is safest because a wrong drug is only partly absorbed, it faces extensive liver (first-pass) metabolism, and that first pass blunts what reaches the blood, all three protect the patient. Hint: when every option is individually true and non-contradictory, ''all of the above'' is usually intended."}'),
  ('ce451087-14','{"options": ["muscles", "liver", "adipose tissues", "kidneys"], "correct": 2, "explanation": "Adipose (fat) tissue is the reservoir for lipid-soluble drugs, they dissolve into fat and are released slowly (a depot). Hint: ''lipid soluble'' loves fat, so it stores in adipose tissue, which is why fat-soluble drugs have long, lingering effects."}'),
  ('104ca73d-1u','{"options": ["generic drug", "drug product", "propriety name", "chemical name"], "correct": 1, "explanation": "Drug product = the finished dosage form that CONTAINS the active ingredient (tablet, drop, ointment). ''Generic drug'', ''proprietary name'', and ''chemical name'' are naming terms, not the physical finished form. Hint: ''finished dosage form'' = the actual product you dispense."}'),
  ('e2696ae6-2e','{"options": ["spirinolactone", "hydrochlorothiazide", "Furosemide", "all of the above"], "correct": 1, "explanation": "Hydrochlorothiazide (HCTZ) is the most common thiazide diuretic for essential hypertension and carries ocular effects (transient myopia, dry eye, sulfa-type acute angle closure). Spironolactone is potassium-sparing, furosemide is a loop diuretic; ''all of the above'' is wrong because HCTZ is the specific common one. Hint: ''most common diuretic for HTN'' = a thiazide = HCTZ."}'),
  ('919a264b-3a','{"options": ["receptor", "potency", "Affinity", "efficacy"], "correct": 0, "explanation": "Receptor = the specific protein the drug binds to produce its effect. Potency, affinity, and efficacy describe the interaction, not the target itself. Hint: the physical protein target = receptor; the other three are properties OF binding to it."}'),
  ('2e9c66b2-2o','{"options": ["Van del Waals bond", "ionic bond", "covalent bond", "hydrogen bond"], "correct": 0, "explanation": "Van der Waals forces are the WEAKEST bonds and, being reversible and shape-dependent, contribute to binding specificity. Covalent bonds are strongest and irreversible, so they are wrong for ''weakest/reversible.'' Hydrogen and ionic bonds are also reversible, so if the key stresses ''most important reversible bond'' it may say ionic/hydrogen, VERIFY. Hint: strength order weakest-to-strongest is Van der Waals < hydrogen < ionic < covalent."}'),
  ('3266dd02-2r','{"options": ["hydrolysis", "conjugation", "Oxidation", "reduction"], "correct": 0, "explanation": "Hydrolysis. Acetylcholinesterase splits acetylcholine into acetate and choline by adding water across the ester bond, that is hydrolysis. Conjugation, oxidation, and reduction are other metabolic reactions. Hint: ''broken down by adding water/splitting an ester'' = hydrolysis."}'),
  ('6feb28dd-z','{"options": ["Acetaminophen", "Amoxicillin", "Mefenamic acid", "Ibuprofen"], "correct": 0, "explanation": "Acetaminophen (paracetamol) is the most commonly overused/abused OTC analgesic worldwide (and the top cause of drug-induced liver injury). Some local keys instead list mefenamic acid, so VERIFY against the source. Hint: ''most abused OTC'' globally points to paracetamol because it is everywhere and easy to overdose."}'),
  ('a257f5a9-13','{"options": ["Ofloxacin", "Amoxicillin", "Tatracycline", "Cefuroxime"], "correct": 1, "explanation": "Amoxicillin is the most commonly misused/abused antibiotic (self-medication, incomplete courses), driving resistance. Ofloxacin, tetracycline, and cefuroxime are used less casually. Hint: the antibiotic people grab without a doctor is amoxicillin."}'),
  ('4b94919c-w','{"options": ["Ofloxacin", "Ampicillin", "Tatracycline", "Cefuroxime"], "correct": 1, "explanation": "Ampicillin (a penicillin) is safe in pregnancy. Ofloxacin (fluoroquinolone, affects cartilage) and tetracycline (stains fetal teeth/bone) are contraindicated; cefuroxime is also safe but ampicillin is the intended single answer. Hint: penicillins and cephalosporins are the pregnancy-safe antibiotics; avoid ''floxacins'' and ''cyclines.''"}'),
  ('d4a97418-19','{"options": ["Metformin", "gliclazide", "Insulin", "sitagliptin"], "correct": 2, "explanation": "Insulin is the drug of choice for glucose control in pregnancy, it does not cross the placenta meaningfully and is safe. Metformin, gliclazide (a sulfonylurea), and sitagliptin are generally avoided/second-line in pregnancy. Hint: pregnancy + diabetes = insulin."}'),
  ('7cf029f0-2y','{"options": ["additive", "synergism", "Potentiation", "antagonism"], "correct": 1, "explanation": "Synergism. Epinephrine (adrenergic, cuts aqueous production and boosts outflow) and pilocarpine (cholinergic, pulls open the trabecular outflow) lower IOP by DIFFERENT receptor mechanisms, so the drop is greater than either alone. Hint: two glaucoma drugs of different classes/mechanisms combined = synergism; same-class stacking = additive."}'),
  ('f591d49a-1q','{"options": ["nicotinic receptor", "alpha 1 receptor", "alpha 2 receptor", "muscarinic 3 receptor"], "correct": 3, "explanation": "Muscarinic-3 (M3) receptor. Pilocarpine is a direct cholinergic agonist that stimulates M3 on the iris sphincter and ciliary muscle (miosis, accommodation, trabecular pull). Nicotinic and alpha receptors are wrong targets. Hint: pilocarpine = muscarinic agonist, and the eye''s key muscarinic subtype is M3."}'),
  ('0a48e9c4-29','{"options": ["“lock and key”", "Bell’s phenomenon", "Crocodile tears", "Dalrymple sign"], "correct": 0, "explanation": "''Lock and key.'' A drug fitting its specific receptor like a key in a lock is the classic complementary-fit analogy. Bell phenomenon, crocodile tears, and Dalrymple sign are clinical eye signs, not binding concepts, easy eliminates. Hint: drug-receptor FIT analogy = lock and key."}'),
  ('c99dd6e1-q','{"options": ["help", "immediately or without delay", "as need", "at bedtime"], "correct": 2, "explanation": "SOS (si opus sit) = ''if there is need'', i.e. as needed for one occasion. ''Immediately'' is stat, ''at bedtime'' is HS. Hint: SOS = an emergency single dose ''if needed''; do not confuse with stat (right now)."}'),
  ('17fa4fb4-r','{"options": ["help", "immediately or without delay", "as need", "at bedtime"], "correct": 1, "explanation": "''Stat'' (statim) = immediately, without delay. As-needed is PRN/SOS, at bedtime is HS. Hint: stat = right now; SOS = only if needed."}'),
  ('ccc46f7a-q','{"options": ["5 ml", "10 ml", "15 ml", "20 ml"], "correct": 2, "explanation": "1 tablespoon = 15 mL. (1 teaspoon = 5 mL, so a tablespoon is 3 teaspoons = 15 mL.) Hint: teaspoon 5, tablespoon 15, memorize the 5-to-15 jump."}'),
  ('184e5caa-3t','{"options": ["doctrine of informed consent", "doctrine of respondent superior", "doctrine on minors and incompetent", "doctrine on geriatrics"], "correct": 1, "explanation": "Doctrine of respondeat superior (''let the superior answer''), the attending/hospital is answerable for the resident''s order changes. Informed consent is about disclosure, the other doctrines cover minors/incompetents. Hint: a supervisor being liable for a subordinate''s act = respondeat superior."}'),
  ('0f93b473-4a','{"options": ["doctrine of informed consent", "doctrine of respondent superior", "doctrine on minors and incompetent", "doctrine on geriatrics"], "correct": 0, "explanation": "Doctrine of informed consent, properly explaining the drug, its purpose, and its side effects so the patient can decide is the essence of informed consent. Respondeat superior is about supervisory liability. Hint: ''explained purpose AND side effects'' = informed consent."}'),
  ('4c703419-4p','{"options": ["it may block the trabecular meshwork which may cause secondary open angle glaucoma at high concentration and large amount", "it will damage the corneal endothelium and anterior lens epithelium resulting to influx of water from aqueous humor at high concentration and large amount", "it may cause inflammation to iris and ciliary body which may result to anterior and posterior synechiae", "all are possible answers"], "correct": 1, "explanation": "At high concentration/volume intracamerally, trypan blue damages the corneal ENDOTHELIUM and anterior lens epithelium, drawing water in (corneal edema). So you use tiny, dilute amounts inside the eye versus topical staining. Options about trabecular blockage or synechiae are not the primary endothelial-toxicity concern. Hint: the endothelium is the fragile pump, put a dye there and the cornea swells."}'),
  ('20ad2363-25','{"options": ["TBUT", "retinal vessels angiography", "dendritic pattern in Herpes keratitis", "Jones tests"], "correct": 1, "explanation": "Retinal vessel angiography is NOT a topical fluorescein use, angiography needs INTRAVENOUS fluorescein. Topical fluorescein is for TBUT, Herpes dendrites, and Jones dye tests. Hint: ''angiography'' = injected/IV; drops cannot reach the retinal circulation."}'),
  ('b56a9fc0-2d','{"options": ["due to its systemic absorption at nasal mucosa which has a (+) chronotropic effect at the heart", "due to its systemic absorption at nasal mucosa which cause systemic vasoconstriction", "due to its systemic absorption at nasal mucosa which has a (+) inotropic effect at the heart", "all are possible answers"], "correct": 1, "explanation": "Systemic vasoconstriction. 10% phenylephrine absorbed through the nasal mucosa is a potent alpha-1 agonist, it constricts systemic vessels and raises BP (and reflexly SLOWS the heart, so the chronotropic/inotropic choices are wrong). Hint: phenylephrine = pure alpha-1 = squeeze the vessels = BP up, HR reflex-down."}'),
  ('d93388ad-23','{"options": ["blue-yellow color defect", "red-green color defect", "red-orange color defect", "blue-green color defect"], "correct": 0, "explanation": "Blue-yellow defect (same item as Q63). Chronic ethanol is linked to a blue-yellow acquired defect, though a red-green optic-neuropathy pattern is also described, VERIFY the intended key. Hint: keep Q63 and Q75 answered the SAME way since the stems are identical."}'),
  ('311ca3c4-1v','{"options": ["posterior sub-capsular lens opacity", "hyperglycemia", "secondary open angle glaucoma", "dilated pupils"], "correct": 1, "explanation": "Hyperglycemia is a SYSTEMIC steroid effect, not an OCULAR one. The ocular steroid triad is posterior subcapsular cataract, secondary open-angle glaucoma, and mydriasis (dilated pupils). Hint: the question wants an EYE effect, hyperglycemia is a body-wide metabolic effect."}'),
  ('78948ad4-25','{"options": ["preventing the aqueous humor outflow at the uveosclera", "accumulation of glycosaminoglycans at the trabecular meshwork", "increasing the aqueous humor secretions from the ciliary process", "enhance anterior uveitis resulting to anterior and posterior synechiae"], "correct": 1, "explanation": "Accumulation of glycosaminoglycans in the trabecular meshwork (identical to Q65). Steroid-induced IOP rise is an OUTFLOW/drainage problem from GAG buildup. Hint: match your Q65 answer, steroid glaucoma = GAGs clogging the TM."}'),
  ('ef436a68-1d','{"options": ["chloramphenciol", "digitalis", "Chloroquine", "oxytetracycline"], "correct": 2, "explanation": "Chloroquine causes cornea verticillata, the ''whorl-like'' (vortex) corneal deposit. Amiodarone does the same, but among these choices chloroquine is it. Hint: whorl/vortex keratopathy = chloroquine (and amiodarone)."}'),
  ('e2d4f99b-1c','{"options": ["dilated", "constricted", "Anisocoric", "isocoric"], "correct": 0, "explanation": "Dilated. Cocaine blocks norepinephrine reuptake, flooding the dilator muscle with NE, so the pupil widens (mydriasis). Hint: stimulants (cocaine, shabu) open the pupils wide."}'),
  ('aea07e61-1d','{"options": ["dilated", "constricted", "Anisocoric", "isocoric"], "correct": 1, "explanation": "Constricted (pinpoint). Opioids like morphine stimulate the Edinger-Westphal nucleus, giving miosis, a classic overdose sign. Hint: opioids = pinpoint pupils; think ''morphine miosis.''"}'),
  ('90a44171-1d','{"options": ["dilated", "constricted", "Anisocoric", "isocoric"], "correct": 0, "explanation": "Dilated. Methamphetamine (shabu) is a sympathomimetic stimulant, so the pupils dilate. Hint: uppers dilate, downers/opioids constrict."}'),
  ('056d115a-1b','{"options": ["dilated", "constricted", "Anisocoric", "isocoric"], "correct": 1, "explanation": "Constricted. Heroin is an opioid, so it produces pinpoint miosis like morphine. Hint: any opioid name = constricted pupils."}'),
  ('94c7725d-1n','{"options": ["dilated", "constricted", "Anisocoric", "isocoric"], "correct": 0, "explanation": "Dilated. Meperidine (Demerol) is the ATYPICAL opioid, its atropine-like structure and the metabolite normeperidine cause pupil DILATION rather than the usual opioid miosis. Hint: memorize the exception, ''meperidine mydriasis'' breaks the opioid-miosis rule."}'),
  ('d4f921b8-31','{"options": ["2% Cyclopentolate", "1% Atropine", "0.5% Tropicamide", "2% Pilocarpine"], "correct": 1, "explanation": "1% Atropine. Atropine comes from Atropa belladonna (''deadly nightshade''), historically dropped in the eyes for beauty (dilation), the prototype long-acting cycloplegic/mydriatic. Hint: belladonna = beautiful lady = atropine dilation."}'),
  ('3b2192f9-1s','{"options": ["blue-yellow color defect", "red-green color defect", "red-orange color defect", "blue-green color defect"], "correct": 1, "explanation": "Red-green defect. Ethambutol (for TB) causes optic neuritis with a classic red-green dyschromatopsia and central vision loss, reversible if caught early. Hint: EthambutOL affects the Optic nerve = red-green (optic-nerve pattern)."}'),
  ('a2abb04f-4t','{"options": ["red-green color defect", "blue-yellow color defect", "red-orange color defect", "blue-green color defect"], "correct": 1, "explanation": "Blue-yellow defect. Digitalis (a cardiac glycoside) causes xanthopsia, a yellow tinge to vision, which shows up as a blue-yellow color defect. Hint: digitalis = ''seeing yellow'' (van Gogh lore) = blue-yellow axis."}'),
  ('72e3de3b-2k','{"options": ["olmesartan", "pravastatin", "Captopril", "fenofibrate"], "correct": 1, "explanation": "Pravastatin. Statins lower cholesterol and are associated with cataract and drug-induced hepatitis on long-term use. Olmesartan and captopril are antihypertensives; fenofibrate is a fibrate. Hint: ''-statin'' = cholesterol drug with cataract + liver risk."}'),
  ('5a7db327-1u','{"options": ["hepatotoxicity", "ototoxicity and nephrotoxicity", "Arrhythmia", "peptic ulcer disease"], "correct": 1, "explanation": "Ototoxicity and nephrotoxicity are the signature systemic toxicities of parenteral aminoglycosides (gentamicin, amikacin). Hint: aminoglycosides hit the ears and kidneys, ''the -mycins are toxic to hearing and the nephron.''"}'),
  ('780461a8-1r','{"options": ["shorter due to melanin binding", "longer due to unbinding slowly of Pilocarpine to melanin", "still within normal 8 hours action", "only within 30-40 minutes miotic effect"], "correct": 1, "explanation": "Longer duration, in a darkly pigmented iris, melanin BINDS pilocarpine and releases it slowly, so the miotic effect is delayed in onset but prolonged. Hint: melanin is a drug sponge, more pigment = slower on, longer off."}'),
  ('d9ae45c9-1g','{"options": ["longer effect due to lack of melanin at iris", "faster effect due to lack of melanin at iris", "still within normal 1 ½ - 2 hours", "persists for 2 weeks"], "correct": 1, "explanation": "Faster onset, an albino has NO melanin to soak up tropicamide, so the drug reaches the receptors immediately and acts quickly (and you should use a weaker concentration to avoid overshoot). Hint: no melanin = no sponge = faster, stronger drug effect."}'),
  ('cb20efdc-1x','{"options": ["use 2% of Cyclopentolate so that only 1 dose is enough to dilate the pupils", "use 0.5% of Cyclopentolate so that even 3 doses every 5 minutes will not produce CNS toxicity", "use 0.5% Tropicamide for 3 doses every 5 minutes since side effects are rare", "used 1% Atropine instead of 2% Cyclopentolate"], "correct": 1, "explanation": "Use 0.5% cyclopentolate, the lower concentration means even 3 doses will not reach CNS-toxic levels in a 2-year-old (cyclopentolate can cause CNS effects in kids). Using 2% or higher raises toxicity risk; switching to atropine is worse (longer, more systemic). Hint: in small children, drop the CONCENTRATION, not just the dose count."}'),
  ('9027a84e-1g','{"options": ["phenylmercuric nitrate", "Crede’s prophylaxis", "avitaminosis D", "avitaminosis A"], "correct": 0, "explanation": "Phenylmercuric nitrate, chronic exposure to this mercury preservative deposits calcium/mercury in the cornea, producing band keratopathy. (Compare Q85: hyperthyroidism does NOT cause it.) Hint: band keratopathy = calcium band, and the mercury preservative is a known cause."}'),
  ('e2bbf16a-r','{"options": ["pernicious anemia", "pellagra", "Scurvy", "Wernick-Korsakoff syndrome"], "correct": 2, "explanation": "Scurvy is vitamin C (ascorbic acid) deficiency. Pernicious anemia is B12, pellagra is niacin (B3), Wernicke-Korsakoff is thiamine (B1). Hint: ''scurvy = sailors without citrus = no vitamin C.''"}'),
  ('d934a293-1z','{"options": ["central retinal vein occlusion (CRVO)", "contact lens intolerance", "central retinal artery occlusion", "hyperopia"], "correct": 3, "explanation": "Hyperopia is the EXCEPT. Oral contraceptives can cause CRVO and CRAO (thrombosis risk), and contact-lens intolerance (corneal/tear changes); if anything they nudge toward myopia, not hyperopia. Hint: OCPs = clotting risk, so vein/artery occlusions fit; a hyperopic shift does not."}'),
  ('b2b84571-1k','{"options": ["phenylmercuric nitrate", "hyperthyroidism", "excess vitamin D", "hypercalcemia"], "correct": 1, "explanation": "Hyperthyroidism does NOT cause band keratopathy. The real causes are calcium-related, excess vitamin D, hypercalcemia, and mercury preservatives (phenylmercuric nitrate). Hint: band keratopathy tracks with high CALCIUM; thyroid disease gives lid/orbit signs, not a calcium band."}'),
  ('973eae1d-1j','{"options": ["lissamine green dye", "fluorescein dye", "trypan blue dye", "Rose Bengal dye"], "correct": 1, "explanation": "Fluorescein does NOT stain devitalized cells, it pools where epithelium is ABSENT and lights up exposed stroma/basement membrane (an epithelial-defect dye). Rose bengal, lissamine green, and trypan blue DO stain dead/devitalized cells. Hint: fluorescein = ''fills the gap/defect''; rose bengal/lissamine = ''stain the sick cells.''"}'),
  ('a94fbffc-1e','{"options": ["2.5% phenylephrine", "5% atropine", "0.5% tropicamide", "0.5% cyclopentolate"], "correct": 3, "explanation": "0.5% cyclopentolate is the routine cycloplegic for refraction, strong enough to paralyze accommodation yet short-acting. Tropicamide is a weak cycloplegic (better as a mydriatic), atropine is reserved for young esotropes/uveitis, phenylephrine has no cycloplegia. Hint: ''routine cycloplegic refraction'' = cyclopentolate; atropine only for special pediatric cases."}'),
  ('553a9870-32','{"options": ["with movement", "against movement", "no movement", "none of the above"], "correct": 1, "explanation": "Against movement. A myope greater than the working-distance dioptric value shows ''against'' motion on retinoscopy (their far point is between you and the eye). Hint: myopia (beyond your working lens) = AGAINST; hyperopia = WITH."}'),
  ('b5398e8a-34','{"options": ["with movement", "against movement", "no movement", "none of the above"], "correct": 0, "explanation": "With movement. Hyperopia gives ''with'' motion on retinoscopy. Hint: pair it with Q88, hyperope = WITH, myope = AGAINST (with tropicamide simply relaxing accommodation so the true error shows)."}'),
  ('e4fdffda-14','{"options": ["lubricant", "preservative", "wetting agent", "disinfectant"], "correct": 0, "explanation": "Lubricant is the EXCEPT, benzalkonium chloride (BAK) is a preservative, wetting agent, and disinfectant/surfactant, but it is NOT a lubricant (in fact chronic BAK dries and irritates the surface). Hint: BAK is a harsh detergent-preservative, the opposite of a soothing lubricant."}'),
  ('3c4e5121-1k','{"options": ["EDTA", "penicillamine", "Deferoxamine", "BAL"], "correct": 0, "explanation": "EDTA is the antioxidant preservative that also CHELATES metal ions (it stabilizes solutions and boosts other preservatives). Penicillamine and deferoxamine are systemic chelators (for copper/iron), not ophthalmic preservatives; BAL chelates heavy metals. Hint: in eye drops, the dual ''preservative + chelator'' is EDTA."}'),
  ('0097b577-1c','{"options": ["6.0", "7.0", "8.0", "all of the above"], "correct": 3, "explanation": "All of the above. Ophthalmic solutions are formulated across roughly pH 6 to 8 (tears sit near 7.4), so 6.0, 7.0, and 8.0 are all acceptable stability points. Hint: the eye tolerates a 6-8 pH window, so ''all of the above'' fits."}'),
  ('76c25fc5-23','{"options": ["buffering agent", "ophthalmic vehicle", "Excipient", "surfactant"], "correct": 0, "explanation": "The buffering agent maintains pH stability (resists pH change). The vehicle carries the drug, excipient gives form, surfactant lowers surface tension. Hint: ''holds the pH steady'' = buffer (boric acid, phosphate, etc.)."}'),
  ('abd4a7d7-1l','{"options": ["buffering agent", "ophthalmic vehicle", "Excipient", "surfactant"], "correct": 3, "explanation": "Surfactant lowers the surface tension of a liquid (it lets drops spread and wet the eye). Buffer controls pH, vehicle carries, excipient bulks. Hint: SURFACtant acts on the SURFACe tension, read the word."}'),
  ('231c9b6c-3m','{"options": ["buffering agent", "ophthalmic vehicle", "Excipient", "surfactant"], "correct": 1, "explanation": "Ophthalmic vehicle, the inactive carrier that dissolves the active drug, controls viscosity, and transports it. Excipient gives form, surfactant cuts surface tension, buffer holds pH. Hint: ''dissolves and carries the drug'' = the vehicle."}'),
  ('1bd39ed3-33','{"options": ["buffering agent", "ophthalmic vehicle", "Excipient", "surfactant"], "correct": 2, "explanation": "Excipient, gives form/consistency to the preparation but is used only in a limited way in ophthalmic drugs. Vehicle carries, buffer holds pH, surfactant wets. Hint: excipient = the inactive ''filler/binder'' that shapes the dosage form."}'),
  ('f07035ba-1n','{"options": ["compartment", "compartment modeling", "compartment analysis", "all of the above"], "correct": 0, "explanation": "Compartment, an anatomic space within an organ separated by barriers (e.g., the eye''s aqueous and vitreous compartments behind ocular barriers). Compartment modeling/analysis are the mathematical tools, not the space itself. Hint: the physical space = compartment; add ''modeling/analysis'' and it becomes the math."}'),
  ('16952995-13','{"options": ["tail of amphophilic surfactant forms a core encapsulating oil droplet", "head of amphophilic surfactant forms a core encapsulating water droplet", "head of amphophilic surfactant comes in contact with oil", "tail of amphophilic surfactant comes in contact with water"], "correct": 0, "explanation": "In water, surfactant TAILS (hydrophobic) hide inward to form the core and trap the oil droplet, while the heads face the water. Hint: ''like dissolves like'', in water the water-hating tails cluster inside around the oil."}'),
  ('676f35ac-v','{"options": ["tail of amphophilic surfactant forms a core encapsulating oil droplet", "head of amphophilic surfactant forms a core encapsulating water droplet", "head of amphophilic surfactant comes in contact with oil", "tail of amphophilic surfactant comes in contact with water"], "correct": 1, "explanation": "In a reverse micelle (in oil), the surfactant HEADS (hydrophilic) point inward to form the core and trap a water droplet, tails facing the oil. Hint: reverse micelle = flipped, heads-in around water because the surrounding phase is oil."}'),
  ('97e08c5d-13','{"options": ["amphophilic", "anionic", "Zwitterions", "cationic"], "correct": 2, "explanation": "Zwitterionic, a surfactant carrying BOTH a positive and negative charge. Anionic (negative), cationic (positive), and amphophilic (has both hydrophilic and hydrophobic parts, but that describes structure, not dual charge). Hint: ''dual/opposite charges on one molecule'' = zwitterion."}'),
  ('f61942a9-5q','{"options": ["Worth’s theory", "Theory of retinal rivalry", "Wall’s theory", "Verhoeff’s theory"], "correct": 2, "explanation": "The description (two identical images projected to one perceptual position via a common/community visual direction) fits the projection-based fusion theory. VERIFY: the named-theory attribution (Worth/Wall/Verhoeff) is obscure and easily mis-keyed, so confirm which theory the source intends; Wall''s is the best fit here."}'),
  ('b67bfe56-2h','{"options": ["Eyes are normally hyperopic at birth", "The first sign of development of fixation is when eyes follow large objects", "Visual acuity is expected to be 20/20 at the age of three", "Foveas are fully formed at the age of 3 months"], "correct": 3, "explanation": "The false statement is that the foveas are fully formed at 3 months; foveal maturation actually continues to about age 4."}'),
  ('b7a87c72-2a','{"options": ["Agonists", "Antagonists", "Synergists", "Yoke muscles"], "correct": 1, "explanation": "In positive vertical divergence (vertical vergence) the two eyes move oppositely (one up, one down). RIR (depresses OD) and LSR (elevates OS) act in OPPOSITE vertical directions on the two eyes, so they are ANTAGONISTS in this disjunctive movement (not yoke/agonist/synergist). Cross-link: contrast Hering''s yoke pairs (conjugate) with disjunctive vergence."}'),
  ('da0032cc-2b','{"options": ["Inferior oblique", "Superior oblique", "Inferior rectus", "Superior rectus"], "correct": 0, "explanation": "With a head tilt to the left, the right eye extorts to keep the image upright, and the inferior oblique is the primary extorter."}'),
  ('d44cf806-29','{"options": ["Flat fusion", "Superimposition", "Simultaneous perception", "Both b and c"], "correct": 0, "explanation": "Almost-identical targets with only MINIMAL disparity test FLAT (2nd-grade) fusion — the ability to fuse near-identical images. Superimposition (1st grade) uses dissimilar targets; simultaneous perception is grade-1; stereopsis (3rd grade) needs larger lateral disparity. Worth''s three grades: superimposition → flat fusion → stereopsis."}'),
  ('65cd743c-2j','{"options": ["Superior rectus", "Inferior rectus", "Superior oblique", "Inferior oblique"], "correct": 1, "explanation": "Hypertropia with incyclorotation points to a weak INFERIOR RECTUS (loss of depression raises the eye; loss of its extorsion leaves relative intorsion)."}'),
  ('e2137417-50','{"options": ["Presence of EPD at OD", "Presence of TAPD at OD", "Presence of TAPD at OS", "Presence of EPD at OS"], "correct": 0, "explanation": "Light at OD with the pupil STATIONARY (no reaction at all, direct or maintained) = an EFFERENT pupillary defect (EPD) at OD — the motor (parasympathetic/CN III) output to that pupil is impaired, so it can''t constrict regardless of input. An RAPD (afferent) would still constrict consensually. EPD = the ''output'' (effector) is broken on that side."}'),
  ('15b9a76a-5h','{"options": ["Refraction", "Interference", "Dispersion", "Diffraction"], "correct": 1, "explanation": "Interference, from waves combining out of step, produces the broad color effects described. VERIFY: the stem is awkwardly worded (it mixes incoherence and color), so confirm; among the options interference best fits color phenomena."}'),
  ('d3ed2e23-3t','{"options": ["Dendron", "Axon", "Physiological connectors", "Synapse"], "correct": 2, "explanation": "Accessory sense-organ structures that protect and modulate the receptors are the ''physiological connectors'' as worded here. VERIFY: this is unusual terminology, so confirm the intended term in the source."}'),
  ('eaf2a41a-x','{"options": ["Physiological anisocoria", "Pathological anisocoria", "Aniseikonia", "Anisometropia"], "correct": 0, "explanation": "A small physiologic difference in pupil size (about half a millimeter or less) is physiological anisocoria. VERIFY: the stem figure is garbled (''5mm''); a benign small difference points to physiological anisocoria, so confirm the source value."}'),
  ('214c2b81-3h','{"options": ["Ventral Stream pathway", "Pupillary Pathway", "Dorsal Pathway", "Visual Pathway"], "correct": 2, "explanation": "The DORSAL (''where/how'') stream (occipito-PARIETAL) processes spatial location, motion, and visually-guided EYE and HAND movements in the environment. The VENTRAL (''what'') stream (occipito-temporal) handles object/form recognition. Mnemonic: Dorsal = ''where/action'' (up to parietal), Ventral = ''what'' (down to temporal)."}'),
  ('c65e254b-2p','{"options": ["Optic nerve", "Retina", "Occipital Lobe (right)", "Lateral Geniculate Body"], "correct": 3, "explanation": "RIGHT homonymous hemianopsia means a LEFT retrochiasmal lesion; among the options the LATERAL GENICULATE BODY (left) fits a complete homonymous hemifield relay lesion. (Optic nerve/retina give monocular defects; right occipital lobe would give LEFT hemianopsia.) The keyed answer localizes to the LGB. Rule: contralateral homonymous loss = lesion on the opposite retrochiasmal pathway."}'),
  ('c97b429e-2f','{"options": ["Right superior homonymous quadratanopsia", "Right Inferior homonymous quadratanopsia", "Right Homonymous Hemianopsia", "Left Inferior homonymous quadratanopsia"], "correct": 3, "explanation": "RIGHT eye, NASAL optic radiation fibers carry the TEMPORAL field of that eye; combined as a homonymous defect this maps to a LEFT INFERIOR homonymous quadrantanopsia (the keyed representation) — locating the affected radiation bundle. Work it through: nasal retina = temporal field; inferior vs superior depends on the radiation loop (Meyer''s = superior field). Use the field-to-fiber map to convert."}'),
  ('1eaffb14-2h','{"options": ["Right superior homonymous quadratanopsia", "Right Inferior homonymous quadratanopsia", "Right Homonymous Hemianopsia", "Left Inferior homonymous quadratanopsia"], "correct": 0, "explanation": "LEFT eye, TEMPORAL optic radiation fibers carry the NASAL field of that eye; as a homonymous defect this presents as a RIGHT SUPERIOR homonymous quadrantanopsia (keyed) — a temporal-lobe (Meyer''s loop) pattern giving a superior ''pie in the sky'' on the right. Convert fiber bundle → field quadrant using the radiation map (temporal loop = superior field)."}'),
  ('65d70464-1x','{"options": ["Confusion with up and down", "Skipping lines when reading", "Omitting words and transposing words when reading", "Experiencing illusory text movement"], "correct": 0, "explanation": "EXCEPT question on OCULAR MOTILITY (eye-movement/tracking) problems. Skipping lines, omitting/transposing words, and illusory text movement all stem from poor saccades/fixation during reading. CONFUSION of up and down is a SPATIAL/directional (laterality) problem, not a motility one, so A is the exception. Distinguish oculomotor (tracking) deficits from visual-spatial (directionality) deficits."}'),
  ('d124d23f-4e','{"options": ["Generalized depression", "Localized depression", "Hemianopsia", "Quadratanopsia"], "correct": 0, "explanation": "Field extents temporal 60 / nasal 40 / superior 50 / inferior 55 — ALL reduced roughly proportionally below normal (temporal should be ~90, etc.) = GENERALIZED (concentric) DEPRESSION of the field, not a focal/localized defect or a hemi-/quadrant pattern. Causes: media opacity, miosis, fatigue, diffuse disease. Localized depression would spare some meridians; hemianopsia respects the midline."}'),
  ('a53d1618-3e','{"options": ["Crystalline lens", "Pupil size", "Dark to light adaptation", "Tear film"], "correct": 2, "explanation": "Bright-sunlight visual disturbance in the elderly is most attributable to slowed DARK-to-LIGHT (and light-to-dark) ADAPTATION with age — the photoreceptor/RPE adaptation kinetics slow, so transitions and glare recovery worsen. Crystalline lens changes and pupil miosis contribute to glare, but the asked aging change is adaptation. Pearl: ageing slows photopigment adaptation → glare/transition trouble."}'),
  ('266e6c2f-32','{"options": ["Trabecular Meshwork", "Scleral spur", "Schlemm’s Canal", "Iris Root"], "correct": 2, "explanation": "CORRECTED ANSWER: Schlemm''s canal (C). The description — ''in cross-section an oval CHANNEL that ENCIRCLES the entire circumference of the anterior chamber'' — is the classic definition of SCHLEMM''S CANAL, the circular collector channel at the limbus draining aqueous from the trabecular meshwork to episcleral veins. The source sheet keyed ''scleral spur'' (a triangular ridge of sclera, an attachment for the ciliary muscle/TM — not a channel). Anatomy: TM → Schlemm''s canal → collector channels → episcleral veins."}'),
  ('d42925e7-53','{"options": ["Pretectal Nucleus", "Ciliary ganglion", "Nerve Fiber", "Lateral Geniculate body"], "correct": 2, "explanation": "First blank: ganglion-cell axons form the NERVE FIBER layer of the retina (vision fibers then synapse in the LGB, pupillary fibers at the pretectal nucleus). VERIFY: this is a multi-blank fill (items 144 to 146) compressed into one MCQ, so confirm how the source scores it; the first blank is the nerve fiber layer."}'),
  ('e5068c97-4k','{"options": ["Macula", "Sensory Retina", "RPE", "Photoreceptors cells", "Peripheral retina"], "correct": 3, "explanation": "The light-detecting portion of the retina comprises the photoreceptor cells (with the RPE), so ''photoreceptor cells'' fills the first blank. VERIFY: this is a multi-blank fill compressed into one MCQ, so confirm the source''s intended matching."}'),
  ('2d1baf52-4x','{"options": ["IV", "I", "II", "III"], "correct": 1, "explanation": "Color deficiency passed from mother to son is X-linked, so the reason is HEREDITARY (I, option B). The classic red-green defects are X-linked recessive: the carrier mother passes the affected X to her son. Diagnosis (II), acquired (III), and evaluation (IV) are testing purposes, not the inheritance cause."}'),
  ('0aed5744-4n','{"options": ["I", "IV", "III", "II"], "correct": 3, "explanation": "Reaching a conclusion about a defect is DIAGNOSIS (II, option D). Hereditary (I) and acquired (III) are causes, and evaluation (IV) is the assessment step; the act of concluding the patient is color blind is the diagnosis."}'),
  ('f40d46fd-4p','{"options": ["III", "III", "IV", "I"], "correct": 0, "explanation": "Color deficiency from drug/substance toxicity is ACQUIRED (III, option A). Hereditary defects are present from birth; a toxic cause developing later is acquired. VERIFY: the printed options A and B both read III here (a source typo), but the intended answer is Acquired (III)."}'),
  ('c5954f1e-5o','{"options": ["I", "II", "III", "IV"], "correct": 3, "explanation": "Running two tests to compare results is part of EVALUATION (IV, option D). Comparing methods cross-checks the finding. Hereditary/acquired are causes and diagnosis is the conclusion; comparison of tests is evaluative."}'),
  ('b82694fd-4k','{"options": ["III", "IV", "I", "II"], "correct": 1, "explanation": "Testing/EVALUATION (IV, option B) comes before and enables a proper diagnosis, so it is the precursor. VERIFY: ''precursor to diagnosis'' is loosely worded; evaluation (the assessment that precedes diagnosis) is the best fit among Hereditary/Acquired/Evaluation."}'),
  ('9e61be20-3r','{"options": ["II", "IV", "I", "III"], "correct": 2, "explanation": "Hyperopia driving an eye turn (accommodative esotropia) is a REFRACTIVE cause (I, option C). Anatomical (II) is a structural fault, neurological (III) is nerve-based, and pathological (IV) is disease-based; uncorrected hyperopia is a refractive etiology."}'),
  ('ff85f1ab-4z','{"options": ["IV", "III", "II", "I"], "correct": 2, "explanation": "A congenital orbital malformation is an ANATOMICAL (structural) cause (II, option C). It is a physical fault of the orbit/muscles rather than a refractive, neurological, or disease process."}'),
  ('d44d1c5d-4i','{"options": ["I", "IV", "II", "III"], "correct": 3, "explanation": "A stroke damages the nerve supply to the eye muscles, so the etiology is NEUROLOGICAL (III, option D). Not refractive, anatomical, or a primary eye disease."}'),
  ('0e892f30-5h','{"options": ["I", "IV", "III", "II"], "correct": 3, "explanation": "Forceps trauma physically damaging the eye muscles is an ANATOMICAL/mechanical cause (II, option D). The muscle structure is injured, not the refraction or nerve pathway per se."}'),
  ('c080c93c-59','{"options": ["III", "II", "I", "IV"], "correct": 2, "explanation": "Accommodative esotropia is fundamentally a REFRACTIVE (hyperopic) cause (I, option C): the uncorrected hyperopia drives excess accommodation and convergence. Surgery corrects the angle but the underlying etiology is refractive."}'),
  ('98fef6e3-61','{"options": ["II", "IV", "III", "I"], "correct": 3, "explanation": "Telling objects apart by their features is VISUAL DISCRIMINATION (I, option D). Spatial relationship (II) is about position relative to other objects, visual memory (III) is recall, and visual closure (IV) is completing partial figures."}'),
  ('8ceb786c-5q','{"options": ["II", "I", "III", "IV"], "correct": 0, "explanation": "Judging where objects sit relative to each other is SPATIAL RELATIONSHIP (II, option A). Discrimination is telling them apart, memory is recall, and closure is filling gaps."}'),
  ('c7d32221-5w','{"options": ["I", "III", "IV", "II"], "correct": 1, "explanation": "Recalling a briefly seen item is VISUAL MEMORY (III, option B). Discrimination, spatial relationship, and closure do not involve remembering a past stimulus."}'),
  ('ce21c385-5n','{"options": ["IV", "II", "I", "III"], "correct": 0, "explanation": "Recognizing the whole from fragments is VISUAL CLOSURE (IV, option A). The brain fills in the missing parts to complete the figure."}'),
  ('162aa540-5s','{"options": ["I", "IV", "III", "II"], "correct": 1, "explanation": "Concluding the whole from only a portion is VISUAL CLOSURE (IV, option B), the same closure skill: completing a partially shown figure."}'),
  ('e1d2c33d-5d','{"options": ["III", "IV", "I", "II"], "correct": 2, "explanation": "The VISUAL FIELD (I, option C) is measured with the eye stationary (fixating), and its outer limits are set by facial anatomy (nose, brow) and retinal sensitivity. Fixation, neural transmission, and perceptual are the other requirements."}'),
  ('e51a65c2-5i','{"options": ["III", "I", "IV", "II"], "correct": 3, "explanation": "The field of FIXATION (II, option D) is the motor field: the solid angle through which the eye can rotate/move its visual axis. This contrasts with the fixed visual field, which is measured with the eye still."}'),
  ('bb822634-57','{"options": ["III", "II", "I", "IV"], "correct": 0, "explanation": "The optic nerve carries the signal, so it is part of NEURAL TRANSMISSION (III, option A). Visual field, fixation, and perceptual are the other requirements; the nerve is the conduction link."}'),
  ('50f62f37-6j','{"options": ["IV", "II", "III", "I"], "correct": 0, "explanation": "Fusing the two eyes'' images into one is a PERCEPTUAL requirement (IV, option A), a brain (sensory fusion) function. Field, fixation, and transmission set the stage; the merging into one percept is perceptual."}'),
  ('f5546399-5k','{"options": ["I", "IV", "III", "II"], "correct": 1, "explanation": "Moulding two monocular images into one percept is the PERCEPTUAL (IV, option B) function (sensory fusion), the same brain-level integration as the previous item."}'),
  ('05b74b02-54','{"options": ["III", "II", "IV", "I"], "correct": 2, "explanation": "Perceiving stimulus across all intensity levels is the LIGHT sense (IV, option C), the retina''s ability to detect a range of luminance. VERIFY: form/contrast/color/light are loosely defined here; light (intensity) is the best fit for ''levels of intensity.''"}'),
  ('e6127be5-3d','{"options": ["II", "IV", "I", "III"], "correct": 1, "explanation": "Rods drive dim-light (scotopic) vision, so the rod-dependent function is the LIGHT sense (IV, option B). VERIFY: rods also serve motion/contrast, but among Form/Contrast/Color/Light the light sense is the classic rod role."}'),
  ('9be0c290-3l','{"options": ["III", "I", "IV", "II"], "correct": 0, "explanation": "Cones mediate COLOR (III, option A) vision (and high acuity). Rods handle light/dim vision; the cone-dependent sensitivity here is color."}'),
  ('3ed6ca36-4o','{"options": ["IV", "III", "I", "II"], "correct": 3, "explanation": "Distinguishing an object from its background by luminance difference is CONTRAST (II, option D) sensitivity. Form, color, and light-intensity alone do not capture object-vs-background separation."}'),
  ('718c35a4-4u','{"options": ["IV", "I", "III", "II"], "correct": 0, "explanation": "White light (all wavelengths combined, before dispersion) is the LIGHT sense (IV, option A). VERIFY: this overlaps with the color category; white/undispersed light is treated here as the light sensitivity."}'),
  ('2ee6b1f0-4k','{"options": ["II", "IV", "III", "I"], "correct": 3, "explanation": "A central scotoma points to the OPTIC NERVE (I, option D) or macula (a central-vision lesion). The chiasma, occipital lobe, and temporal loop give hemianopic (half-field) patterns, not a central island of loss."}'),
  ('6a905961-5g','{"options": ["III", "II", "IV", "I"], "correct": 1, "explanation": "Bitemporal hemianopia localizes to the CHIASMA (II, option B), where the crossing nasal-retinal fibers are compressed (classically by a pituitary tumor)."}'),
  ('0781edd9-57','{"options": ["IV", "II", "III", "I"], "correct": 2, "explanation": "Congruous (well-matched between the two eyes) defects arise POSTERIORLY, in the OCCIPITAL lobe (III, option C). The more anterior the lesion (tract), the more incongruous the defect."}'),
  ('c6cede54-59','{"options": ["I", "II", "IV", "III"], "correct": 2, "explanation": "Incongruous (mismatched) defects arise more anteriorly, in the optic-radiation TEMPORAL LOOP (Meyer''s loop) (IV, option C) or optic tract. Anterior lesions give incongruity; posterior (occipital) lesions give congruity."}'),
  ('3cd86bb6-5q','{"options": ["II", "III", "I", "IV"], "correct": 2, "explanation": "A lesion of the OPTIC NERVE (I, option C) blinds the whole eye on that side (monocular blindness), before the fibers cross at the chiasm. Beyond the chiasm, lesions cause half-field (not whole-eye) loss."}'),
  ('f045a44c-4w','{"options": ["II", "III", "IV", "I"], "correct": 3, "explanation": "Keenest (sharpest) vision is at the MACULA (I, option D), specifically the cone-packed fovea. Intrinsic/extraocular muscles and the visual pathway are not the receptor site."}'),
  ('e93afef5-4x','{"options": ["I", "IV", "II", "III"], "correct": 2, "explanation": "Focusing (accommodation) is done by the ciliary muscle, an INTRINSIC ocular muscle (II, option C). Extraocular muscles aim the eye; the intrinsic ciliary muscle changes lens power for focus."}'),
  ('ada4bf69-4o','{"options": ["IV", "III", "II", "I"], "correct": 1, "explanation": "Eye teaming (aligning and moving the two eyes together) is the job of the EXTRAOCULAR muscles (III, option B). The intrinsic muscles handle focus and pupil, not teaming."}'),
  ('46303ad0-4p','{"options": ["I", "III", "II", "IV"], "correct": 3, "explanation": "Nerve impulses travel along the VISUAL PATHWAY (IV, option D) from retina to cortex. The macula and muscles are not the conduction route."}'),
  ('f4870c31-4s','{"options": ["III", "I", "II", "IV"], "correct": 2, "explanation": "The INTRINSIC (ciliary) muscle (II, option C) can be read as the pace-setter: accommodation drives the near response and its linked convergence. VERIFY: ''pace setter'' is non-standard wording; some may argue the extraocular muscles instead, so confirm against the source key."}'),
  ('ac5c503e-55','{"options": ["III", "IV", "I", "II"], "correct": 1, "explanation": "A thread/string with X, A, V (crossing) responses is the BROCK STRING (IV, option B), used to test convergence and check for suppression. Maddox rod uses a striated lens, bar reading uses a bar, and hole-in-hand uses a tube."}'),
  ('5e1942ee-5t','{"options": ["III", "IV", "I", "II"], "correct": 0, "explanation": "A striated lens that turns a point light into a streak is the MADDOX ROD (III, option A), the classic subjective test for heterophoria."}'),
  ('f140c282-77','{"options": ["IV", "III", "II", "I"], "correct": 2, "explanation": "Holding a pen/bar over the reading material to detect suppression is BAR READING (II, option C): a patient with good binocular vision reads on despite the bar, while a suppressor drops words."}'),
  ('72ad4471-3t','{"options": ["III", "IV", "I", "II"], "correct": 2, "explanation": "Looking through a TUBE with one eye while the other faces the palm (a ''hole'' appears in the hand) is the HOLE-IN-HAND test (I, option C) of simultaneous perception/fusion."}'),
  ('8e5b20b9-44','{"options": ["I & IV", "I & II", "II & III", "IV & III"], "correct": 3, "explanation": "Subjective phoria detection is best done with the MADDOX ROD (III) and the BROCK STRING (IV), so IV & III (option D). Hole-in-hand tests binocularity and bar reading tests suppression, not phoria magnitude. VERIFY: the pairing is debatable since Maddox rod is the strongest single subjective phoria test."}'),
  ('95afae9c-43','{"options": ["II", "IV", "III", "I"], "correct": 3, "explanation": "The EYE (I, option D) is the organ with refractive media (cornea, lens) and light-sensitive retina. The brain interprets, and motor/sensory are systems, not the organ."}'),
  ('e962c57d-43','{"options": ["I", "IV", "III", "II"], "correct": 3, "explanation": "The BRAIN (II, option D) is the CNS organ that receives and interprets the electrical (neural) signals from the eye."}'),
  ('d9932499-3u','{"options": ["IV", "I", "II", "III"], "correct": 3, "explanation": "The MOTOR system (III, option D) (efferent output to muscles) runs through the peripheral nervous system. Sensory input, eye, and brain are the other elements."}'),
  ('88d79172-47','{"options": ["III", "I", "II", "IV"], "correct": 3, "explanation": "The SENSORY system (IV, option D) is input-dependent: with no incoming stimulus there is nothing to react to. Motor is output; sensory is the input side."}'),
  ('5067daa4-3t','{"options": ["IV & I", "II & III", "III & IV", "I & II"], "correct": 2, "explanation": "Afferent = SENSORY (IV) input and efferent = MOTOR (III) output, so III & IV (option C). The eye and brain each have both afferent and efferent components."}'),
  ('da061683-3d','{"options": ["III", "II", "IV", "I"], "correct": 3, "explanation": "The SUPERIOR rectus (I, option D) primarily elevates the eye. Inferior depresses, lateral abducts, medial adducts."}'),
  ('8bddfe96-3e','{"options": ["I", "II", "III", "IV"], "correct": 1, "explanation": "The INFERIOR rectus (II, option B) primarily depresses the eye. Superior elevates; the horizontal recti move the eye side to side."}'),
  ('168c9937-3l','{"options": ["IV", "III", "II", "I"], "correct": 1, "explanation": "Moving the eye AWAY from the nose (abduction) is the primary action of the LATERAL rectus (III, option B). Medial adducts (toward the nose)."}'),
  ('db7410e9-3l','{"options": ["IV", "III", "II", "I"], "correct": 0, "explanation": "Adduction (turning the eye toward the nose) is the primary action of the MEDIAL rectus (IV, option A). Lateral abducts."}'),
  ('886baf63-3o','{"options": ["IV & I", "III & IV", "II & III", "I & II"], "correct": 3, "explanation": "The vertical recti carry adduction as a tertiary action: SUPERIOR rectus (elevate, intort, adduct) and INFERIOR rectus (depress, extort, adduct), so I & II (option D). The horizontal recti have only their single horizontal action."}'),
  ('ef3922ea-4f','{"options": ["I", "III", "II", "IV"], "correct": 0, "explanation": "Cranial nerve VI (abducens) runs the lateral rectus, whose action is ABDUCTION (I, option A)."}'),
  ('dfa7f3e9-4q','{"options": ["IV", "III", "I", "II"], "correct": 3, "explanation": "The strongest of the recti is the medial rectus (CN III), whose action is ADDUCTION (II, option D)."}'),
  ('28859567-4t','{"options": ["II", "I", "III", "IV"], "correct": 2, "explanation": "By the Spiral of Tillaux the farthest insertion (7.7 mm) is the superior rectus, whose action is SUPRADUCTION/elevation (III, option C)."}'),
  ('2c04de81-3n','{"options": ["IV", "II", "I", "III"], "correct": 0, "explanation": "The inferior rectus depresses the eye, so its action is INFRADUCTION (IV, option A)."}'),
  ('dfd5175e-4c','{"options": ["II & III", "IV & I", "I & II", "III & IV"], "correct": 2, "explanation": "The horizontal recti (medial and lateral) act in a single plane, so they have only a primary horizontal action (ABDUCTION and ADDUCTION), no secondary/tertiary components, giving I & II (option C). The vertical recti and obliques all have secondary/tertiary torsion and horizontal actions."}'),
  ('29937ee2-4a','{"options": ["III", "IV", "I", "II"], "correct": 2, "explanation": "CN VI palsy weakens the lateral rectus, so the eye cannot abduct and turns in: ESOTROPIA (I, option C)."}'),
  ('95106559-3w','{"options": ["I", "III", "II", "IV"], "correct": 2, "explanation": "The strongest muscle is the medial rectus; its paralysis removes adduction, so the eye drifts out: EXOTROPIA (II, option C)."}'),
  ('84b562a6-4t','{"options": ["II", "I", "III", "IV"], "correct": 2, "explanation": "The farthest insertion is the superior rectus (an elevator); paralyzed, the eye cannot elevate and sits low: HYPOTROPIA (III, option C)."}'),
  ('0e0d1724-3t','{"options": ["II", "IV", "I", "III"], "correct": 1, "explanation": "The inferior rectus depresses; paralyzed, the eye cannot look down and drifts up: HYPERTROPIA (IV, option B)."}'),
  ('9d6ef6e5-3m','{"options": ["I & II", "III & IV", "IV & I", "II & III"], "correct": 0, "explanation": "Horizontal deviations are ESOTROPIA (in) and EXOTROPIA (out), so I & II (option A). Hypo/hypertropia are vertical."}'),
  ('65ff02e0-6u','{"options": ["III", "II", "IV", "I"], "correct": 2, "explanation": "The uncrossed (non-decussating) fibers carry the nasal fields; damaging them on both sides gives BINASAL hemianopia (IV, option C). (Crossing fibers, by contrast, give bitemporal loss.)"}'),
  ('d67d2719-6d','{"options": ["III", "II", "I", "IV"], "correct": 0, "explanation": "The decussating (crossing) nasal-retinal fibers serve the temporal fields, so their compression gives BITEMPORAL hemianopia (III, option A), the classic pituitary sign."}'),
  ('ddc654c3-5a','{"options": ["I", "III", "II", "IV"], "correct": 0, "explanation": "A left optic tract lesion drops the RIGHT half-fields of both eyes: RIGHT HOMONYMOUS hemianopia (I, option A). The tract carries the contralateral field."}'),
  ('c8265f79-59','{"options": ["I", "III", "II", "IV"], "correct": 2, "explanation": "A right optic tract lesion drops the LEFT half-fields of both eyes: LEFT HOMONYMOUS hemianopia (II, option C)."}'),
  ('f0c30bd0-5l','{"options": ["IV", "I", "II", "III"], "correct": 2, "explanation": "The right LGN, like the right tract, serves the left visual field, so a lesion gives LEFT HOMONYMOUS hemianopia (II, option C)."}'),
  ('ef4c1e40-3x','{"options": ["II", "IV", "I", "III"], "correct": 2, "explanation": "Monocular rotations (ductions) test eye movement, a MOTOR (I, option C) skill (oculomotor control)."}'),
  ('aa70ebc2-4a','{"options": ["I", "IV", "III", "II"], "correct": 3, "explanation": "Amplitude of accommodation is grouped here under the SENSORY/visual-efficiency category (II, option D). VERIFY: accommodation involves the ciliary muscle (a motor act) and is sometimes classed separately, so the category is debatable."}'),
  ('082a1a84-45','{"options": ["IV", "III", "II", "I"], "correct": 1, "explanation": "Recognizing and identifying what is seen is a COGNITIVE (III, option B) skill (perception/processing), not a motor or sensory-intake task."}'),
  ('d9742020-3y','{"options": ["IV", "II", "III", "I"], "correct": 0, "explanation": "Eye-hand coordination combines vision with motor output, so it is INTEGRATION (IV, option A) (visual-motor integration)."}'),
  ('ab8dd609-4y','{"options": ["II", "III", "I", "IV"], "correct": 3, "explanation": "Placing shapes/colors in order combines perception with motor placement, an INTEGRATION (IV, option D) task. VERIFY: the organizing/sequencing element could also be read as cognitive, so confirm against the key."}'),
  ('102cee1d-5k','{"options": ["II", "IV", "III", "I"], "correct": 3, "explanation": "With the eye open, atmospheric oxygen dissolves in the TEAR FILM (I, option D), the cornea''s main oxygen source. The tear film is the interface that lets air-oxygen reach the avascular cornea."}'),
  ('de454503-4p','{"options": ["III", "II", "I", "IV"], "correct": 1, "explanation": "The PALPEBRAL CONJUNCTIVAL capillaries (II, option B) line the inner eyelids and supply oxygen to the front of the cornea when the eye is closed."}'),
  ('8480e9b9-5s','{"options": ["II", "IV", "III", "I"], "correct": 2, "explanation": "The LIMBAL capillaries (III, option C) sit at the limbus, the cornea-sclera border, feeding the peripheral cornea."}'),
  ('ff0487cd-4s','{"options": ["IV", "III", "II", "I"], "correct": 0, "explanation": "The corneal endothelium faces the anterior chamber, so it draws most of its oxygen from the AQUEOUS humor (IV, option A)."}'),
  ('e0d96e1d-4w','{"options": ["IV & I", "III & IV", "II & III", "I & II"], "correct": 2, "explanation": "With the lids closed in sleep, atmospheric oxygen is cut off, so the cornea relies on the PALPEBRAL CONJUNCTIVAL and LIMBAL vessels (II & III, option C). VERIFY: the aqueous also supplies the endothelium, so some keys pair the answer differently; the closed-eye vascular sources are conjunctival and limbal."}'),
  ('a06c2923-56','{"options": ["IV", "II", "I", "III"], "correct": 2, "explanation": "The PERIMETER (I, option C) maps the full extent of the visual field out to its peripheral limits. Confrontation is crude, tangent screen and Amsler test only the central field."}'),
  ('1e72a4a2-5v','{"options": ["IV", "I", "II", "III"], "correct": 2, "explanation": "CONFRONTATION (II, option C) is the crude bedside method: the examiner compares the patient''s field to their own (which must be normal). No instrument is used."}'),
  ('ef6f3ebe-66','{"options": ["II", "IV", "I", "III"], "correct": 3, "explanation": "The TANGENT (Bjerrum) SCREEN (III, option D) tests the central 30 degrees, where most clinically significant field changes appear."}'),
  ('09ef727b-51','{"options": ["III", "I", "IV", "II"], "correct": 2, "explanation": "The AMSLER GRID (IV, option C) assesses the central field (about 10 to 20 degrees) around fixation, ideal for macular (metamorphopsia/scotoma) changes."}'),
  ('4d4f14ba-51','{"options": ["I", "III", "II", "IV"], "correct": 0, "explanation": "The PERIMETER (I, option A) is the most reliable, standardized instrument for mapping the full extent of the visual field."}'),
  ('b162b030-3c','{"options": ["IV", "III", "I", "II"], "correct": 0, "explanation": "The highest frequency band here (600 to 689 THz) is BLUE (IV, option A). Higher frequency means shorter wavelength, toward the blue/violet end."}'),
  ('f3bd2c75-3c','{"options": ["I", "III", "IV", "II"], "correct": 1, "explanation": "The 530 to 624 THz band is GREEN (III, option B), sitting between yellow and blue in frequency."}'),
  ('ae7891d3-3c','{"options": ["IV", "III", "I", "II"], "correct": 3, "explanation": "The 508 to 540 THz band is YELLOW (II, option D), just above red/orange in frequency."}'),
  ('18235a2e-3c','{"options": ["II", "III", "I", "IV"], "correct": 2, "explanation": "The lowest frequency band (405 to 479 THz) is RED (I, option C). Lower frequency means longer wavelength, the red end."}'),
  ('dcb9ed1e-39','{"options": ["IV", "II", "I", "I"], "correct": 2, "explanation": "RED (I, option C) has the longest wavelength (and lowest frequency) of the visible colors. Blue/violet have the shortest. Mnemonic: ROYGBIV runs long-to-short wavelength."}'),
  ('29d27429-53','{"options": ["III", "I", "IV", "II"], "correct": 2, "explanation": "Trichromatic (normal three-cone) color vision needs healthy photopigments, which depend on VITAMIN A (IV, option C). Ethambutol, chloroquine, and AMD damage color vision; vitamin A supports it."}'),
  ('fa36b57e-4z','{"options": ["II", "IV", "I", "III"], "correct": 2, "explanation": "ETHAMBUTOL (I, option C) causes optic neuropathy with classic red-green color loss, which is why vision is monitored during TB treatment."}'),
  ('796d29cc-54','{"options": ["II", "III", "IV", "I"], "correct": 0, "explanation": "AGE-RELATED MACULAR DEGENERATION (II, option A) is linked to acquired blue-yellow (tritan) defects. VERIFY: chloroquine toxicity can also produce blue-yellow loss, so this pairing is debatable against the source key."}'),
  ('be4f1e7e-4k','{"options": ["IV", "III", "II", "I"], "correct": 1, "explanation": "CHLOROQUINE (III, option B) retinopathy (bull''s-eye maculopathy) is taken here as the blue-defect cause. VERIFY: acquired blue defects overlap between chloroquine and AMD, so confirm the intended pairing with the source."}'),
  ('fc7a654a-55','{"options": ["III", "I", "II", "IV"], "correct": 3, "explanation": "Ethambutol, AMD, and chloroquine all damage color vision, but VITAMIN A (IV, option D) supports normal color vision rather than causing a defect, so it is the EXCEPT."}'),
  ('77c37b2d-2t','{"options": ["I", "II", "III", "IV"], "correct": 0, "explanation": "The optic nerve is cranial nerve 2, so ordinal I=2 (option A). (I optic, II oculomotor, III trochlear, IV abducens are 2, 3, 4, 6 in this legend.)"}'),
  ('d1e3237d-2y','{"options": ["III", "IV", "I", "II"], "correct": 3, "explanation": "The oculomotor nerve is cranial nerve 3, so II=3 (option D)."}'),
  ('9a1b77c0-2y','{"options": ["I", "III", "IV", "II"], "correct": 1, "explanation": "The trochlear nerve is cranial nerve 4, so III=4 (option B)."}'),
  ('9c6bf6ff-2v','{"options": ["II", "IV", "I", "III"], "correct": 1, "explanation": "The abducens nerve is cranial nerve 6, so IV=6 (option B)."}'),
  ('51b6ff77-2u','{"options": ["III", "I", "II", "IV"], "correct": 1, "explanation": "Cranial nerves 3, 4, and 6 are the ocular MOTOR nerves. Cranial nerve 2 (the optic nerve) is SENSORY, so I=2 (option B) is the EXCEPT."}'),
  ('72756a63-59','{"options": ["I", "III", "II", "IV"], "correct": 0, "explanation": "Crawling develops GROSS MOTOR (I, option A) skills, the large-muscle movement base that later supports finer skills."}'),
  ('9a6947fd-4x','{"options": ["IV", "III", "I", "II"], "correct": 3, "explanation": "Awareness of the body''s two sides is LATERALITY (II, option D), the internal sense of left and right within one''s own body."}'),
  ('fd4a1357-4y','{"options": ["I", "IV", "III", "II"], "correct": 2, "explanation": "Projecting directions (right/left, up/down) into external space is DIRECTIONALITY (III, option C), which builds on laterality."}'),
  ('5437356d-4m','{"options": ["III", "I", "IV", "II"], "correct": 2, "explanation": "Recognizing shapes and patterns is FORM PERCEPTION (IV, option C), a visual-perceptual skill."}'),
  ('48fdfdc5-45','{"options": ["II", "III", "IV", "I"], "correct": 3, "explanation": "GROSS MOTOR (I, option D) control develops first and is the precursor to fine motor skills (large muscles before small)."}'),
  ('bf9318ad-3b','{"options": ["II", "I", "IV", "III"], "correct": 1, "explanation": "PHYSIOLOGY (I, option B) is the study of the normal functioning of the body''s systems."}'),
  ('494e8f9c-4k','{"options": ["IV", "I", "III", "II"], "correct": 3, "explanation": "NEUROLOGY (II, option D) studies the nervous system and its diseases."}'),
  ('9db8fdab-3e','{"options": ["III", "I", "II", "IV"], "correct": 0, "explanation": "PSYCHOLOGY (III, option A) is the science of mind and behavior."}'),
  ('50bdbbb9-4d','{"options": ["I", "II", "III", "IV"], "correct": 3, "explanation": "OPTICS (IV, option D) is the science of light and its behavior/effects."}'),
  ('ea6854bb-6t','{"options": ["II", "I", "IV", "III"], "correct": 3, "explanation": "Concern with how the person adapts to their environment (not just light physics) is the PSYCHOLOGY (III, option D) dimension of vision."}'),
  ('fb823483-4g','{"options": ["II", "IV", "I", "III"], "correct": 2, "explanation": "CN VI palsy weakens the lateral rectus, so ABDUCTION (I, option C) is lost and the eye cannot turn out."}'),
  ('2029c2c0-4f','{"options": ["IV", "II", "I", "III"], "correct": 1, "explanation": "The strongest muscle is the medial rectus; paralyzed, ADDUCTION (II, option B) is lost."}'),
  ('7883ec96-5k','{"options": ["II", "I", "III", "IV"], "correct": 2, "explanation": "The farthest insertion is the superior rectus; paralyzed, SUPRADUCTION/elevation (III, option C) is lost."}'),
  ('cace9488-4j','{"options": ["IV", "I", "II", "III"], "correct": 0, "explanation": "The inferior rectus depresses the eye, so its paralysis loses INFRADUCTION (IV, option A)."}'),
  ('bbcdd46d-44','{"options": ["IV & I", "II & III", "III & IV", "I & II"], "correct": 2, "explanation": "Vertical eye movements are SUPRADUCTION and INFRADUCTION (III & IV, option C); abduction/adduction are horizontal."}'),
  ('8c0666b7-4f','{"options": ["III", "IV", "I", "II"], "correct": 2, "explanation": "The sensation of things in motion is MOVEMENT (I, option C), the perception of change of position over time."}'),
  ('558a2a48-48','{"options": ["II", "I", "IV", "III"], "correct": 3, "explanation": "Color perception comes from the visible-spectrum WAVELENGTHS, 390 to 700 nm (III, option D). Different wavelengths are seen as different colors."}'),
  ('3d88ac49-4y','{"options": ["IV", "II", "I", "III"], "correct": 0, "explanation": "Light is a form of ENERGY (IV, option A), which can be transformed into other forms of power (for example electrical, as in phototransduction or solar cells)."}'),
  ('4b46ba2a-4j','{"options": ["IV", "II", "III", "I"], "correct": 1, "explanation": "Recognizing an object''s form is the SHAPE (II, option B) sensation. Movement, wavelength, and energy describe other attributes."}'),
  ('9414fd2c-6z','{"options": ["I", "IV", "II", "III"], "correct": 3, "explanation": "A rainbow is white light split into its component WAVELENGTHS, 390 to 700 nm (III, option D). VERIFY: the stem says ''diffraction'' but describes dispersion/refraction; the color-producing property is the wavelength spread."}'),
  ('5dd203a4-4a','{"options": ["III", "II", "I", "IV"], "correct": 3, "explanation": "RUNNING (IV, option D) is a purely gross-motor recreation. Copying letters and following dots are visual-motor; responding to a name is auditory."}'),
  ('a9986052-3w','{"options": ["I", "IV", "II", "III"], "correct": 2, "explanation": "RESPONDING WHEN THE NAME IS CALLED (II, option C) is a purely auditory task. The others involve vision/motor output."}'),
  ('bd9a5a05-5y','{"options": ["III", "IV", "II", "I"], "correct": 0, "explanation": "FOLLOWING THE DOTS (III, option A) tests ocular tracking, the mechanical (oculomotor) visual-motor system: the eyes must smoothly pursue targets."}'),
  ('d8d14ef7-6p','{"options": ["IV", "II", "I", "III"], "correct": 2, "explanation": "COPYING LETTERS (I, option C) is duplication guided by vision and verbalization, integrating visual, perceptual, and motor skills."}'),
  ('1bfce9f6-5y','{"options": ["II", "IV", "III", "I"], "correct": 3, "explanation": "COPYING LETTERS (I, option D) best displays the full integration of visual input, perceptual processing, and motor output (writing). VERIFY: overlaps with the previous copying item, so the intended distinct answer may differ."}'),
  ('bd19900c-4h','{"options": ["III", "I", "IV", "II"], "correct": 1, "explanation": "Visible LIGHT (I, option B) is the band of the electromagnetic spectrum (a particular group of wavelengths) that the eye can see."}'),
  ('6aa57f4d-3r','{"options": ["I", "IV", "II", "III"], "correct": 2, "explanation": "The EYE (II, option C) is the sensory organ that admits and focuses light to begin the process of seeing."}'),
  ('99746a39-3t','{"options": ["III", "II", "IV", "I"], "correct": 0, "explanation": "The visual pathway (nerves, tracts, cortex) is the NEURO (III, option A) element that carries and processes the signal."}'),
  ('2122b91c-4w','{"options": ["II", "III", "IV", "I"], "correct": 2, "explanation": "Phototransduction is a photochemical event, so the transformation is CHEMICAL (IV, option C): light triggers a chemical cascade in the photoreceptors that generates the electrical signal."}'),
  ('fe9a83d6-4w','{"options": ["III", "IV", "II", "I"], "correct": 3, "explanation": "Without LIGHT (I, option D) there is no stimulus to see; light is the indispensable factor for vision."}'),
  ('aaac5198-3a','{"options": ["Light perception", "Counting finger", "Light projection", "Hand motion"], "correct": 1, "explanation": "If the patient can count fingers, the acuity is recorded as COUNTING FINGERS (CF). It ranks above hand motion but below readable Snellen acuity. The low-vision ladder: CF, then hand motion, then light projection, then light perception."}'),
  ('19c01b8c-2u','{"options": ["Color test", "Light projection", "Light perception", "Hand motion"], "correct": 3, "explanation": "Detecting a moving hand (but not counting fingers) is recorded as HAND MOTION (HM), one step below counting fingers on the low-vision scale."}'),
  ('b89845d8-3a','{"options": ["Light projection", "Color test", "Counting finger", "Light perception"], "correct": 0, "explanation": "Correctly localizing where a light comes from is LIGHT PROJECTION (LProj): the patient perceives light AND its direction, one step above bare light perception."}'),
  ('39c4be42-3d','{"options": ["Light perception", "Color test", "Counting finger", "Light projection"], "correct": 0, "explanation": "Perceiving only the presence or absence of light (no direction) is LIGHT PERCEPTION (LP), the lowest measurable vision above no light perception (NLP)."}'),
  ('2185b3af-3t','{"options": ["Counting finger", "Light projection", "Color test", "Light perception"], "correct": 3, "explanation": "Bare LIGHT PERCEPTION (option D) only says light is present, giving no information about the fovea specifically, so it is the least useful for checking foveal sensitivity. Color testing (foveal cones) and light projection (retinal localization) probe more localized function. VERIFY: light projection is also gross, so the intended ''not a fovea test'' answer may vary by key."}'),
  ('89b6e1d0-70','{"options": ["I", "III", "IV", "II"], "correct": 0, "explanation": "A defect stretching from fixation (centro-) to the blind spot (-cecal) is the CENTROCECAL scotoma (I, option A), a horizontal oval linking the two, seen in toxic/nutritional optic neuropathies."}'),
  ('7663f306-63','{"options": ["III", "II", "I", "IV"], "correct": 1, "explanation": "A field defect the patient does not notice and that shows up only on testing is a NEGATIVE scotoma (II, option B). (A positive scotoma is one the patient actively sees.) VERIFY: the stem''s ''black spot'' wording is contradictory with ''unaware''; the ''detected only by examination'' clue points to negative."}'),
  ('23b92c15-5e','{"options": ["I", "III", "IV", "II"], "correct": 1, "explanation": "The optic disc has no photoreceptors, producing the normal PHYSIOLOGIC scotoma (III, option B), the blind spot everyone has."}'),
  ('7d2bf763-56','{"options": ["II", "I", "IV", "III"], "correct": 2, "explanation": "A depressed area at the SIDE (edge) of the field is a PERIPHERAL scotoma (IV, option C), away from the central/paracentral zone."}'),
  ('4e75078b-5q','{"options": ["III", "I", "IV", "II"], "correct": 0, "explanation": "An enlarging blind spot means the PHYSIOLOGIC scotoma (III, option A) is expanding, a concern that flags optic-disc pathology (for example papilledema)."}'),
  ('47919c6f-4z','{"options": ["III", "I", "II", "IV"], "correct": 1, "explanation": "Not putting the correct lens for the test distance is a WRONG PRESCRIPTION error (I, option B): an uncorrected refractive blur can mimic a field defect."}'),
  ('0d01d64b-5z','{"options": ["IV", "III", "I", "II"], "correct": 3, "explanation": "Poorly worded directions to the patient are INADEQUATE INSTRUCTIONS (II, option D), which produce unreliable responses that can look like field loss."}'),
  ('3cde9e8d-4m','{"options": ["IV", "III", "I", "II"], "correct": 1, "explanation": "A stimulus that is TOO DIM (III, option B) is an intensity error: a target below the seeing threshold falsely appears as a defect."}'),
  ('e18e6d4d-5c','{"options": ["III", "I", "IV", "II"], "correct": 2, "explanation": "A stimulus that is TOO SMALL (IV, option C) plots an isopter too small to encompass the blind spot, an error of target size."}'),
  ('591768c5-5a','{"options": ["IV", "II", "I", "III"], "correct": 1, "explanation": "Ambiguous directions (INADEQUATE INSTRUCTIONS, II, option B) let the patient respond too cautiously or too eagerly, skewing the result."}'),
  ('8ccf15f7-5o','{"options": ["IV", "II", "I", "III"], "correct": 2, "explanation": "Retinitis pigmentosa is a retinal disease, so it falls under EYE HEALTH (I, option C). Refractive error, ocular motility, and accommodation are the other efficiency areas."}'),
  ('84da6cd6-5k','{"options": ["III", "II", "IV", "I"], "correct": 1, "explanation": "Needing a +4.00 sphere is a REFRACTIVE ERROR (II, option B) (hyperopia), an optical, not a health or motility, issue."}'),
  ('cd418ef0-4v','{"options": ["IV", "III", "I", "II"], "correct": 1, "explanation": "A paralyzed medial rectus is an OCULAR MOTILITY (III, option B) problem: the extraocular muscle system is impaired."}'),
  ('9bac783e-5d','{"options": ["III", "I", "IV", "II"], "correct": 2, "explanation": "A near add (plano distance, +3.00 add) addresses focusing at near, so the concern is ACCOMMODATIVE (IV, option C) efficiency."}'),
  ('605a3aa9-5s','{"options": ["IV", "III", "I", "II"], "correct": 2, "explanation": "A cataract is an ocular disease, so it falls under EYE HEALTH (I, option C)."}'),
  ('e3c7311f-3x','{"options": ["III", "IV", "I", "II"], "correct": 2, "explanation": "The MEIBOMIAN glands (I, option C) secrete the lipid (oil) layer of the tear film, which retards evaporation. Lacrimal/accessory make the aqueous; goblets make mucin."}'),
  ('fc927bb5-5k','{"options": ["II", "III", "IV", "I"], "correct": 0, "explanation": "The main LACRIMAL gland (II, option A) produces the aqueous and drives REFLEX tearing (in response to irritation or emotion)."}'),
  ('bbf6d31c-4j','{"options": ["I", "III", "IV", "II"], "correct": 1, "explanation": "The ACCESSORY lacrimal glands of Krause and Wolfring (III, option B) provide the basal (basic) aqueous secretion, the steady baseline tear production."}'),
  ('32c92dd2-4b','{"options": ["I", "II", "III", "IV"], "correct": 3, "explanation": "GOBLET cells (IV, option D) are specialized epithelial cells (not glands) that secrete the mucin layer of the tear film."}'),
  ('53abbdb7-3m','{"options": ["IV", "I", "II", "III"], "correct": 0, "explanation": "The bulk of the tear film (the aqueous) is secreted by GLANDS (lacrimal, accessory), whereas the mucin comes from GOBLET cells (IV, option A), which are cells, not glands, so goblets are the EXCEPT. VERIFY: the meibomian oil is also a minority component, so the intended answer may vary by key."}'),
  ('1db29658-5o','{"options": ["Worth’s theory", "Theory of retinal rivalry", "Wall’s theory", "Verhoeff’s theory"], "correct": 2, "explanation": "Wall''s (Worth''s projection) theory holds that single binocular vision is a sensory PROJECTION of two identical retinal images to one perceptual locus, fused because they share a common visual direction. Worth''s theory frames fusion as a learned instinct in grades (superimposition→flat fusion→stereopsis); retinal rivalry and Verhoeff describe other fusion models. Cross-link: ties to the Doctrine of Corresponding Points (Q28) — identical points share a visual direction."}'),
  ('83307d6e-3a','{"options": ["Angle alpha", "Angle lambda", "Angle gamma", "Angle beta"], "correct": 2, "explanation": "Angle gamma is between the LINE OF SIGHT and the OPTIC AXIS, met near the center of rotation (~13.5 mm behind cornea). Compare: angle alpha = visual axis vs optic axis (at nodal point); angle lambda = line of sight vs pupillary axis; angle kappa (clinical) ≈ lambda. Cross-link: angle kappa positive = pseudo-exotropia, a Hirschberg pitfall (Q43)."}'),
  ('4ab2ebd5-2d','{"options": ["Eyes are normally hyperopic at birth", "The first sign of development of fixation is when eyes follow large objects", "Visual acuity is expected to be 20/20 at the age of three", "Foveas are fully formed at the age of 3 months"], "correct": 1, "explanation": "EXCEPT (not-true) question. The FIRST sign of fixation development is following a LIGHT, not large objects, so B is the false statement = answer. True facts: newborns are physiologically hyperopic (A); 20/20 by ~3 yr (C); foveal maturation by a few months (D). Cross-link: the visual critical period (to ~7-8 yr) underlies amblyopia treatment windows."}'),
  ('79b3db48-33','{"options": ["Dextroinfraversion", "Dextrosupraversion", "Levoinfraversion", "Levosupraversion"], "correct": 2, "explanation": "ANTAGONISTS RSO + LIR: RSO depresses/intorts OD, LIR depresses OS — together they pull the eyes DOWN and to the LEFT = levoinfraversion. (They are listed as antagonists across the two eyes but as a version produce down-left.) Use the muscle-action grid: RSO acts down-in-torsion; pairing with LIR gives the left-down field. Mnemonic: ''levo'' = left, ''infra'' = down."}'),
  ('4e310bf3-29','{"options": ["Inferior oblique", "Superior oblique", "Inferior rectus", "Superior rectus"], "correct": 0, "explanation": "Head tilt to the LEFT triggers the ocular counter-roll: OD must INTORT to stay vertical, and the right INFERIOR OBLIQUE is the intortor that is the agonist here (the IO and SO are the torsional muscles; SR/IR have secondary torsion). Bielschowsky/Park''s 3-step logic builds on this. Mnemonic: ''tilt left → right eye intorts → IO (and SR) intort; IO is the answer.''"}'),
  ('04c35e91-2v','{"options": ["Levosupraversion", "Levoinfraversion", "Dextrosupraversion", "Dextroinfraversion"], "correct": 3, "explanation": "Dextroinfraversion (down and to the right). RIR depresses the abducted right eye and LSO depresses the adducted left eye, the yoke pair for down-right gaze. Hint: RIR + LSO = depressors for right gaze = dextrodepression."}'),
  ('22e551df-23','{"options": ["Most extra ocular muscle is innervated by the occulomotor nerve", "All extraocular muscle except inferior rectus originate from the annulus of zinn*", "Medial rectus is the strongest and broadest muscle, and has the closest insertion from limbus", "Superior rectus is the longest extraocular muscle if the tendon is excluded"], "correct": 1, "explanation": "FALSE statement = answer. NOT all EOMs except IR arise from the annulus of Zinn — actually the INFERIOR OBLIQUE arises from the orbital floor (maxilla), and it''s the IO (not IR) that is the exception; the four recti and SO originate at/near the annulus of Zinn. So B is false. True: most EOMs are CN III (A); MR is the strongest, closest insertion to limbus (C); SR is longest (D). Pearl: ''IO is the odd one out — it starts at the orbital floor.''"}'),
  ('3d80ec7e-1u','{"options": ["Presence of alternating deviation", "There is diplopic awareness", "Presence of NRC or ARC", "Unilateral functional amblyopia"], "correct": 0, "explanation": "''Alternating deviation'' is the EXCEPT, alternation protects against amblyopia and typifies infantile/congenital esotropia. Acquired esotropia is usually unilateral with diplopic awareness, ARC/NRC, and unilateral amblyopia. Hint: alternation = congenital pattern; acquired ET tends to be unilateral."}'),
  ('44559fe8-26','{"options": ["Suppression of the deviating eye", "Diplopia", "NRC", "Fusion"], "correct": 3, "explanation": "Fusion, seeing a single PINK light means the red (filtered) image and the white image are superimposed into one, so the eyes are fusing. Hint: pink = red + white blended into one = fusion."}'),
  ('c891e041-34','{"options": ["5 prism", "10 prism", "20 prism", "35 prism"], "correct": 2, "explanation": "About 20 prism diopters is roughly the smallest horizontal tropia obvious to the naked eye (direct observation). Some sources cite a bit less, VERIFY. Hint: small tropias hide; a deviation becomes plainly visible around 20 prism diopters."}'),
  ('cf68abcf-20','{"options": ["Physiologic diplopia", "proximal diplopia", "pathologic diplopia", "distal diplopia"], "correct": 2, "explanation": "Pathologic diplopia, double vision caused by a manifest strabismus/squint. Physiologic diplopia is the normal doubling of non-fixated objects. Hint: squint-caused double vision = pathologic; normal off-fixation doubling = physiologic."}'),
  ('c430d44e-3m','{"options": ["100 seconds of an arc", "200 seconds of an arc", "20 seconds of an arc", "40 seconds of an arc"], "correct": 3, "explanation": "40 seconds of arc, recognizing all nine Titmus circle sets corresponds to the finest 40-arcsec threshold. Hint: all 9 circles right = the best Titmus score = 40 arcsec."}'),
  ('86e95d8f-3u','{"options": ["Stereoscopic effect", "True fusion", "Simultaneous macular perception", "Accommodation"], "correct": 1, "explanation": "True fusion (Grade II) is deficient, the inability to combine the two eyes'' images into one is a fusion failure. Hint: ''cannot make two images one'' = fusion (Grade II) problem."}'),
  ('07f5b647-2z','{"options": ["Grade I only", "Grade II only", "Grade III only", "No binocular vision"], "correct": 1, "explanation": "Grade II only, the patient fuses (Grade II) but has no stereopsis (Grade III). Hint: fusion without depth = up to Grade II only."}'),
  ('2301c508-3a','{"options": ["Stereopsis", "True fusion", "Simultaneous macular perception", "Vergence"], "correct": 2, "explanation": "Simultaneous macular perception (Grade I) is checked first, you must confirm both foveas perceive at once (no suppression) before testing fusion or stereo. Hint: rule out suppression at Grade I before moving up."}'),
  ('c079d6bb-36','{"options": ["Accommodation", "Stereoscopic effect", "Color perception", "Visual acuity"], "correct": 1, "explanation": "Stereoscopic effect (stereopsis), depth judgment (as in parking) is a stereopsis function. Hint: judging distance/depth = stereopsis."}'),
  ('90c00618-35','{"options": ["Retinal disease", "Binocular vision anomalies", "Cataract", "Corneal dystrophy"], "correct": 1, "explanation": "Binocular vision anomalies, near headaches/eyestrain in a child point first to accommodative/vergence (binocular) problems. Hint: reading eyestrain in a child = think binocular vision first."}'),
  ('5fe624c2-3q','{"options": ["Sensory", "Motor", "Perceptual", "Refractive"], "correct": 2, "explanation": "Perceptual, interpreting/assigning meaning to what is seen. Hint: ''brain interprets'' = perceptual processing."}'),
  ('f7dc7f95-33','{"options": ["Sensory", "Perceptual", "Motor", "Cognitive"], "correct": 2, "explanation": "Motor, holding foveal fixation while tracking is an eye-movement (motor) task. Hint: keeping the target on the fovea while it moves = motor (pursuit) system."}'),
  ('dc18fae6-28','{"options": ["Accommodative excess", "Accommodative insufficiency", "Convergence excess", "Divergence excess"], "correct": 1, "explanation": "Accommodative insufficiency, reduced ability to focus at near. Hint: can''t crank up enough focus = accommodative INsufficiency."}'),
  ('1f6b6886-37','{"options": ["Ill-sustained accommodation", "Accommodative spasm", "Paralysis of accommodation", "Convergence insufficiency"], "correct": 0, "explanation": "Ill-sustained accommodation, focus starts fine but fatigues/cannot be held through prolonged near work. Hint: fades with time = ill-sustained (a fatigue variant of insufficiency)."}'),
  ('ca5c82bf-2h','{"options": ["Accommodative infacility", "Accommodative excess", "Divergence insufficiency", "Exotropia"], "correct": 0, "explanation": "Accommodative infacility, trouble changing focus quickly between near and far. Hint: slow to shift focus = infacility (a flexibility problem)."}'),
  ('7b1f9f41-2q','{"options": ["Convergence excess", "Divergence excess", "Convergence insufficiency", "Divergence insufficiency"], "correct": 2, "explanation": "Convergence insufficiency, reduced convergence during near work (with a receded NPC and exo at near). Hint: eyes can''t hold in for reading = convergence insufficiency."}'),
  ('82ddcd67-2j','{"options": ["Incomitant strabismus", "Concomitant strabismus", "Neurogenic strabismus", "Mechanical strabismus"], "correct": 1, "explanation": "Concomitant strabismus, the angle is the same in every direction of gaze. Hint: CONcomitant = Constant angle in all gazes."}'),
  ('4a6728d6-2k','{"options": ["Concomitant", "Incomitant", "Esophoria", "Orthophoria"], "correct": 1, "explanation": "Incomitant strabismus, the deviation changes with gaze direction (typical of a nerve palsy or restriction). Hint: angle varies with gaze = INcomitant."}'),
  ('c91fbdfd-1w','{"options": ["Mechanical", "Myogenic", "Neurogenic", "Concomitant"], "correct": 2, "explanation": "Neurogenic strabismus, a sixth-nerve palsy is a nerve (neurogenic) cause. Hint: cranial-nerve palsy = neurogenic strabismus."}'),
  ('b49f40c7-26','{"options": ["Mechanical strabismus", "Neurogenic strabismus", "Convergence insufficiency", "Accommodative insufficiency"], "correct": 0, "explanation": "Mechanical (restrictive) strabismus, orbital scarring physically limits the muscle. Hint: a physical tether/scar = mechanical/restrictive."}'),
  ('24c6360d-35','{"options": ["Suppression", "Diplopia", "Amblyopia", "ARC"], "correct": 1, "explanation": "Diplopia, the double vision from misaligned images. (True sensory adaptations that follow are suppression and ARC.) Hint: two images seen = diplopia; the brain''s fix for it is suppression."}'),
  ('fc443690-2f','{"options": ["Suppression", "Amblyopia", "Eccentric fixation", "Diplopia"], "correct": 2, "explanation": "Eccentric fixation, the eye fixates with a non-foveal retinal point (a monocular sign, often in amblyopia). Hint: fixating off the fovea = eccentric fixation."}'),
  ('249b53f9-2g','{"options": ["Diplopia", "Suppression", "Stereopsis", "Fusion"], "correct": 1, "explanation": "Suppression, the brain inhibits one eye''s image to avoid confusion/diplopia. Hint: brain ''switches off'' an eye = suppression."}'),
  ('80387676-2a','{"options": ["Saccadic dysfunction", "Pursuit dysfunction", "Nystagmus", "Vergence dysfunction"], "correct": 2, "explanation": "Nystagmus, involuntary rhythmic oscillation of the eyes. Hint: rhythmic to-and-fro eye movement = nystagmus."}'),
  ('b3c5ed0a-24','{"options": ["A cause of binocular anomalies", "A symptom only", "A treatment effect", "A sensory adaptation"], "correct": 0, "explanation": "A cause of binocular anomalies, reduced acuity in one eye can drive binocular dysfunction (it is a cause, not just a symptom). Hint: one weak eye can CAUSE the binocular breakdown."}'),
  ('cf6293f2-12','{"options": ["Relative Negative", "Absolute Negative", "Relative Positive", "Absolute Positive"], "correct": 1, "explanation": "The physiologic blind spot (optic disc, no photoreceptors) is an ABSOLUTE NEGATIVE scotoma — absolute (nothing seen) and negative (the patient is unaware of it, since it''s filled in perceptually). Positive scotomas are noticed by the patient (e.g., a dark patch). Anatomic basis: the disc has no rods/cones."}'),
  ('064136f5-23','{"options": ["Decussating Optic Chiasm", "Non-decussating Optic Chiasm", "Left Optic Tract", "Right Optic Tract"], "correct": 1, "explanation": "BI-NASAL heteronymous hemianopsia = loss of both nasal fields, from lesions hitting the UNCROSSED (temporal) fibers on BOTH lateral aspects of the chiasm (e.g., bilateral compression) — the ''non-decussating'' fibers. Bitemporal loss = central chiasm (crossing nasal fibers, classic pituitary). Binasal is rare; it hits the lateral chiasm. Cross-link: chiasm anatomy (Q90)."}'),
  ('0c384396-5k','{"options": ["Presence of EPD at OD", "Presence of TAPD at OD", "Presence of TAPD at OS", "Presence of EPD at OS"], "correct": 0, "explanation": "Efferent pupillary defect (EPD) at OD, the right pupil fails to constrict to either its own light or the consensual stimulus (a motor/output failure). Hint: one pupil never moves (direct or consensual) = efferent (motor) defect in that eye."}'),
  ('a9fa0e62-6m','{"options": ["Presence of RAPD at OD", "Presence of TAPD at OD", "Presence of TAPD at OS", "Presence of RAPD at OS"], "correct": 3, "explanation": "RAPD at OS, when the light swings to the left eye the pupil dilates (escapes) instead of holding, the hallmark of a relative afferent defect in the illuminated (left) eye. Hint: pupil DILATES when light reaches it = RAPD in that eye."}'),
  ('85cd65e0-6w','{"options": ["Right optic nerve lesion causing monocular temporal field loss", "Left occipital lobe lesion causing homonymous hemianopia with macular sparing", "Lesion at the optic chiasm compressing nasal fibers", "Lesion of the right lateral geniculate nucleus affecting both eyes"], "correct": 1, "explanation": "A right homonymous hemianopsia (right eye loses temporal field, left eye loses nasal field, both are the RIGHT half), pointing to a LEFT occipital lesion (often with macular sparing). Hint: both eyes lose the same (right) half = homonymous = contralateral (left) occipital lesion."}'),
  ('545a6738-93','{"options": ["There is a left relative afferent pupillary defect (RAPD)", "There is a right relative afferent pupillary defect (RAPD)", "There is a left efferent pupillary defect", "There is a right efferent pupillary defect"], "correct": 1, "explanation": "Right RAPD, swinging to the right eye makes both pupils dilate instead of constrict (the worse-acuity, ARMD-affected right eye has the relative afferent defect). Hint: dilation on swinging TO an eye = RAPD in that eye."}'),
  ('f695488c-3u','{"options": ["Bowman''s membrane", "corneal stroma", "corneal endothelium", "anterior corneal epithelium"], "correct": 2, "explanation": "The corneal endothelium, its pump keeps the stroma deturgesced; endothelial damage lets fluid in and the cornea swells (edema). Hint: the endothelial pump keeps the cornea clear and dry, lose it and it floods."}'),
  ('b69496d6-1o','{"options": ["Phototransduction", "Accommodation", "color perception", "pupillary constriction only"], "correct": 1, "explanation": "Accommodation, the ciliary muscle changes lens shape to focus, so its lesion impairs accommodation. Hint: ciliary muscle = the focusing (accommodation) muscle."}'),
  ('0f0f362e-2c','{"options": ["ganglion cell layer", "inner nuclear layer", "nerve fiber layer", "photoreceptor cell layer"], "correct": 3, "explanation": "The photoreceptor (outer) layer draws most of its supply from the choriocapillaris. The inner retina is fed by the central retinal artery. Hint: outer retina/photoreceptors = choroidal supply; inner retina = retinal artery."}'),
  ('0e7c1215-1b','{"options": ["contains abundant blood vessels", "collagen fibers are irregularly arranged", "maintains controlled water content and organized collagen", "absorbs all incoming light"], "correct": 2, "explanation": "Controlled water content (endothelial deturgescence) plus regularly arranged collagen keep the cornea clear. Vessels or disordered collagen would scatter light. Hint: clear cornea = dry (deturgesced) + orderly collagen + avascular."}'),
  ('a71abfcb-37','{"options": ["Reflection", "Refraction", "Dispersion", "polarization"], "correct": 2, "explanation": "Dispersion, a prism spreads white light into its wavelengths because each color refracts by a slightly different amount. Hint: rainbow from a prism = dispersion (wavelength-dependent refraction)."}'),
  ('446a3ae5-1x','{"options": ["Outer segment", "Inner segment", "Synaptic body", "Nucleus"], "correct": 0, "explanation": "The OUTER segment houses the visual pigment (stacked discs of rhodopsin/iodopsin). Hint: photopigment lives in the outer segment discs."}'),
  ('c8f35b59-2p','{"options": ["GABA", "Serotonin", "Glutamate", "Dopamine"], "correct": 2, "explanation": "Glutamate is the photoreceptor''s neurotransmitter (released in the dark, reduced by light). Hint: photoreceptors talk with glutamate."}'),
  ('f3d38b00-1y','{"options": ["Excitatory postsynaptic potential (EPSP)", "inhibitory postsynaptic potential (IPSP)", "Closure of sodium gated channels", "Opening of sodium gated channels"], "correct": 2, "explanation": "Closure of sodium-gated (cGMP-gated) channels, light closes them, Na+ influx stops, and the cell HYPERpolarizes. Hint: light -> shut the Na+ gates -> hyperpolarize (the odd ''off'' response of photoreceptors)."}'),
  ('316f2e28-14','{"options": ["Bipolar cells", "Horizontal cells", "rods", "Cones"], "correct": 1, "explanation": "Horizontal cells mediate lateral inhibition (sharpening contrast across the retina). Hint: horizontal cells spread sideways = lateral inhibition."}'),
  ('029735d5-26','{"options": ["W cells", "X cells", "Y cells", "Z cells"], "correct": 0, "explanation": "W cells, slow-conducting ganglion cells receiving substantial rod input. Hint: W = ''weak/slow,'' rod-linked; X = detail/color; Y = fast/motion."}'),
  ('a4f8bce8-15','{"options": ["W cells", "X cells", "Y cells", "Z cells"], "correct": 2, "explanation": "Y cells are the largest, fastest ganglion cells (transient, motion, magnocellular). Hint: Y = ''zippy,'' the big fast motion cells."}'),
  ('a2778c41-1s','{"options": ["cAMP", "cGMP", "Tyrosinase", "RXR"], "correct": 1, "explanation": "cGMP, in phototransduction, activated phosphodiesterase (PDE) hydrolyzes cGMP, closing the channels. Hint: light -> PDE chews up cGMP -> channels close."}'),
  ('94ca582a-1h','{"options": ["Ito cells", "Nephrons", "Pulmonary lobule", "Paneth cells"], "correct": 0, "explanation": "Ito cells (hepatic stellate cells) are the body''s main vitamin A store. Hint: liver Ito cells = the vitamin A warehouse (feeding the visual cycle)."}'),
  ('544eeaf2-1s','{"options": ["Retinal isomerase", "Retinal hydroxylase", "Retinal dehydrogenase", "Retinalase"], "correct": 0, "explanation": "Retinal isomerase reconverts all-trans retinal back to 11-cis retinal (regenerating the pigment). Hint: ''isomerase'' flips trans back to cis to reload rhodopsin."}'),
  ('4c927af9-1l','{"options": ["OCA1", "OCA2", "Albinism", "Avitaminosis A"], "correct": 0, "explanation": "OCA1 (oculocutaneous albinism type 1) is the tyrosinase-deficient form. ''Albinism'' is the general term; OCA1 names the tyrosinase defect. Hint: OCA1 = tyrosinase-negative albinism."}'),
  ('ca3f0a22-23','{"options": ["RPE pigment granules move toward ELM", "Cone inner segments move toward ELM", "Rod outer segments elongate markedly", "Ganglion cells shift toward vitreous"], "correct": 1, "explanation": "Cone inner segments contract toward the ELM as the first retinomotor response to light (rods elongate, RPE pigment migrates). Sources vary on which change is ''first,'' so VERIFY. Hint: in light, cones pull IN (toward ELM), rods stretch OUT, pigment spreads."}'),
  ('05e777e6-1s','{"options": ["Iris pigmentation and melanin content", "Blood supply and oxygen availability", "Pupil diameter under scotopic conditions", "Intraocular pressure fluctuations"], "correct": 1, "explanation": "Blood supply and oxygen availability, the retina is highly metabolic and oxygen-dependent. Hint: the retina is an oxygen glutton, so its metabolism tracks blood/oxygen supply."}'),
  ('ebaca361-2l','{"options": ["It stabilizes photopigments and prevents electron liberation", "It replaces retinal and converts photons to mechanical energy", "It blocks unstable compounds and absorbs all visible wavelengths", "It sensitizes electrolytic solutions and emits electrons under light"], "correct": 3, "explanation": "Fluorescein sensitizes the solution and liberates (emits) electrons under light, acting as a photosensitizer in these classic retinal-stimulation experiments. Hint: as a photosensitizer, fluorescein turns absorbed light into electron liberation."}'),
  ('e9f7ca48-2r','{"options": ["About 620 nm corresponding to orange light", "About 530 nm corresponding to green light", "About 480 nm corresponding to blue light", "About 580 nm corresponding to yellow light"], "correct": 1, "explanation": "About 530 nm (green), near the photopic sensitivity peak (~555 nm) where the light-adapted eye''s electrical response is greatest. If the key lists ~560 to 580, that is the same peak region, VERIFY. Hint: photopic (light-adapted) peak sits in the yellow-green, ~555 nm."}'),
  ('b44ad72b-21','{"options": ["Once threshold is reached, impulse size is maximal", "Increasing stimulus always increases impulse amplitude", "Impulse intensity scales with light wavelength only", "Subthreshold stimuli produce proportionate small impulses"], "correct": 0, "explanation": "All-or-none: once threshold is reached, the impulse is maximal (a bigger stimulus does not make a bigger spike). Hint: threshold reached = full-size impulse, always."}'),
  ('6eee5f0c-2g','{"options": ["A permanent blind spot called a scotoma", "A pupillary constriction called miosis", "A loss of color vision called achromatopsia", "A luminous ring called a pressure phosphene"], "correct": 3, "explanation": "A pressure phosphene, firm scleral pressure in the dark mechanically excites the retina and you ''see'' a luminous ring/spot. Hint: press the eye in the dark and you see light = a phosphene."}'),
  ('767309af-2d','{"options": ["Decreased atmospheric oxygen pressure reduces retinal oxygenation", "Increased ultraviolet exposure directly damages photopigments", "Reduced barometric pressure shrinks the pupil mechanically", "Lower temperature slows rhodopsin regeneration markedly"], "correct": 0, "explanation": "Lower atmospheric oxygen pressure at altitude reduces retinal oxygenation, dulling sensitivity (early night-vision loss). Hint: thin air -> less oxygen to the oxygen-hungry retina."}'),
  ('e7d4ee33-2m','{"options": ["Green region around middle wavelengths", "Blue-violet region at shortest wavelengths", "Yellow region near photopic peak", "Red region near long wavelengths"], "correct": 0, "explanation": "The dark-adapted (rod) system is most sensitive around the green/blue-green (scotopic peak ~507 nm), the Purkinje shift toward shorter wavelengths. If the key emphasizes ''blue-violet,'' that reflects the same shift, VERIFY. Hint: dark adaptation shifts peak sensitivity toward blue-green (~500 nm)."}'),
  ('4a9ae57a-28','{"options": ["Mesopic retina during cone dominance", "Light-adapted retina under photopic conditions", "Unadapted retina during abrupt illumination", "Dark-adapted retina under scotopic conditions"], "correct": 3, "explanation": "The dark-adapted (scotopic) retina has the LOWEST threshold (highest sensitivity) for detecting light. Hint: dark-adapted eyes catch the faintest light (lowest threshold)."}'),
  ('0a9a534c-2b','{"options": ["pH 7.0 after photobleaching", "pH 7.3 in dark adaptation", "pH 6.8 under dim illumination", "pH 7.6 during intense light"], "correct": 1, "explanation": "About pH 7.3 in dark adaptation (Bondi-stain data). These exact retinal-pH figures come from older physiology sources, so VERIFY. Hint: dark-adapted retinal pH is set slightly alkaline (~7.3) in this classic data."}'),
  ('a3107db3-19','{"options": ["longest wavelength and high frequency", "longest wavelength and low frequency", "shortest wavelength and high frequency", "shortest wavelength and low frequency"], "correct": 1, "explanation": "Red light has the LONGEST wavelength and therefore the LOWEST frequency (wavelength and frequency are inversely related). Hint: long wavelength = low frequency; red is the long, slow end."}'),
  ('333963ea-18','{"options": ["longest wavelength and high frequency", "longest wavelength and low frequency", "shortest wavelength and high frequency", "shortest wavelength and low frequency"], "correct": 1, "explanation": "Same as before, red light = longest wavelength, lowest frequency. Hint: red = long wavelength, low frequency (opposite of violet)."}'),
  ('cfeabd9c-2r','{"options": ["Rhodopsin", "Iodopsin", "Melanopsin", "Retinal"], "correct": 2, "explanation": "Melanopsin is the photopigment of intrinsically photosensitive retinal ganglion cells (ipRGCs). Hint: ipRGCs run on melanopsin (the circadian pigment)."}'),
  ('244a5ea5-1y','{"options": ["Motion detection", "High Color Sensitivity", "High spatial resolution", "Fine detail discrimination"], "correct": 0, "explanation": "Motion detection is the magnocellular signature (large, fast, contrast/motion, colorblind). Hint: MAGNO = Motion/Movement (big, fast cells)."}'),
  ('5bfe0b1b-22','{"options": ["Magnocellular neurons have smaller receptive fields than parvocellular neurons", "Parvocellular neurons have faster conduction velocities", "Parvocellular neurons are color-insensitive", "Magnocellular neurons are more sensitive to low contrast stimuli"], "correct": 3, "explanation": "Magnocellular neurons are more sensitive to low-contrast stimuli (and fast/motion). Parvocellular handle color and fine detail. Hint: magno = low-contrast/motion champions; parvo = color/detail."}'),
  ('1815491b-2i','{"options": ["Lateral geniculate nucleus", "Superior colliculus", "Suprachiasmatic nucleus", "Visual cortex"], "correct": 2, "explanation": "ipRGCs project to the suprachiasmatic nucleus (SCN), the circadian clock. Hint: SCN = the body clock; ipRGCs set it by light."}'),
  ('9a8abeb3-21','{"options": ["Cornea", "Aqueous humor", "Lens nucleus", "Vitreous humor"], "correct": 2, "explanation": "The lens NUCLEUS has the highest refractive index (~1.40 to 1.41), higher than the cornea (1.376). Hint: the dense lens core bends light most, highest index."}'),
  ('fd35337a-20','{"options": ["Cornea", "Lens cortex", "Aqueous humor", "Retina"], "correct": 2, "explanation": "Aqueous humor''s index (~1.336) is closest to water (1.33). Hint: aqueous is basically water optically, index ~1.336."}'),
  ('4c622a97-33','{"options": ["it is bent towards the normal.", "it always lies along the normal.", "it is unaffected.", "it is bent away from the normal."], "correct": 0, "explanation": "Entering a slower (denser) medium at an angle, light bends TOWARD the normal. Hint: into a slower medium = bend toward the normal (like a car slowing on one side)."}'),
  ('c37006ae-1s','{"options": ["Bends away from the normal", "No bending occurs", "Bends toward the normal", "Gets totally reflected"], "correct": 2, "explanation": "Air into cornea (denser, slower) = bends toward the normal. Hint: air-to-cornea = speed drops = bend toward the normal."}'),
  ('54fd1ea8-2k','{"options": ["Violet, Blue, Green, Yellow, Red", "Red, Orange, Yellow, Green, Violet", "Red, Orange, Yellow, Green, Blue, Violet", "Violet, Indigo, Blue, Green, Yellow, Red"], "correct": 2, "explanation": "Increasing frequency runs Red, Orange, Yellow, Green, Blue, Violet (red = lowest frequency, violet = highest). Hint: ROYGBIV goes from low to high frequency (red low, violet high)."}'),
  ('8ad32c8c-2q','{"options": ["UV-C", "UV-B", "UV-A", "Both UV-A and UV-B"], "correct": 0, "explanation": "UV-C does NOT reach the surface, the ozone layer absorbs it. Hint: UV-C is the most dangerous but ozone blocks it; UV-A/B get through."}'),
  ('0d1400ff-1v','{"options": ["All colors focus at the same point.", "Shorter wavelengths are refracted less than longer wavelengths.", "Blue light has a shorter focal length than red light.", "It occurs only in multifocal lenses."], "correct": 2, "explanation": "TRUE: blue light has a shorter focal length than red (it is refracted more), the essence of longitudinal chromatic aberration. Hint: blue bends more -> focuses sooner (shorter focal length) than red."}'),
  ('30867307-1e','{"options": ["Two refracting surfaces", "Three refracting surfaces", "A single refracting surface with one principal point", "Four refracting surfaces"], "correct": 2, "explanation": "The reduced eye is modeled as a SINGLE refracting surface with one principal point (and one nodal point). Hint: reduced eye = one surface, simplest model."}'),
  ('b0f59330-1p','{"options": ["Retina", "Vitreous", "Cornea and crystalline lens", "Optic nerve"], "correct": 2, "explanation": "The cornea and crystalline lens absorb most UV-B (protecting the retina). Hint: the front optics (cornea + lens) soak up UV-B."}'),
  ('b3267372-4m','{"options": ["Reduced Eye", "Gullstrand Exact Eye", "Listing Eye", "Emsley Reduced Eye"], "correct": 1, "explanation": "The Gullstrand exact (schematic) eye uses multiple refracting surfaces and gradient-index optics for the most accurate model. Hint: ''exact/gradient index'' = Gullstrand; ''single surface'' = reduced eye."}'),
  ('ac61d947-1c','{"options": ["The refractive index is constant for all wavelengths.", "Shorter wavelengths are refracted more than longer wavelengths.", "Longer wavelengths are refracted more than shorter wavelengths.", "Lens power changes with pupil size."], "correct": 1, "explanation": "Longitudinal chromatic aberration occurs because shorter wavelengths are refracted MORE than longer ones. Hint: short (blue) bends more than long (red), so they focus at different depths."}'),
  ('66210e40-12','{"options": ["It readily reaches the retina.", "It is the least energetic UV radiation.", "It causes tanning.", "It is commonly used for germicidal disinfection."], "correct": 3, "explanation": "TRUE: UV-C is used for germicidal disinfection (it is highly energetic; ozone normally blocks it). Hint: UV-C = germicidal lamps (most energetic UV)."}'),
  ('94a77ebb-21','{"options": ["The IOL is positioned closer to the retina.", "The IOL is positioned farther from the retina (more anterior).", "The IOL is tilted.", "The IOL is decentered."], "correct": 1, "explanation": "Moving a PLUS IOL FARTHER from the retina (more anterior) increases its effective power. Hint: shift a plus lens forward (away from retina) = more effective plus power."}'),
  ('3dfc77c6-1y','{"options": ["UV-A", "UV-B", "UV-C", "All penetrate equally"], "correct": 0, "explanation": "UV-A penetrates deepest (longest wavelength) into skin and ocular tissue. Hint: UV-A = ''Aging/deep'' (reaches the lens/retina)."}'),
  ('3c505b83-1q','{"options": ["Moving the object farther away.", "Increasing the object size or bringing it closer.", "Wearing sunglasses.", "Reducing pupil size."], "correct": 1, "explanation": "Enlarging the object or bringing it closer increases the visual angle (and retinal image size). Hint: bigger or closer = bigger visual angle."}'),
  ('a86ca597-25','{"options": ["Optical axis", "Pupillary axis", "Visual axis", "Line of sight"], "correct": 2, "explanation": "The visual axis links the fixation point, the nodal point(s), and the fovea. Hint: fixation-to-nodal-to-fovea = visual axis."}'),
  ('1f3851c2-10','{"options": ["Visual axis and pupillary axis", "Optical axis and pupillary axis", "Optical axis and visual axis", "Optical axis and line of sight"], "correct": 0, "explanation": "Angle kappa is between the VISUAL axis and the PUPILLARY axis. Hint: kappa = pupillary vs visual axis (alpha = optical vs visual)."}'),
  ('1f516bdd-1b','{"options": ["A posterior shift increases the effective power of a plus IOL.", "An anterior shift decreases the effective power of a plus IOL.", "An anterior shift increases the effective power of a plus IOL.", "IOL position does not affect postoperative refraction."], "correct": 2, "explanation": "TRUE: an ANTERIOR shift increases a plus IOL''s effective power (posterior shift decreases it). Hint: plus lens forward = more power; backward = less."}'),
  ('ac6c2d39-38','{"options": ["Fixation axis", "Line of sight", "Visual axis", "Optical axis"], "correct": 0, "explanation": "The fixation axis connects the fixation point to the eye''s center of rotation. Hint: fixation point straight to the center of rotation = fixation axis."}'),
  ('60894d44-65','{"options": ["Angle Alpha", "Angle Gamma", "Angle Kappa", "Angle Lambda"], "correct": 2, "explanation": "Angle kappa is what the corneal-reflex-versus-pupil-center test clinically estimates. (Strictly, the reflex-to-line-of-sight version is angle lambda, so if the key says lambda, that is why.) Hint: clinically we call the reflex-vs-pupil offset angle kappa."}'),
  ('3021a42e-t','{"options": ["Large Pupil", "Small Pupil", "High Myopia", "Accommodation"], "correct": 1, "explanation": "A small pupil increases depth of focus (and depth of field), like stopping down a camera. Hint: smaller pupil (aperture) = greater depth of focus."}'),
  ('6dfe9e85-17','{"options": ["Thickness", "Radius of Curvature", "Focal Length", "Refractive Index"], "correct": 2, "explanation": "Dioptric power is inversely proportional to focal length (P = 1/f). Hint: shorter focal length = stronger power (inverse)."}'),
  ('e21d1778-1e','{"options": ["Lens Thickness", "Axial Length", "Corneal Curvature", "Pupil Size"], "correct": 1, "explanation": "Axial length is the most important factor in retinal image size. Hint: a longer eye spreads the image out more, axial length rules image size."}'),
  ('4c7be9c9-y','{"options": ["Accommodation", "Convergence", "Pupil Constriction", "Divergence"], "correct": 3, "explanation": "Divergence is NOT part of the near triad (accommodation, convergence, and pupil constriction/miosis). Hint: near reflex = focus + converge + constrict; divergence is the odd one out."}'),
  ('e34c6ade-12','{"options": ["Corneal curvature change", "Lens shape change", "Pupil dilation", "Vitreous movement"], "correct": 1, "explanation": "Accommodation is achieved by changing LENS shape (the lens rounds up). Hint: focusing near = the lens gets fatter (shape change)."}'),
  ('58ca5314-18','{"options": ["High vascularity", "Pigmented cells", "Endothelial pump function", "Thick Bowman’s membrane"], "correct": 2, "explanation": "Corneal transparency is maintained mainly by endothelial PUMP function (deturgescence). Hint: the endothelial pump keeps the cornea dry and clear."}'),
  ('896fb5d9-18','{"options": ["Infero-nasal orbit", "Supero-lateral orbit", "Infero-temporal orbit", "Supero-nasal orbit"], "correct": 1, "explanation": "The main lacrimal gland sits in the SUPERO-LATERAL (superotemporal) orbit, in its own fossa. Hint: tears come from up-and-out (superotemporal) and drain down-and-in."}'),
  ('bffd35ec-15','{"options": ["20% of ocular volume", "40%", "60%", "80%"], "correct": 3, "explanation": "The vitreous fills about 80% (roughly four-fifths) of the ocular volume. Hint: vitreous = the big posterior filler, about 4/5 of the globe."}'),
  ('bd48c4f5-1a','{"options": ["Flatter", "Thinner", "More Convex", "Rigid"], "correct": 2, "explanation": "When the ciliary muscle contracts, zonules slacken and the lens becomes MORE convex (rounder) for near focus. Hint: ciliary contracts -> zonules loosen -> lens fattens (more convex)."}'),
  ('83b3641f-18','{"options": ["Bipolar Cells", "Horizontal cells", "Ganglion cells", "Muller cells"], "correct": 2, "explanation": "Ganglion cells give rise to the optic nerve (their axons form it). Hint: ganglion-cell axons = the optic nerve."}'),
  ('17edeffd-17','{"options": ["Produce tears", "Nourish photoreceptors", "Produce aqueous humor", "Transmit light energy"], "correct": 1, "explanation": "The RPE nourishes and supports the photoreceptors (and recycles pigment, absorbs stray light). Hint: RPE = the photoreceptors'' support/nurse layer."}'),
  ('7942bfb1-1c','{"options": ["Iris color", "Pupil diameter", "Lens color", "Corneal thickness"], "correct": 1, "explanation": "Blur-circle size depends mainly on pupil diameter (a larger pupil makes a bigger blur circle). Hint: bigger pupil = bigger blur circle."}'),
  ('6386147a-11','{"options": ["Large pupil", "Small Pupil", "Increase accommodation only", "Increase axial length"], "correct": 1, "explanation": "A small pupil increases depth of field. Hint: small aperture = more in focus (greater depth of field)."}'),
  ('d50f64b7-1k','{"options": ["The nerve impulse becomes weaker as it travels.", "The nerve impulse loses part of its energy during conduction.", "The nerve impulse maintains its strength as it travels along the nerve fiber.", "The nerve impulse stops after reaching the first synapse."], "correct": 2, "explanation": "Conduction without decrement: the impulse keeps its full strength as it travels the fiber. Hint: no fading, the action potential is regenerated all along."}'),
  ('d3b0e766-1u','{"options": ["Maximum stimulus", "Subliminal stimulus", "Threshold stimulus", "Supernormal stimulus"], "correct": 2, "explanation": "The threshold stimulus is the minimum needed to produce a response. Hint: the just-enough stimulus = threshold."}'),
  ('1cf2c0e2-15','{"options": ["Less excitable or completely unresponsive.", "More excitable.", "Conducting faster.", "Undergoing muscle contraction."], "correct": 0, "explanation": "During the refractory period the nerve is less excitable or completely unresponsive. Hint: refractory = ''recovering,'' hard or impossible to fire again."}'),
  ('1bc4ad57-1f','{"options": ["Permit recovery before another impulse can be generated.", "Allow repeated firing without recovery.", "Increase nerve fatigue", "Reduce blood supply."], "correct": 0, "explanation": "The refractory period permits recovery before another impulse can fire (and enforces one-way, spaced conduction). Hint: refractory period = a mandatory reset before the next spike."}'),
  ('b9db6c32-1g','{"options": ["Increasing stimulus strength increase", "Once threshold is reached, the response is maximal.", "Every stimulus causes the same muscle contraction.", "Subliminal stimuli produce small action potentials"], "correct": 1, "explanation": "All-or-none: once threshold is reached, the response is maximal. Hint: threshold met = full response, no partial spikes."}'),
  ('509a4a76-2t','{"options": ["The size of the action potential.", "The specific nerve pathway stimulated.", "The duration of the impulse.", "The strength of the nerve membrane"], "correct": 1, "explanation": "By the specific nerve pathway stimulated (the labeled-line / law of specific nerve energies), not by spike size. Hint: WHICH nerve fires decides the sensation, not how big the spike is."}'),
  ('7db90959-2i','{"options": ["A continuous uninterrupted stream.", "Random electrical discharges", "Distinct rhythmic pulses or gushes", "Chemical waves."], "correct": 2, "explanation": "Distinct rhythmic pulses/gushes, the optic-nerve signal after light is a train of discrete impulses, not a steady stream. Hint: nerves fire in rhythmic bursts of spikes, not a continuous current."}'),
  ('4747081e-1z','{"options": ["Synapse", "Muscle contraction", "Nerve impulse", "Neuromuscular junction"], "correct": 2, "explanation": "The action potential is the inseparable accompaniment of the nerve impulse. Hint: nerve impulse = its action potential, one and the same event."}'),
  ('85fa7e16-3x','{"options": ["Hutchinson’s", "Amaurotic", "Horner’s", "Adies"], "correct": 0, "explanation": "Hutchinson''s pupil, a fixed, dilated, usually unilateral pupil from a CNS lesion compressing the oculomotor (third) nerve (e.g., uncal herniation). Hint: blown, fixed, dilated pupil from compression = Hutchinson''s."}'),
  ('44957e6c-2h','{"options": ["Lower stream", "Upper stream", "“What”", "V5/MT"], "correct": 1, "explanation": "The upper (dorsal) stream, the ''where/how'' pathway that guides eye-hand and spatial action. Hint: dorsal/UPPER stream = ''where/how'' (action, eye-hand); ventral/lower = ''what.''"}'),
  ('f8810137-2y','{"options": ["Turns upwards and outwards", "Turns upwards and inwards", "Turns downwards and outwards", "Turns downwards and inwards"], "correct": 0, "explanation": "Up and outwards. A right fourth-nerve (superior oblique) palsy leaves the inferior oblique unopposed, so the right eye drifts up (hypertropia), extorted, and slightly out. Some texts stress only the hypertropia, VERIFY the horizontal component. Hint: SO palsy = the eye rides UP (and extorted); unopposed IO also abducts (out)."}'),
  ('acece274-2w','{"options": ["Levosupraversion", "Levoinfraversion", "Dextrosupraversion", "Dextroinfraversion"], "correct": 3, "explanation": "RIR (depresses OD) + LSO (depresses OS) act together — both DEPRESS — taking the eyes DOWN and to the RIGHT = dextroinfraversion. Use the action grid again: this is a yoke down-right pairing. ''Dextro'' right, ''infra'' down."}'),
  ('49c2e73b-2i','{"options": ["Superior rectus", "Inferior rectus", "Superior oblique", "Inferior oblique"], "correct": 1, "explanation": "Relative HYPERtropia (the eye sits higher) plus INCYCLOrotation of the involved eye points to a weak depressor/extortor — the INFERIOR RECTUS (which depresses and EXTORTS). A weak IR lets the eye drift up and intort relative to normal. (SO weakness gives hypertropia with EXtorsion and the classic head tilt; here the torsion clue points to IR.) Use the action grid to match the sign pattern."}'),
  ('c0361ce7-4b','{"options": ["Intermittent exotropia", "Accommodative esotropia", "Alternating hypertropia"], "correct": 1, "explanation": "[Source-review: 3 options extracted.] Inward deviation appearing ONLY at near/accommodation in a young hyperope = ACCOMMODATIVE ESOTROPIA — accommodation drives convergence via the AC/A ratio. Treatment is full plus correction (± bifocals if high AC/A, Q58). Intermittent exotropia is an outward, fatigue-related turn; alternating hypertropia is vertical. High-yield pediatric pearl."}'),
  ('76827281-43','{"options": ["Constant exotropia", "Intermittent exotropia", "Constant esotropia", "Intermittent hypertropia"], "correct": 1, "explanation": "An outward deviation that surfaces with FATIGUE/daydreaming (fusional control lapses) = INTERMITTENT EXOTROPIA, the most common childhood exo. Constant exo/eso are always manifest; intermittent hypertropia is vertical. Pearl: ''exo worse when tired/sick/inattentive'' = intermittent exotropia; managed with VT (Q53) ± surgery."}'),
  ('dc9a94b5-3m','{"options": ["Unilateral hypertropia", "Alternating hypertropia", "Unilateral hypotropia", "Intermittent hypertropia"], "correct": 0, "explanation": "One eye CONSISTENTLY higher while the fellow eye fixates = UNILATERAL (constant) HYPERTROPIA. ''Alternating'' would switch between eyes; intermittent comes and goes. Naming rule: name vertical deviations by the HIGHER eye (hyper-) and by laterality/constancy."}'),
  ('b31334f4-3u','{"options": ["Unilateral esotropia", "Alternating esotropia", "Constant exotropia", "Alternating exotropia"], "correct": 1, "explanation": "Inward deviation that SWITCHES between either eye taking up fixation = ALTERNATING ESOTROPIA. Alternation usually means good (equal) acuity in both eyes, so amblyopia risk is low (each eye gets used). Unilateral eso would keep one eye turned (amblyopia risk). Pearl: alternating = protects against amblyopia."}'),
  ('11d13ece-3q','{"options": ["Latent exotropia", "Intermittent exotropia", "Constant exotropia", "Alternating exotropia"], "correct": 2, "explanation": "A CONSTANT outward turn that does NOT change with cover (always manifest) = CONSTANT EXOTROPIA. ''Latent'' (exophoria) only appears under cover; intermittent comes and goes. Constancy + manifest-under-all-conditions defines it."}'),
  ('c6f0fed3-35','{"options": ["Infantile esotropia", "Accommodative esotropia", "Sensory esotropia", "Paralytic esotropia"], "correct": 0, "explanation": "Inward deviation present SINCE BIRTH and NOT changed by accommodation = INFANTILE (congenital) ESOTROPIA — large, constant angle, onset <6 months, often with cross-fixation. Accommodative eso appears later (~2-3 yr) and responds to plus; sensory eso follows monocular vision loss. Early surgery preserves binocularity."}'),
  ('1725b197-45','{"options": ["Intermittent exotropia", "Manifest exotropia", "Latent exotropia (exophoria)", "Constant exotropia"], "correct": 2, "explanation": "Deviation that appears ONLY when an eye is COVERED (dissociated) and is absent with both eyes open = LATENT exotropia = EXOPHORIA. Fusion controls it when both eyes view; covering breaks fusion and reveals it. Intermittent/constant exo are at least sometimes manifest. Cover test logic: phoria = movement only on cover/uncover."}'),
  ('8c47a779-3r','{"options": ["Brown syndrome", "Duane syndrome", "Fourth nerve palsy", "Sixth nerve palsy"], "correct": 2, "explanation": "Right HYPERtropia worse on LEFT gaze (and typically worse on right head tilt) = FOURTH (trochlear) NERVE palsy of the SO. Park''s 3-step: hyper OD → worse on contralateral (left) gaze and ipsilateral tilt isolates the right SO. Brown is restrictive (worse up-and-in), Duane is horizontal, CN VI is abduction loss. Classic neuro-BV pearl."}'),
  ('21f404db-3t','{"options": ["Intermittent hypertropia", "Constant hypertropia", "Latent hypertropia", "Alternating hypertropia"], "correct": 0, "explanation": "Intermittent UPWARD deviation worse with fatigue = INTERMITTENT HYPERTROPIA (vertical analog of intermittent exo). Constant is always present; latent only under cover; alternating switches eyes. Pearl: ''intermittent + tired'' = control-dependent deviation."}'),
  ('c18c389c-45','{"options": ["Sensory exotropia", "Accommodative exotropia", "Infantile exotropia", "Intermittent exotropia"], "correct": 0, "explanation": "Constant outward turn in an eye with POOR vision from amblyopia = SENSORY EXOTROPIA — loss of vision/fusion lets the eye drift (out more often than in, in older children/adults). Accommodative/infantile/intermittent exo all imply functioning vision. Rule: monocular vision loss → sensory strabismus."}'),
  ('522544a6-53','{"options": ["Left eye esotropia", "Left eye exotropia", "Right eye esotropia", "Right eye exotropia"], "correct": 0, "explanation": "Cover-uncover: covering the RIGHT eye makes the LEFT eye move OUTWARD to pick up fixation → the left eye was turned IN (esotropic) and had to swing out to fixate = LEFT ESOTROPIA. The direction the uncovered/just-fixating eye moves reveals the deviation: moves out → was eso. Cover-test rule: refixation movement OUT = eso, IN = exo."}'),
  ('770a22bd-42','{"options": ["20 prism diopters of exotropia", "20 prism diopters of esotropia", "20 prism diopters of hypertropia", "20 prism diopters of hypotropia"], "correct": 1, "explanation": "PACT neutralizing with 20Δ BASE-OUT prism means base-out was needed to straighten an inward turn → 20Δ of ESOTROPIA. Base-out neutralizes eso (the prism shifts the image outward to meet the in-turned eye); base-in neutralizes exo. Quick rule: base-OUT = esO; base-IN = exo."}'),
  ('cc80f7d6-3m','{"options": ["15 degrees of esotropia", "15 degrees of exotropia", "30 degrees of esotropia", "30 degrees of exotropia"], "correct": 0, "explanation": "The corneal reflex shifts OPPOSITE to the way the eye turns, because the reflex is a mirror image off the cornea rather than a marker on it. An eye rotated nasally (esotropia) throws its reflex TEMPORALLY. So a reflex displaced temporally by 1 mm in the right eye means ESOtropia. Magnitude: Hirschberg runs at about 15 degrees (roughly 7 prism dioptres) per millimetre of decentration, so 1 mm = 15 degrees. Answer: 15 degrees of esotropia. Cross-check against the landmarks: reflex at the pupil margin is about 15 degrees, mid-iris about 30, limbus about 45. The old key said exotropia. Get the direction by picturing the mirror: the eye turns in, the reflection slides out."}'),
  ('fce73ae9-31','{"options": ["Normal binocular vision", "Suppression of one eye", "Double vision (diplopia)", "Fusion with suppression"], "correct": 2, "explanation": "Worth 4-dot showing FIVE dots total (3 green + 2 red) = the patient sees both eyes'' images unfused = DIPLOPIA. Seeing only 2 (red) or 3 (green) = suppression of one eye; seeing 4 = fusion. Count rule: 4 = fusion, 2 or 3 = suppression, 5 = diplopia (crossed in exo, uncrossed in eso)."}'),
  ('4e77b40a-37','{"options": ["Suppression in one eye", "Normal binocular vision", "Esotropia", "Exotropia"], "correct": 0, "explanation": "Bagolini striated glasses showing one COMPLETE and one BROKEN line (a gap where the other line crosses) = SUPPRESSION scotoma in one eye (the gap is the suppressed area around the fovea). Two complete crossing lines = normal/ARC fusion; the gap localizes a central suppression. Bagolini tests under near-natural conditions, so it detects subtle suppression."}'),
  ('671cf330-4o','{"options": ["Good fusion range", "Limited fusion range", "Normal stereopsis", "No fusion ability"], "correct": 0, "explanation": "A fusion range of 30Δ base-in to 20Δ base-out (a wide total amplitude) = GOOD fusional (vergence) range on the synoptophore — large reserves mean comfortable single binocular vision. Limited range would be a few prism diopters; this measures motor fusion, not stereopsis. Cross-link: Sheard''s/Percival''s criteria judge whether reserves compensate a phoria."}'),
  ('2177b1b4-2y','{"options": ["Paralytic strabismus", "Mechanical restriction", "Functional strabismus", "Latent strabismus"], "correct": 1, "explanation": "A FORCED DUCTION test with RESISTANCE to passive movement indicates a MECHANICAL RESTRICTION (e.g., tight/entrapped muscle, Brown syndrome, thyroid eye disease) rather than a neurogenic palsy. Free passive movement with poor active movement = paralytic. Rule: forced duction POSITIVE (restricted) = mechanical; NEGATIVE (free) = paralytic."}'),
  ('8e2f06c6-3k','{"options": ["Esotropia", "Exotropia", "Hypertropia", "Hypotropia"], "correct": 2, "explanation": "Lancaster red-green showing the two targets VERTICALLY misaligned = a VERTICAL deviation = HYPERtropia (named by the higher eye). Horizontal misalignment would be eso/exo. Lancaster maps the deviation in all gaze positions to localize the underacting muscle."}'),
  ('528e4472-3d','{"options": ["Esophoria", "Exophoria", "Hyperphoria", "Hypophoria"], "correct": 1, "explanation": "Maddox rod: a VERTICAL red streak seen to the RIGHT of the white light (streak before the right eye, appearing on the same/right side) = crossed image relationship of EXOPHORIA. Exophoria = crossed → the streak falls on the opposite side to the deviating-out eye''s expectation; the classic teaching pairs ''streak to the right of the light, rod over right eye'' with exophoria. Cross-link: esophoria (Q17) gives the uncrossed pattern."}'),
  ('a1b9aab2-1n','{"options": ["Refractive error", "Muscle paralysis", "Retinal detachment", "Optic nerve pathology"], "correct": 3, "explanation": "An MRI in strabismus is ordered to rule out OPTIC NERVE / central pathology (tumor, demyelination, compressive lesion) when a deviation is paralytic, acquired, or has neuro signs. Refractive error, muscle paralysis localization, and retinal detachment are assessed clinically/with other tools. Red flags (new palsy, papilledema, headache) drive neuroimaging."}'),
  ('d7d76187-30','{"options": ["Elimination of the esotropia at near and distance", "Reduction in refractive error", "Improvement in visual acuity without affecting alignment", "Increase in esotropia"], "correct": 0, "explanation": "Full plus correction in accommodative esotropia removes the accommodative drive, so the expected outcome is ELIMINATION of the esotropia at BOTH near and distance (in pure refractive accommodative eso). It works by cutting accommodation-driven convergence, not by changing acuity directly. If a high AC/A leaves residual near eso, add a bifocal (Q58)."}'),
  ('cca0ca06-37','{"options": ["To correct refractive errors", "To align the visual fields and alleviate double vision", "To enhance peripheral vision", "To improve visual acuity"], "correct": 1, "explanation": "Prism glasses in constant esotropia with diplopia are prescribed to RE-ALIGN the images on corresponding points and RELIEVE the double vision (a sensory comfort measure), not to change refraction or acuity. Prisms shift the image to the deviated fovea. Pearl: prism = symptomatic diplopia relief, not a cure of the deviation."}'),
  ('42cc22d5-2m','{"options": ["Complete resolution of the exotropia", "Improved control of eye alignment and reduction in symptoms", "Increased frequency of exotropia", "Development of esotropia"], "correct": 1, "explanation": "Vision therapy for INTERMITTENT exotropia aims to IMPROVE CONTROL of alignment and reduce symptoms (build fusional convergence and awareness), not to ''cure'' the exo outright. Realistic goal = better control/longer fusion, fewer breaks. Cross-link: orthoptic vergence training (Q61/Q73)."}'),
  ('e2b0f360-3f','{"options": ["To align the eyes", "To strengthen the weaker eye and improve visual acuity", "To correct refractive error", "To reduce intraocular pressure"], "correct": 1, "explanation": "Occlusion (patching) therapy for strabismic amblyopia STRENGTHENS the weaker (amblyopic) eye to improve its visual ACUITY by forcing its use — it does NOT straighten the eyes (that''s surgery/prism). Treat amblyopia first (or alongside) to give surgery a binocular chance. Critical-period dependent."}'),
  ('40c0cb08-3k','{"options": ["Permanent correction of strabismus", "Temporary relief of diplopia", "Improvement in muscle function", "Reduction in refractive error"], "correct": 1, "explanation": "Prism for paralytic strabismus (cranial nerve palsy) gives TEMPORARY relief of DIPLOPIA while the palsy is observed for spontaneous recovery (often up to ~6 months); it does not restore muscle function or permanently fix the deviation. If diplopia persists, consider surgery (Q60). Management ladder: observe + prism → surgery."}'),
  ('93440a7a-36','{"options": ["To improve visual acuity", "To correct refractive error", "To align the eyes for better binocular vision and appearance", "To treat underlying neurological conditions"], "correct": 2, "explanation": "Strabismus surgery in infantile esotropia primarily ALIGNS the eyes to give the best chance at peripheral binocular vision and a normal appearance — done early (before ~2 yr) to harness residual binocular potential. It doesn''t correct refraction or improve acuity per se (amblyopia is treated separately). Goal = alignment for binocularity + cosmesis."}'),
  ('748f34b5-4p','{"options": ["Occlusion therapy", "Vision therapy", "Prismatic correction", "Botulinum toxin injections"], "correct": 2, "explanation": "Sensory exotropia with poor visual potential (not a surgical candidate for binocular gain): PRISMATIC correction can relieve symptomatic diplopia/positioning; botulinum and surgery target alignment but binocular benefit is limited when the eye can''t see. Among the options, prism is the conservative management for symptom relief. Pearl: poor-vision eye → manage symptoms, not fusion."}'),
  ('684d7158-3p','{"options": ["Strabismus surgery", "Increased lens power", "Bifocals or multifocal lenses", "Occlusion therapy"], "correct": 2, "explanation": "Accommodative esotropia not fully controlled by single-vision plus alone (a HIGH AC/A leaving residual NEAR eso) is managed with BIFOCALS / multifocal plus add at near — extra plus relaxes accommodative convergence for near. More minus would worsen it; surgery/occlusion address other issues. Pearl: high AC/A residual near eso → bifocal add (often +2.50/+3.00)."}'),
  ('ecf0c654-2w','{"options": ["Continue observation", "Initiate vision therapy", "Prescribe stronger glasses", "Recommend strabismus surgery"], "correct": 1, "explanation": "Worsening intermittent exotropia (more frequent/larger breaks) → step UP active treatment with VISION THERAPY (build fusional convergence and control) before considering surgery; observation is for stable, well-controlled cases and stronger glasses won''t help an exo. Management ladder: observe → VT → surgery (if poor control/large angle)."}'),
  ('c4d5f718-4b','{"options": ["Recession and resection surgery", "LASIK", "Photorefractive keratectomy (PRK)", "Cataract extraction"], "correct": 0, "explanation": "Persistent diplopia from a sixth-nerve palsy after conservative care is addressed surgically by RECESSION-RESECTION (weaken the antagonist medial rectus, strengthen/transpose to aid abduction). LASIK/PRK/cataract surgery are refractive/lens procedures, irrelevant to muscle realignment. Surgery is delayed until the palsy is stable (~6 months)."}'),
  ('23d2d0dd-37','{"options": ["Brock string with accommodative targets", "Monocular fixation in binocular field (MFBF)", "Stereograms with changing base-in and base-out prism", "Dynamic retinoscopy"], "correct": 2, "explanation": "Advanced convergence-insufficiency therapy uses STEREOGRAMS with progressively changing BASE-IN/BASE-OUT demand to expand fusional vergence ranges (jump and smooth vergences). Brock string and MFBF are earlier/anti-suppression tools; dynamic retinoscopy is a measurement, not therapy. Goal: widen positive fusional vergence."}'),
  ('8942871a-2x','{"options": ["Binocular accommodative rock", "Vertical saccades training", "Horizontal vergence training with vectograms", "Near-far fixation jumps"], "correct": 2, "explanation": "Intermittent EXOtropia is treated orthoptically by HORIZONTAL VERGENCE training with VECTOGRAMS (variable base-in/out targets) to build fusional convergence and control. Accommodative rock targets focusing; saccade/fixation drills target eye movements, not vergence. Match the therapy to the deficit: exo control = convergence/vergence work."}'),
  ('b7026383-2o','{"options": ["Marsden ball with directional sequences", "Loose prism jumps", "Saccadic eye movement trainer", "Hart chart with randomized letters"], "correct": 0, "explanation": "The MARSDEN BALL (swinging ball with directional call-outs) trains OCULOMOTOR pursuit, timing, and spatial awareness/eye-hand integration. Loose prisms train vergence; saccadic trainers train fixation jumps; Hart charts train accommodative/saccadic skill. Marsden ball = dynamic pursuit + spatial/motor integration."}'),
  ('e95ed4c6-2a','{"options": ["To balance monocular visual acuity", "To improve stereopsis and binocularity", "To reduce myopic progression", "To enhance contrast sensitivity"], "correct": 1, "explanation": "Binocular PERCEPTUAL LEARNING (dichoptic) techniques aim to improve STEREOPSIS and BINOCULARITY by training the two eyes to work together (reducing suppression, rebuilding fusion) — the modern push beyond patching for amblyopia. Not for monocular acuity balance per se or myopia control. Cross-link: dichoptic anti-suppression (Q65)."}'),
  ('d04cb7f3-2n','{"options": ["Dichoptic training", "Monocular occlusion", "Patch therapy", "Plus lens accommodative flippers"], "correct": 0, "explanation": "ANAGLYPHIC (red-green) filters that present different images to each eye = DICHOPTIC training for ANTI-SUPPRESSION — each eye sees its own targets so the suppressing eye is forced to participate. Monocular occlusion/patching is the opposite (covers one eye); accommodative flippers train focusing. Anaglyph = colored-filter dichoptic."}'),
  ('78bc0be2-2x','{"options": ["Multi-directional tracking with visual- motor integration", "Near point of convergence (NPC) testing", "Vertical prism adaptation", "Dynamic visual acuity exercises"], "correct": 0, "explanation": "Multi-directional tracking combined with VISUAL-MOTOR INTEGRATION trains fine motor control and HAND-EYE coordination (linking visual input to motor output). NPC testing and prism adaptation are measurements/sensory tasks; dynamic VA is a test. Match: ''hand-eye + fine motor'' = visual-motor integration drills."}'),
  ('2763867e-24','{"options": ["To monitor intraocular pressure", "To enhance compliance and provide regular practice", "To replace all in-office vision therapy", "To diagnose visual disorders remotely"], "correct": 1, "explanation": "Computerized HOME-BASED vision therapy programs chiefly boost COMPLIANCE and give frequent, structured practice between office visits — they SUPPLEMENT, not replace, in-office VT (and don''t measure IOP or diagnose remotely). Adherence is the main barrier in VT, so home programs target it."}'),
  ('9582a1b3-3j','{"options": ["Optometric vision therapy with perceptual-cognitive tasks", "Basic saccadic exercises", "Static accommodative training", "Pharmacological interventions"], "correct": 0, "explanation": "For children with learning-related visual deficits, OPTOMETRIC VT with PERCEPTUAL-COGNITIVE tasks (visual memory, discrimination, figure-ground, visualization) targets visual information processing, beyond simple eye-movement drills. Basic saccades/static accommodation are narrow; pharmacology isn''t a VT tool. VIP skills = higher-order visual cognition."}'),
  ('e122b220-2o','{"options": ["To enhance depth perception", "To improve accommodative facility and flexibility", "To correct refractive errors", "To test color vision"], "correct": 1, "explanation": "ACCOMMODATIVE ROCK with alternating lens powers (e.g., ± flippers) builds accommodative FACILITY and FLEXIBILITY (speed of focus change), not depth perception or refractive correction. It trains how quickly/accurately the patient clears targets through changing plus/minus. Pairs with vergence facility work."}'),
  ('d792f5b7-2q','{"options": ["Improved letter recognition", "Enhanced reading speed and accuracy", "Better color differentiation", "Reduced near point stress"], "correct": 1, "explanation": "Successful SACCADIC training in reading-difficulty children improves READING SPEED and ACCURACY by making fixations and inter-word jumps more efficient (fewer regressions). It targets eye-movement efficiency, not letter recognition, color, or near-point stress directly. Saccades = the reading ''tracking'' substrate."}'),
  ('8113284a-2v','{"options": ["Vision therapy with synoptophore", "Patching therapy alone", "Color vision exercises", "Visual field training"], "correct": 0, "explanation": "For a YOUNG CHILD with esotropia needing active binocular rehab, VISION THERAPY with the SYNOPTOPHORE (controlled dichoptic targets to build fusion/correspondence) is the advanced orthoptic option; patching alone treats amblyopia not fusion, and color/field drills are off-target. Synoptophore = the classic instrument for fusion/anti-suppression in strabismus."}'),
  ('fecbb9a6-3q','{"options": ["Accommodative flippers with high accommodative demand", "Prism adaptation therapy", "Detailed stereopsis training with random dot stereograms", "Visual perceptual integration tasks"], "correct": 2, "explanation": "Early intervention for NON-strabismic binocular vision disorders emphasizes STEREOPSIS training with RANDOM-DOT stereograms (build global stereopsis/fusion) along with vergence work. High-demand accommodative flippers and prism adaptation are narrower; random-dot training directly grows binocular depth. Cross-link: random-dot stereo is also a sensitive stereo test (TNO)."}'),
  ('260c1986-29','{"options": ["Base-in and base-out prism jumps", "Basic accommodative rock with plus lenses", "Red-green luster exercise", "Peripheral awareness training"], "correct": 0, "explanation": "Poor VERGENCE FACILITY (slow base-in/out shifting) is best trained with BASE-IN and BASE-OUT PRISM JUMPS (prism flippers/vergence facility), which drill rapid convergence/divergence changes. Accommodative rock targets focusing facility; luster/peripheral drills are anti-suppression/awareness. Match deficit to tool: vergence facility = prism jumps."}'),
  ('30dbbdf3-2z','{"options": ["Visual-motor integration training", "Simple saccadic exercises", "Contrast sensitivity improvement", "Night vision enhancement"], "correct": 0, "explanation": "Visual-SPATIAL ORIENTATION problems are addressed with VISUAL-MOTOR INTEGRATION training (linking spatial perception to coordinated movement/laterality-directionality). Simple saccades, contrast, and night-vision drills don''t build spatial mapping. VMI = the spatial/motor bridge."}'),
  ('febb33ca-36','{"options": ["Marsden ball exercises", "Static accommodation exercises", "Color vision discrimination training", "Night vision exercises"], "correct": 0, "explanation": "EYE-HAND COORDINATION difficulty is trained with MARSDEN BALL exercises (dynamic pursuit + timed motor responses), the same tool from Q63/Q66 for coordination/timing. Static accommodation, color discrimination, and night-vision drills don''t build eye-hand timing. Reinforced: Marsden ball = pursuit + coordination."}'),
  ('3737f6c3-3u','{"options": ["Optic Disc", "Retina", "Optic Nerve", "LGB"], "correct": 1, "explanation": "The RETINA is the thin transparent neural membrane where photoreceptors transduce light into nerve impulses relayed onward — phototransduction happens here, not at the optic disc (axons only), optic nerve (conduit), or LGB (relay). Layered structure: photoreceptors (outer) → bipolar → ganglion (inner). Cross-link: the LGB (Q91) is the next relay."}'),
  ('a04522ba-2t','{"options": ["Homonymous", "Heteronymous", "Congruous", "Incongruous"], "correct": 0, "explanation": "Bilateral field loss where BOTH defects are on the SAME side (both left) = HOMONYMOUS — caused by a retrochiasmal lesion (tract, LGB, radiations, cortex) opposite the field loss. Heteronymous = opposite sides (bitemporal/binasal, chiasmal). ''Homo'' = same side. Cross-link: right-sided lesion → left homonymous loss (Q97)."}'),
  ('86843d33-6o','{"options": ["Presence of RAPD at OD", "Presence of TAPD at OD", "Presence of TAPD at OS", "Presence of RAPD at OS"], "correct": 3, "explanation": "OD constricts, holds briefly, then shows FAST RE-DILATION when the light swings to OS = RAPD on the OTHER eye (OS) — the classic Marcus Gunn sign: the afferent input from OS is weaker, so swinging to OS lets OD escape (re-dilate). Localizes the relative AFFERENT defect to OS. Pearl: the eye that causes re-dilation when illuminated has the RAPD."}'),
  ('b7de4115-3u','{"options": ["Convergence reflex test", "Accommodation and convergence", "Accommodation pupillary response", "Positive vertical convergence"], "correct": 2, "explanation": "The test of pupil SIZE change under NORMAL illumination while shifting fixation from distance to NEAR = the ACCOMMODATIVE (near) PUPILLARY RESPONSE — part of the near triad (accommodation, convergence, miosis). It isolates the miotic component of the near reflex. Cross-link: Argyll Robertson pupils show light-near dissociation (near response intact, light lost)."}'),
  ('86ab5bc2-7q','{"options": ["Argyll Robertson pupil", "Hutchinson’s pupil", "Adies Pupil", "Horner’s syndrome pupil"], "correct": 2, "explanation": "Unequal pupils worse in DIM light, with one pupil POORLY reactive to light but constricting to ACCOMMODATION (light-near dissociation, slow tonic re-dilation) = ADIE''S (tonic) pupil — from ciliary ganglion/post-ganglionic parasympathetic damage; often with diminished DTRs (Holmes-Adie). Argyll Robertson is BILATERAL small pupils, light-near dissociation (neurosyphilis); Horner''s is a small pupil with ptosis; Hutchinson''s is a blown pupil (CN III compression). Pearl: Adie = tonic, light-near dissociation, young women, sluggish re-dilation."}'),
  ('65286f32-57','{"options": ["Only refraction constitutes optometric practice.", "Only dispensing ophthalmic lenses constitutes optometric practice.", "All activities are recognized as acts constituting the practice of optometry.", "Vision therapy is reserved exclusively for ophthalmologists."], "correct": 2, "explanation": "All of them, refraction, prescribing, dispensing, and vision therapy are all acts constituting the practice of optometry under RA 8050 Sec 4. Hint: RA 8050 defines practice broadly; if it is eye/vision care by an OD, it counts."}'),
  ('f41057f6-4r','{"options": ["Cycloplegic refraction", "Contact lens fitting", "Visual acuity testing and vision screening only", "Prescribing eyeglasses"], "correct": 2, "explanation": "Only visual acuity testing and vision screening, a trained lay screener may screen, but refraction, CL fitting, and prescribing are optometric acts. Hint: lay screeners screen; only licensed ODs refract/prescribe/fit."}'),
  ('c7f73423-3d','{"options": ["Illegal practice of optometry", "Allowed because it is incidental to a medical examination", "Allowed only with PRC authorization", "Allowed only if supervised by an optometrist"], "correct": 1, "explanation": "Allowed, it is incidental to a physician''s medical examination (physicians are exempt for eye care within their practice). Hint: doctors examining eyes as part of medical care are exempt from the Optometry Law."}'),
  ('30b1f42e-40','{"options": ["Scope of practice", "Disclosure of authority to practice", "Professional integration", "Code of Ethics"], "correct": 1, "explanation": "Disclosure of authority to practice, the prescription must show the license/registration number (proof of authority). Hint: no license number on the Rx = failure to disclose authority to practice."}'),
  ('bc3c0ccc-23','{"options": ["Registered optometrist, 36 years old, practicing for 12 years", "Registered optometrist who serves as president of a national optometric association", "Registered optometrist with good moral character", "Natural-born Filipino practicing for 15 years"], "correct": 1, "explanation": "An officer (president) of a national optometric association is disqualified (conflict of interest), a Board member must not be an officer of any optometric organization. Hint: Board members cannot simultaneously be officers of an optometric association."}'),
  ('a5bf5299-2s','{"options": ["Yes", "Only with PRC approval", "No, because the term is non-renewable", "Only after two years"], "correct": 0, "explanation": "Yes, a member may be reappointed (up to the allowed second term). Some readings cap total service, so VERIFY the exact term/reappointment limit your key uses. Hint: RA 8050 members serve a 3-year term and may be reappointed for one more term (2 terms max)."}'),
  ('beac778b-3j','{"options": ["Issuing professional licenses", "Preparing examination contents considering recent developments", "Investigating malpractice", "Maintaining the registry"], "correct": 1, "explanation": "Preparing examination content considering recent developments, the Board''s power to keep the exam current. Hint: updating exam topics = the Board''s power over examination content."}'),
  ('0ce1fe62-3s','{"options": ["No", "Yes, because three members constitute a quorum", "Only if the Chairperson is present", "Only with PRC approval"], "correct": 1, "explanation": "Yes, business may proceed with the members present constituting a quorum. Hint: enough members present = quorum = official business can go on."}'),
  ('eb37ef6d-31','{"options": ["Pass the examination", "Retake only the failed subject", "Fail because no rating should be below 50%", "Receive conditional registration"], "correct": 2, "explanation": "Fail, passing requires a general average of at least 75% AND no rating below 50%. A 48% in one subject fails it. Hint: two hurdles, 75% GA and nothing below 50%; a sub-50 grade fails you outright."}'),
  ('7eab24fc-3p','{"options": ["Wait five years", "Complete residency training", "Finish a refresher course in an accredited institution", "Obtain Board approval"], "correct": 2, "explanation": "Complete a refresher course in an accredited institution before retaking after three consecutive failures. Hint: 3 strikes = mandatory refresher course before the next attempt."}'),
  ('de8afb5d-3a','{"options": ["Citizenship", "Moral character", "Educational qualification", "Age requirement"], "correct": 2, "explanation": "Educational qualification, a graduate of an unrecognized school has not met the required education standard. Hint: unrecognized school = the education requirement is not satisfied."}'),
  ('ade7e56e-33','{"options": ["Yes", "Only temporarily", "No", "Only upon Board recommendation"], "correct": 2, "explanation": "No, the Certificate of Registration is issued only after the professional oath is taken. Hint: no oath, no certificate; the oath is a precondition."}'),
  ('f7667b50-2p','{"options": ["Automatically renew the license", "Suspend or revoke the certificate after due process", "Issue a warning only", "Require community service"], "correct": 1, "explanation": "Suspend or revoke the certificate after due process (conviction of a crime involving moral turpitude is a ground). Hint: moral-turpitude conviction = grounds to suspend/revoke, but due process first."}'),
  ('43c521ea-3f','{"options": ["Practice is allowed.", "Practice depends on employer approval.", "Practice is prohibited until reinstatement.", "Practice is allowed with supervision."], "correct": 2, "explanation": "Practice is prohibited until reinstatement, a suspended optometrist may not practice while awaiting reconsideration. Hint: suspended means stop; you cannot practice pending appeal."}'),
  ('6cdb6be2-1o','{"options": ["Year", "Two years", "Three years", "Five years"], "correct": 2, "explanation": "Every three years (the Professional Identification Card renewal cycle). Hint: PRC ID / license renews on a 3-year cycle."}'),
  ('53619b43-3d','{"options": ["None", "Attend a pharmacology course and pass certification", "Residency in ophthalmology", "DOH permit only"], "correct": 1, "explanation": "Attend a pharmacology course and pass a certification examination to be DPA-authorized. Hint: pre-RA 8050 grads earn DPA authority via a pharmacology course + certification exam."}'),
  ('45aabb12-26','{"options": ["Atropine 1%", "Tropicamide 0.5%", "Pilocarpine 2%", "Timolol 0.5%"], "correct": 1, "explanation": "Tropicamide 0.5% is a DIAGNOSTIC agent authorized under RA 8050. Atropine, pilocarpine, and timolol are therapeutic, not diagnostic. Hint: DPAs are diagnostic (dilate/anesthetize/stain), tropicamide fits; the others treat disease."}'),
  ('9500a367-3z','{"options": ["False advertisement", "Unauthorized use of pharmaceutical agents", "Illegal practice", "Moral turpitude"], "correct": 1, "explanation": "Unauthorized use of pharmaceutical agents, giving a drug outside the authorized list/authority. Hint: using a non-listed or unauthorized drug = unauthorized use of pharmaceutical agents."}'),
  ('fd6dcd26-33','{"options": ["Allowed", "Encouraged", "Prohibited", "Allowed only on social media"], "correct": 2, "explanation": "Prohibited, price-based (''cheapest'') advertising is not allowed under the professional rules. Hint: cost/price-competition ads are barred for the profession."}'),
  ('8b83a72d-35','{"options": ["Malpractice", "Illegal advertisement", "Unauthorized assumption of professional title", "Professional misconduct"], "correct": 2, "explanation": "Unauthorized assumption of professional title, using ''Registered Optometrist'' without a license. Hint: claiming the title without the license = unauthorized assumption of the professional title."}'),
  ('0a8abbb6-1q','{"options": ["Suspension only", "Fine only", "Imprisonment, fine, or both", "Community service only"], "correct": 2, "explanation": "Imprisonment, fine, or both may be imposed for prohibited acts under RA 8050. Hint: RA 8050 penalties = fine and/or imprisonment."}'),
  ('c3cb6830-3b','{"options": ["Residency", "Reciprocity", "Citizenship only", "ASEAN membership"], "correct": 1, "explanation": "Reciprocity, a foreigner may sit the exam only if their country extends the same privilege to Filipinos. Hint: foreign eligibility hinges on reciprocity."}'),
  ('8ea7006b-4q','{"options": ["Temporary registration", "Special permit approved by the Board and PRC", "Visitor''s visa", "CHED accreditation"], "correct": 1, "explanation": "A special/temporary permit approved by the Board and PRC lets an invited foreign expert practice despite no reciprocity. Hint: no reciprocity but invited expert = special permit from Board + PRC."}'),
  ('2ba5af2b-3p','{"options": ["Membership is discouraged.", "Membership is encouraged through professional integration.", "Membership is prohibited during the first year.", "Membership is optional only after retirement."], "correct": 1, "explanation": "Encouraged through professional integration (membership in the accredited national organization). Hint: RA 8050 promotes professional integration, so joining is encouraged."}'),
  ('27d7755c-42','{"options": ["Professional independence", "Duty to refer when indicated", "Continuing education", "Confidentiality"], "correct": 1, "explanation": "Duty to refer when indicated, failing to refer a recognized retinal detachment breaches this duty. Hint: recognizing a serious condition and not referring = breach of the duty to refer."}'),
  ('62301ac1-2p','{"options": ["Increasing clinic revenue", "Maintaining professional popularity", "Protecting the visual welfare of the public", "Selling premium lenses"], "correct": 2, "explanation": "Protecting the visual welfare of the public is the optometrist''s primary responsibility. Hint: public visual welfare comes before revenue or popularity."}'),
  ('4d7b5058-4k','{"options": ["Disclose all information", "Maintain confidentiality", "Post findings on social media", "Release information upon verbal request"], "correct": 1, "explanation": "Maintain confidentiality, do not disclose patient information without consent. Hint: no consent, no disclosure."}'),
  ('deabbba5-3s','{"options": ["PRC", "Technical Panel on Optometric Education", "Department of Health", "Integrated National Organization alone"], "correct": 1, "explanation": "The Technical Panel on Optometric Education assists CHED with faculty/curriculum standards. Hint: CHED''s optometry curriculum helper = the Technical Panel on Optometric Education."}'),
  ('322991be-47','{"options": ["Counseling only", "Establishment of offices or clinics where optometric services are offered", "Dispensing only", "Vision screening only"], "correct": 1, "explanation": "Establishment of offices or clinics where optometric services are offered (an act of practice under Sec 4). Hint: opening a clinic to provide eye exams is itself a recognized act of practice."}'),
  ('30d25cd7-3k','{"options": ["Two members", "Three members", "Four members", "Unanimous vote"], "correct": 0, "explanation": "A majority (two members of the three-member Board) is the minimum vote for a valid decision. Hint: 3-member Board -> majority = 2 votes to decide."}'),
  ('de7c9df6-56','{"options": ["Allowed if services are free", "Allowed during disasters only", "Not allowed unless conducted with proper authorization", "Allowed if supervised by an ophthalmologist"], "correct": 2, "explanation": "Not allowed unless conducted with proper authorization/coordination (with public-health officials and the accredited organization). Hint: outreach screenings need proper coordination/authorization, not a solo mobile clinic."}'),
  ('f7772bd2-2i','{"options": ["Register only with the local government", "Notify the Board of the clinic location within 30 days", "Submit monthly clinic reports", "Obtain permission from the integrated association before opening"], "correct": 1, "explanation": "Notify the Board of the clinic location within 30 days (an IRR requirement). Hint: new clinic = tell the Board where, within 30 days."}'),
  ('5aab6128-2t','{"options": ["Corneal topographer", "OCT", "Tonometer and visual field testing equipment", "Fundus camera"], "correct": 2, "explanation": "A tonometer and visual-field testing equipment are additionally required for a DPA-certified clinic. Hint: DPA practice = add tonometry + visual fields to the kit."}'),
  ('95df46e0-2p','{"options": ["The clinic fully complies with the IRR.", "A keratometer or equivalent is required.", "Only a slit lamp is required.", "A keratometer is optional."], "correct": 1, "explanation": "A keratometer (or equivalent) is required for contact-lens practice. Hint: fitting contact lenses requires a keratometer/topographer."}'),
  ('9a739abf-36','{"options": ["Professional Conduct", "Display of Certificate of Registration", "Continuing Professional Education", "Professional Integration"], "correct": 1, "explanation": "Display of Certificate of Registration, the PRC certificate must be posted. Hint: the PRC COR must be on display, diplomas do not substitute."}'),
  ('b64fd87c-32','{"options": ["Ethical if true", "Allowed with PRC approval", "Self-laudatory and prohibited", "Allowed only online"], "correct": 2, "explanation": "Self-laudatory and prohibited (''No. 1'', ''Best'') claims are barred. Hint: superlative self-praise (''best'', ''No. 1'') = self-laudatory, prohibited."}'),
  ('dc1d7eb2-1l','{"options": ["Clinic address and office hours", "Available eye care services", "\"Free eye examination with every purchase.\"", "Professional qualifications"], "correct": 2, "explanation": "''Free eye examination with every purchase'' is specifically prohibited (tying the exam to a sale). Hint: bundling a ''free exam'' with a purchase is a prohibited inducement."}'),
  ('f9a8cc93-3d','{"options": ["Community outreach", "Canvassing and prohibited solicitation", "Public education", "Ethical marketing"], "correct": 1, "explanation": "Canvassing and prohibited solicitation, using promoters to round up customers is barred. Hint: paid promoters herding customers = prohibited solicitation/canvassing."}'),
  ('476e1dc4-4e','{"options": ["Prohibited", "Allowed because the patient is non-ambulant", "Allowed only with LGU approval", "Allowed only for children"], "correct": 1, "explanation": "Allowed because the patient is non-ambulant (home service for a bedridden patient is permitted). Hint: a genuinely bedridden/non-ambulant patient may be seen at home."}'),
  ('fcf65ff5-3p','{"options": ["Always prohibited", "Permitted under specified circumstances", "Illegal unless the employer is an ophthalmologist", "Limited only to hospitals"], "correct": 1, "explanation": "Permitted under specified circumstances, an in-house OD serving only company employees is allowed within the rules. Hint: employer-employed ODs for company staff are allowed under defined conditions."}'),
  ('36f4bfb0-3p','{"options": ["Passed", "Failed", "Conditioned and must retake only the failed subject", "Required to repeat the entire examination"], "correct": 1, "explanation": "Failed, a 48% in a theoretical subject violates the ''no grade below 50%'' rule regardless of the average. Hint: any sub-50 grade fails the whole exam."}'),
  ('c666edab-44','{"options": ["Pass", "Retake only the failed practical area", "Retake the entire examination", "Receive conditional registration"], "correct": 2, "explanation": "Retake the entire examination, a General Weighted Average of 72% is below the 75% passing mark. (If the practical is scored/removed separately in the key, the remedy may differ, VERIFY.) Hint: GWA under 75 = fail overall; the usual remedy is retaking everything."}'),
  ('cec15b63-3r','{"options": ["Residency training", "Pharmacology course and certification examination", "Fellowship training", "PRC interview"], "correct": 1, "explanation": "A pharmacology course and certification examination (for pre-RA 8050 admittees seeking DPA authority). Hint: same as Q16, DPA authority via pharmacology course + certification exam."}'),
  ('a793bc43-2m','{"options": ["Retinoscope", "Ophthalmic chair", "OCT", "Slit-lamp biomicroscope"], "correct": 2, "explanation": "OCT is NOT a required basic clinic instrument (retinoscope, ophthalmic chair, and slit-lamp are). Hint: OCT is advanced, not part of the required basic instrument list."}'),
  ('3e651854-3o','{"options": ["Automatically loses the degree", "Is dropped from the Roll of Optometrists", "Must retake the board examination", "Is permanently disqualified"], "correct": 1, "explanation": "Dropped from the Roll of Optometrists after prolonged (over five years) non-payment of the annual registration fee. Hint: chronic non-payment = removed (dropped) from the roll, not stripped of the degree."}'),
  ('c17c2afb-19','{"options": ["Two years", "Three years", "Five years after the last consultation", "Ten years"], "correct": 2, "explanation": "At least five years after the last consultation for patient records retention. Hint: keep patient records 5 years from the last visit."}'),
  ('ff64ba91-3b','{"options": ["Must complete 60 CPE units", "Permanently exempt from CPE requirements", "Needs only 30 units", "Exempt only with Board approval"], "correct": 1, "explanation": "Permanently exempt from CPE/CPD, a professional 65 years or older at renewal is exempt (a 66-year-old qualifies). Hint: age 65+ at renewal = permanent CPD exemption."}'),
  ('eece6b26-3g','{"options": ["30 CPE units", "45 CPE units", "60 CPE units", "15 CPE units"], "correct": 1, "explanation": "About 45 CPD/CPE units is the general minimum for renewal under current guidelines. Unit counts have shifted over time, so VERIFY the latest figure. Hint: current CPD requirement for renewal is around 45 units (down from the old 100)."}'),
  ('bc59daee-3d','{"options": ["10 days", "15 days", "30 days", "60 days"], "correct": 1, "explanation": "Final after 15 days if not appealed. Hint: 15-day window to appeal a Board decision before it becomes final."}'),
  ('eb9e5c33-3n','{"options": ["Professional advertising", "Unlawful practice", "Practice management", "Product promotion"], "correct": 1, "explanation": "Unlawful practice, prescribing/endorsing a product not registered with FDA (BFAD)/DTI. Hint: pushing an unregistered product = unlawful practice."}'),
  ('2a41afa6-5y','{"options": ["Issue the prescription to satisfy the patient.", "Refuse the request and explain the need for a complete examination.", "Allow the optical staff to determine the prescription.", "Refer the patient immediately to another clinic."], "correct": 1, "explanation": "Refuse and explain the need for a complete examination, patient safety first. Hint: no complete exam, no prescription; explain why."}'),
  ('4aeacc3f-4c','{"options": ["Right to confidentiality", "Right to informed refusal", "Right to free treatment", "Right to demand any procedure"], "correct": 1, "explanation": "Right to informed refusal, a patient may decline a procedure after being informed. Hint: an informed patient may say no, that is informed refusal."}'),
  ('45ad6640-4t','{"options": ["Right to advertise services", "Right to independent professional judgment", "Right to terminate care without reason", "Right to charge unlimited fees"], "correct": 1, "explanation": "Right to independent professional judgment, the OD need not fill a clinically inappropriate demand. Hint: your clinical judgment is yours; you may refuse an unsafe/inappropriate request."}'),
  ('ef52922d-3t','{"options": ["Release the records because the employer requested them.", "Release only the diagnosis.", "Maintain confidentiality unless authorized by the patient or required by law.", "Release the records if the employer paid for the examination."], "correct": 2, "explanation": "Maintain confidentiality unless authorized by the patient or required by law, an employer''s request is not enough. Hint: release records only with patient consent or a legal mandate, never just because an employer asks."}'),
  ('ed5d3c1b-48','{"options": ["Right to choose the examination room", "Right to informed consent", "Right to free consultation", "Right to receive a guarantee of success"], "correct": 1, "explanation": "Right to informed consent, being told risks/benefits before agreeing to treatment. Hint: understanding risks/benefits before consenting = informed consent."}'),
  ('92518926-4h','{"options": ["Continue treatment regardless of the circumstances.", "Immediately abandon the patient without referral.", "Terminate the professional relationship appropriately while ensuring continuity of care.", "Refuse to release the patient''s records."], "correct": 2, "explanation": "Terminate the professional relationship appropriately while ensuring continuity of care (proper notice/referral). Hint: you may ''fire'' an abusive patient, but not abandon, arrange continuity/referral."}'),
  ('a8680d0e-3g','{"options": ["Refuse because prescriptions belong to the clinic.", "Release the prescription as part of the patient''s records.", "Release only if glasses are purchased from the clinic.", "Release only after one year."], "correct": 1, "explanation": "Release the prescription as part of the patient''s records (it is the patient''s, not tied to buying glasses there). Hint: the Rx belongs to the patient; release it, no purchase strings."}'),
  ('74fb6ab5-4n','{"options": ["Continue treatment independently.", "Refer the patient promptly to the appropriate specialist.", "Wait until the next follow-up visit.", "Allow the patient to decide without recommendation."], "correct": 1, "explanation": "Refer the patient promptly to the appropriate specialist (urgent retinal issue beyond scope). Hint: beyond your scope + urgent = refer now."}'),
  ('68b425b9-3k','{"options": ["Right to equal treatment", "Right to confidentiality and privacy", "Right to demand any treatment", "Right to waive professional fees"], "correct": 1, "explanation": "Right to confidentiality and privacy, honor the patient''s wish to keep findings private, even from family. Hint: the patient controls who learns their findings."}'),
  ('bf2e3cbf-4p','{"options": ["Right to independent clinical judgment and ethical practice", "Right to refuse all patients", "Right to charge higher professional fees", "Right to delegate prescribing to clinic staff"], "correct": 0, "explanation": "Right to independent clinical judgment and ethical practice, you may decline to prescribe unnecessary medication. Hint: a normal exam plus an unnecessary drug demand = decline on clinical/ethical grounds."}'),
  ('8475e3cd-4o','{"options": ["A patient requesting clarification regarding the examination findings made by the licensed Optometrist.", "A colleague discussing alternative management options to the patient without the presence of the previous Optometrist who did the eye exam.", "A staff member assisting in appointment scheduling and patient registration.", "A supervisor directing the optometrist to omit certain examination procedures to shorten consultation time."], "correct": 3, "explanation": "A supervisor directing the OD to OMIT examination procedures to save time is improper interference with professional discretion. Hint: pressuring you to skip needed exam steps = interference with your professional judgment."}'),
  ('fe102dc4-36','{"options": ["Automated perimeter", "Corneal Topographer", "Tangent screen", "Goldmann tonometer"], "correct": 1, "explanation": "A corneal topographer (or keratometer) is the CL-related instrument required, it maps the cornea for fitting. VERIFY the exact instrument named in Board Resolution No. 11. Hint: contact-lens fitting needs corneal curvature mapping (keratometer/topographer)."}'),
  ('98589091-2c','{"options": ["Health-related device", "Cosmetic device", "Medical device", "Management device"], "correct": 2, "explanation": "A medical device, the Philippine FDA regulates ALL contact lenses (including plano/cosmetic colored) as medical devices needing a prescription. Hint: even ''cosmetic'' colored lenses are medical devices here, not mere cosmetics."}'),
  ('0591a289-29','{"options": ["Overtime pay", "Hazard pay", "Longevity pay", "Separation pay"], "correct": 3, "explanation": "Separation pay applies to an employee retrenched (authorized-cause termination) after years of service. Hint: retrenchment (an authorized cause) = separation pay."}'),
  ('2ba0d2de-2r','{"options": ["P 900", "P 840", "P 905", "P 755"], "correct": 2, "explanation": "P905, individual community tax = basic P5 + P1 per P1,000 of income. Annual income 900,000 -> 900 additional + 5 basic = P905. Hint: cedula = P5 basic + P1 per P1,000 income (here 900 + 5)."}'),
  ('9bfd7a89-49','{"options": ["Bureau of Internal Revenue (BIR)", "Department of Trade and Industry (DTI)", "Securities and Exchange Commission (SEC)", "National Economic and Development Authority (NEDA"], "correct": 1, "explanation": "Expanding a sole proprietorship to another city means securing a DTI business-name registration for that scope plus a new local business permit. VERIFY: the item options only list agencies, so confirm whether the key wants DTI (re-registration of the business name) or another step."}'),
  ('99e0923b-2b','{"options": ["Excessive capital investment by the employee.", "Responsibility for all liability claims.", "Limitations in scope of practice.", "Lack of office facilities and equipment."], "correct": 2, "explanation": "Limitations in scope of practice is a recognized disadvantage of corporate/employed practice. Hint: employed corporate practice can constrain how you practice (scope)."}'),
  ('c3347517-1i','{"options": ["Separation pay.", "PhilHealth coverage.", "Maternity leave.", "Service incentive leave."], "correct": 1, "explanation": "PhilHealth coverage is mandated under RA 11223 (the Universal Health Care Act). Hint: RA 11223 = Universal Health Care = automatic PhilHealth coverage."}'),
  ('3cb7ed76-3p','{"options": ["20 square meters", "400 square feet", "10 square meters", "800 square feet"], "correct": 2, "explanation": "The examination room minimum area cited in the Board resolution is about 10 square meters (enough for a 6-meter or mirror-folded test lane plus equipment). VERIFY: confirm the exact figure in Optometry Board Resolution No. 11 s. 2016, as values are sometimes quoted differently."}'),
  ('bc5bf8b9-64','{"options": ["The pharmacy may sell contact lenses under its existing drugstore license because contact lenses are consumer products.", "The pharmacy only needs to employ a licensed Optometrist as a consultant since all drug outlets are authorized to dispense ophthalmic devices.", "The pharmacy must obtain a separate FDA LTO as a retailer of medical devices, but no additional professional supervision or valid ophthalmic prescription is necessary since contact lenses are considered over-the-counter products.", "The pharmacy must obtain a separate FDA LTO as a retailer of medical devices, designate a registered optometrist as the Qualified Person, and ensure that contact lenses are dispensed only upon a valid ophthalmic prescription."], "correct": 3, "explanation": "The pharmacy must obtain a separate FDA LTO as a medical-device retailer, designate a registered optometrist as the Qualified Person, and dispense contact lenses only on a valid ophthalmic prescription. Hint: selling CLs = device-retailer LTO + OD Qualified Person + valid prescription."}'),
  ('1faab7ee-3d','{"options": ["Payroll or Income Tax Returns", "Certificate of Good Standing", "Official Receipts", "Special books of accounts"], "correct": 3, "explanation": "The special books of accounts must be registered with the BIR to record transactions. Hint: BIR-registered books of accounts capture the business''s transactions."}'),
  ('df401537-2o','{"options": ["One year", "Two years", "Three years", "Five years"], "correct": 1, "explanation": "The INITIAL FDA License to Operate for a medical-device retailer is valid for two years (renewals run longer). Hint: first LTO = 2 years; renewals = longer."}'),
  ('5de5ffd7-3a','{"options": ["Recommended marketing to increase footfall.", "Acceptable if approved by the accredited professional association.", "Considered as a criminal offense and may be punishable of imprisonment.", "Considered unprofessional and unethical conduct."], "correct": 3, "explanation": "Considered unprofessional and unethical conduct (solicitation via canvassers/entertainers). It is also a prohibited act that can carry penalties, so if the key stresses the penal angle, that is why, VERIFY. Hint: touting through agents/entertainers = unprofessional/unethical (and a punishable prohibited act)."}'),
  ('cf0641e0-29','{"options": ["60 days paid maternity leave", "90 days paid maternity leave", "105 days paid maternity leave", "120 days paid maternity leave"], "correct": 2, "explanation": "105 days of paid maternity leave under the Expanded Maternity Leave Law (RA 11210). Hint: expanded maternity leave = 105 days."}'),
  ('8282204a-2q','{"options": ["Age of the employee, it lowers as the employee age", "Number of dependents, the more dependents the more the contribution", "Length of service and employee’s yearly income tax return", "Applicable contribution rate and the employee''s monthly salary base"], "correct": 3, "explanation": "The applicable contribution rate applied to the employee''s monthly salary base sets the PhilHealth contribution. Hint: PhilHealth = rate x monthly salary base (not age or dependents)."}'),
  ('b07fb2d7-75','{"options": ["Accept the 60-day leave because maternity benefits are subject to company discretion.", "Resign from employment and seek maternity benefits from another employer.", "Request conversion of the remaining leave days into vacation leave credits.", "File a complaint or seek assistance from the Department of Labor and Employment."], "correct": 3, "explanation": "File a complaint or seek assistance from DOLE, 105 days is a statutory right the employer cannot cut to 60. Hint: an employer cannot shrink a legal benefit; escalate to DOLE."}'),
  ('db9199d6-69','{"options": ["CMDN and CPR", "PTR and COGS", "SEC Registration and BIR Certificate of Registration", "Business Permit and Barangay Clearance"], "correct": 0, "explanation": "CMDN and CPR, the Certificate of Medical Device Notification and Certificate of Product Registration prove market authorization. Hint: device market authorization = CMDN/CPR from FDA."}'),
  ('6dfc64f2-5f','{"options": ["The owner is correct. Appointment should have been sent via email beforehand.", "Inspections require at least seven days'' notice according to the policy.", "Inspections may only occur during license renewal and should be done together with the accredited professional association.", "Licensed retailers may be subjected to routine or spot-check inspections during operating hours."], "correct": 3, "explanation": "Licensed retailers may be subject to routine or spot-check inspections during operating hours (no appointment needed). Hint: FDA can inspect licensed outlets anytime during business hours."}'),
  ('1580092c-43','{"options": ["Secure a Mayor''s Permit and Barangay Clearance", "Register with the Bureau of Internal Revenue", "Register the business as retailer under Food and Drug Administration", "Register the business name with the Department of Trade and Industry"], "correct": 3, "explanation": "Register the business NAME with the DTI first (for a sole proprietorship), then proceed to LGU/BIR/FDA. Hint: sequence starts at DTI (name), then permits, BIR, FDA."}'),
  ('e6926fac-1e','{"options": ["It may only be paid after filing the income tax return.", "It is imposed only on individual worker who earn below minimum wage.", "Late payment beyond February is subject to interest.", "Foreign-source income is excluded in all instances."], "correct": 2, "explanation": "CORRECT: late payment of community tax beyond February is subject to interest (it is due by the end of February). Hint: cedula is due by February; pay late and interest accrues."}'),
  ('a817979e-3k','{"options": ["Pag-IBIG Fund", "Social Security System", "Service Incentive Leave", "PhilHealth"], "correct": 3, "explanation": "PhilHealth provides the health-insurance (hospitalization/outpatient) coverage. Hint: government health insurance = PhilHealth."}'),
  ('5f0ba6fd-1p','{"options": ["An optometrist engaged in private practice who independently owns and operates a clinic and regularly renders professional eye care services to patients", "A consultant optometrist who renders professional services in several optical clinics under various contractual arrangements and receives professional fees therefrom", "An optometrist employed by a private corporation or optical chain who receives compensation income as a regular employee and does not maintain an independent clinic", "An optometrist exclusively employed by the government and not authorized to practice outside official functions"], "correct": 3, "explanation": "An optometrist EXCLUSIVELY employed by the government (not practicing outside official functions) is exempt from the professional tax. Hint: government-only practice = professional-tax exempt."}'),
  ('b58b60ab-4t','{"options": ["Ignore the incident because it is an internal clinic matter.", "Confront the colleague privately but take no further action.", "Report the misconduct through the proper professional or legal channels while maintaining professionalism.", "Inform the patients through social media."], "correct": 2, "explanation": "Report the misconduct through the proper professional/legal channels while staying professional (records fraud is serious). Hint: report record-tampering/fraud through official channels, not social media or silence."}'),
  ('41182a6c-3o','{"options": ["Refuse to release the records to protect the clinic.", "Release the records only after obtaining the patient''s proper authorization and following legal procedures.", "Destroy the records after issuing a prescription.", "Release only the financial records."], "correct": 1, "explanation": "Release the records only after the patient''s proper authorization and legal procedure (supporting the second opinion). Hint: release for a second opinion, but with proper patient authorization."}'),
  ('1db99948-55','{"options": ["Maintaining compliance with professional licensure requirements.", "Advertising professional qualifications.", "Promoting the clinic''s services.", "Establishing ownership of the clinic."], "correct": 0, "explanation": "Maintaining compliance with professional licensure requirements (presenting a valid COR and PIC on audit). Hint: showing a current COR/PIC = staying compliant with licensure."}'),
  ('46949c6f-5v','{"options": ["Beneficence", "Justice", "Patient confidentiality and privacy", "Professional competition"], "correct": 2, "explanation": "Patient confidentiality and privacy, a secure records system that limits access to authorized staff. Hint: protect health data, controlled access = confidentiality/privacy."}'),
  ('114846ac-20','{"options": ["Delegating refraction to an unqualified assistant without supervision.", "Issuing prescriptions without examining the patient.", "Maintaining professional competence through continuing professional development while complying with applicable laws and ethical standards.", "Advertising guaranteed cures for all visual disorders."], "correct": 2, "explanation": "Maintaining professional competence via continuing development while complying with laws and ethics is the model of ethical, lawful practice. Hint: keep learning + follow the law/ethics = the gold standard of practice."}'),
  ('87778607-28','{"options": ["digital pressure on the lacrimal sac after instillation", "punctual plug after instillation", "close the eyes for 5 minutes before the next instillation", "ask the patient blink normally after instillation to disperse the medication anteriorly"], "correct": 3, "explanation": "EXCEPT (does NOT prolong contact time). Punctal occlusion (digital pressure on the sac), punctal plugs, and eye closure all SLOW drainage and PROLONG drug contact. Asking the patient to BLINK NORMALLY disperses/pumps the drug into the drainage system FASTER — the exception. Prolong contact = occlude/close, not blink."}'),
  ('06d61d32-3f','{"options": ["Terminate the patient relationship immediately", "Respect the patient’s decision but document and explain the risks clearly", "File a complaint against the patient", "Ignore the complaint"], "correct": 1, "explanation": "Respect patient AUTONOMY: when a patient refuses treatment, you DOCUMENT the refusal and clearly EXPLAIN the risks (informed refusal) — you neither force care nor abandon/retaliate. Autonomy + documentation protects both parties. Refusal → document + counsel risks."}'),
  ('e4eee600-2p','{"options": ["Right to compensation", "Obligation to provide service with diligence", "Patient’s duty of compliance", "Reciprocity of fees"], "correct": 1, "explanation": "Accepting payment but failing to deliver on time breaches the OBLIGATION TO PROVIDE SERVICE WITH DILIGENCE (professional duty to perform competently and timely). It isn''t about the patient''s duties or ''reciprocity.'' Untimely/negligent service = breach of diligence."}'),
  ('38b52f73-30','{"options": ["Ignore the practice", "Report the violation to PRC or professional bodies", "Warn the patients quietly", "Copy the practice to compete"], "correct": 1, "explanation": "Witnessing unlicensed personnel performing refraction (illegal practice) obligates you to REPORT to the PRC/professional body — protecting the public is a professional duty. Ignoring, quietly warning, or copying it are all unethical. Illegal practice → report to PRC."}'),
  ('70ccda3a-2s','{"options": ["The refund is mandatory", "Fees are for professional services, not guaranteed cure", "The patient has no right to complain", "The spectacle should be free"], "correct": 1, "explanation": "Clarify that fees are for PROFESSIONAL SERVICES rendered, NOT a guaranteed ''cure'' — presbyopia is managed, not cured, and no refund is owed simply because spectacles don''t ''cure'' an age-related condition. Manage expectations: you pay for the service/expertise."}'),
  ('c44a7ce9-2h','{"options": ["Register at city hall", "Pass the Philippine licensure examination", "Work under a supervising ophthalmologist", "Show only his diploma"], "correct": 1, "explanation": "Under RA 8050, a foreign-trained optometrist must PASS the Philippine LICENSURE EXAMINATION (and meet registration requirements) to practice — a diploma or city-hall registration alone is insufficient, and optometry isn''t practiced ''under'' an ophthalmologist. Practice rights = pass the PH boards."}'),
  ('c3b47fb0-2e','{"options": ["Share with colleagues freely", "Keep confidentiality unless with patient consent or court order", "Use for marketing", "Post for clinical discussion online"], "correct": 1, "explanation": "Patient CONFIDENTIALITY: keep medical information private UNLESS the patient consents or a court order/legal mandate requires disclosure. Sharing freely, marketing, or posting online breaches confidentiality. Confidentiality unless consent/legal compulsion."}'),
  ('1f9aaad3-2g','{"options": ["Allowed if voluntary", "Unethical price undercutting", "Encouraged to compete", "Required by law"], "correct": 1, "explanation": "Charging EXTREMELY low fees to capture all patients = unethical PRICE UNDERCUTTING (unfair competition that demeans the profession), not legitimate voluntary pricing. Professional codes bar predatory undercutting. Predatory low fees = unethical."}'),
  ('fd9a51c6-2e','{"options": ["Provide it to satisfy the patient", "Refuse and explain the risks of unnecessary correction", "Ask for higher fees first", "Allow another staff member to decide"], "correct": 1, "explanation": "Refuse to provide an UNNECESSARY prescription and EXPLAIN the risks — prescribing what isn''t needed violates beneficence/non-maleficence (an unneeded correction can cause symptoms). Don''t appease the patient or upcharge. Don''t prescribe what isn''t indicated."}'),
  ('fd8af151-2d','{"options": ["Acceptable as marketing", "Misleading and unethical advertising", "Protected by freedom of speech", "Permitted only with approval"], "correct": 1, "explanation": "''Guaranteed cure for all eye conditions'' is MISLEADING/false ADVERTISING — prohibited (RA 8050/ethics). It isn''t protected speech or acceptable marketing. False health claims = unethical advertising."}'),
  ('48e40563-2c','{"options": ["Refuse care outright", "Provide no service until paid", "Consider professional compassion while maintaining integrity", "Demand collateral"], "correct": 2, "explanation": "A patient who can''t fully pay but urgently needs spectacles may be helped through PROFESSIONAL COMPASSION while MAINTAINING INTEGRITY (e.g., payment arrangement/charity) — not outright refusal or demanding collateral. Balance compassion with professional integrity."}'),
  ('da3c704d-1t','{"options": ["Deny release", "Charge excessively for release", "Provide records upon request with proper documentation", "Give only verbal notes"], "correct": 2, "explanation": "Provide the requested MEDICAL RECORDS upon proper request/documentation — records belong to the patient''s care and access is a right (with appropriate identity/consent verification). Don''t deny, overcharge, or give only verbal notes. Records access = patient''s right."}'),
  ('9fc8de57-1s','{"options": ["Creative marketing", "Illegal and unethical solicitation", "Permissible under RA 10912", "Acceptable if patients agree"], "correct": 1, "explanation": "Hiring AGENTS to canvass/solicit patients in malls is illegal/unethical SOLICITATION (touting) — professional services may not be hawked this way (not ''creative marketing'' or permitted under the CPD law RA 10912). Patient touting = prohibited solicitation."}'),
  ('daf6c497-2r','{"options": ["Sue the patient", "Document advice and re-explain proper use", "Stop seeing the patient", "Ignore the complaint"], "correct": 1, "explanation": "When a patient misuses spectacles and gets symptoms, your duty is to DOCUMENT the advice given and RE-EXPLAIN proper use (patient education/follow-up) — not to sue or abandon them. Re-educate and document; maintain the relationship."}'),
  ('f4636743-24','{"options": ["Code of advertising", "Collegiality and professional cooperation", "Patient autonomy", "Fee-splitting rules"], "correct": 1, "explanation": "A colleague refusing to accept your referrals breaches COLLEGIALITY and professional COOPERATION (the duty of practitioners to work together for patient care). It isn''t an advertising, autonomy, or fee-splitting issue. Refusing referrals = breach of collegiality."}'),
  ('ef5291a1-24','{"options": ["Ignore the false data", "Clarify and correct records while informing the patient", "File legal charges immediately", "Terminate care at once"], "correct": 1, "explanation": "If a patient gave FALSE information, CLARIFY and CORRECT the records while INFORMING the patient (maintain accurate records, address it professionally) — don''t ignore it, sue, or abandon care abruptly. Correct the record + communicate."}'),
  ('cc9dd727-2c','{"options": ["Practical shortcut", "Fraudulent and unethical conduct", "Allowed if provider agrees", "Acceptable during busy schedules"], "correct": 1, "explanation": "Paying to FAST-TRACK CPD units without attending = FRAUDULENT, unethical conduct (CPD must reflect genuine learning under RA 10912). It''s never an acceptable ''shortcut.'' Fake CPD = fraud."}'),
  ('db45336a-2q','{"options": ["Refuse the request", "Provide the prescription as it is the patient’s right", "Charge a penalty", "Warn against competitors"], "correct": 1, "explanation": "RELEASE the spectacle prescription on request — it is the PATIENT''S RIGHT to take their Rx and buy elsewhere; refusing, penalizing, or disparaging competitors is unethical. Rx portability = patient''s right."}'),
  ('d40b74a9-2f','{"options": ["Prescribe as requested", "Refuse and explain medical risks", "Refer to non-licensed sellers", "Offer more expensive options"], "correct": 1, "explanation": "Refuse the CONTRAINDICATED tinted contact lenses and EXPLAIN the medical risks — patient insistence doesn''t override your duty of non-maleficence; never refer to unlicensed sellers. Don''t provide contraindicated care; counsel risks."}'),
  ('f346a4fc-1y','{"options": ["Hide the mistake", "Admit, correct, and explain to the patient", "Blame laboratory staff", "Offer free frames instead"], "correct": 1, "explanation": "ADMIT the prescription error, CORRECT it, and EXPLAIN to the patient (honesty/transparency, integrity) — don''t hide it, shift blame, or paper over it with free frames. Disclose and remedy errors."}'),
  ('482115ad-28','{"options": ["Common courtesy", "Conflict of interest and unethical", "Encouraged business partnership", "Protected practice"], "correct": 1, "explanation": "Accepting GIFTS to prescribe a particular brand is a CONFLICT OF INTEREST (unethical inducement that biases clinical judgment) — not ''courtesy'' or a legitimate partnership. Kickbacks/gifts-for-prescribing = conflict of interest."}'),
  ('055b76fa-21','{"options": ["Proceed anyway", "Respect refusal and document informed decision", "Refuse all further care", "Charge extra fees"], "correct": 1, "explanation": "Respect the patient''s REFUSAL of dilation and DOCUMENT the informed decision (autonomy + informed refusal) — don''t proceed against their will, abandon them, or upcharge. Refusal of a test → honor + document (same principle as Q4)."}'),
  ('58f67f5a-28','{"options": ["Acceptable to attract clients", "Misleading advertising prohibited by RA 8050", "Modern marketing strategy", "Allowed with disclaimers"], "correct": 1, "explanation": "''100% cure for blindness'' is MISLEADING ADVERTISING prohibited by RA 8050 — exaggerated/false health claims are barred regardless of platform or disclaimers. False cure claims = prohibited advertising."}'),
  ('d9c794ad-1y','{"options": ["Normal sharing", "Plagiarism and unethical practice", "Acceptable in emergencies", "A form of patient education"], "correct": 1, "explanation": "Copying another''s research/work without credit is PLAGIARISM — unethical professional conduct (intellectual dishonesty), never acceptable as ''sharing'' or ''education.'' Uncredited copying = plagiarism."}'),
  ('68597933-21','{"options": ["Ignore since not your business", "Report to PRC as illegal practice", "Advise patients to avoid", "Offer to cover for him"], "correct": 1, "explanation": "An optometrist practicing on an EXPIRED license is engaged in ILLEGAL PRACTICE → REPORT to the PRC. It IS your professional concern (public protection); don''t cover for them. Expired license practice → report to PRC."}'),
  ('a74d2804-2g','{"options": ["Applaud politely", "Correct or report misinformation", "Copy claims for your lecture", "Stay silent"], "correct": 1, "explanation": "When a practitioner spreads FALSE scientific claims, your professional duty is to CORRECT or REPORT the misinformation (uphold evidence-based standards), not applaud, copy, or stay silent. Counter misinformation."}'),
  ('c3fda287-1v','{"options": ["Good marketing strategy", "Unethical commercialization of professional service", "Encouraged by PRC", "Permitted if patients are satisfied"], "correct": 1, "explanation": "A ''buy one take one'' spectacle promo is unethical COMMERCIALIZATION of a professional service (treats clinical care like retail merchandise) — barred by professional standards, not endorsed by PRC. Gimmick promos on professional services = unethical."}'),
  ('6e836f34-1t','{"options": ["Attempt anyway", "Refer to a specialist", "Refuse without explanation", "Allow unlicensed staff to handle"], "correct": 1, "explanation": "A patient wanting treatment OUTSIDE your competence should be REFERRED to a specialist (know your limits — non-maleficence) — don''t attempt it, refuse without explanation, or delegate to unlicensed staff. Beyond scope/competence → refer."}'),
  ('eb3abb31-24','{"options": ["Provide spectacles only", "Refer to an ophthalmologist", "Prescribe stronger lenses", "Discharge without advice"], "correct": 1, "explanation": "A patient needing SURGERY must be REFERRED to an OPHTHALMOLOGIST (surgery is outside optometry''s scope) — not managed with spectacles/stronger lenses or discharged. Surgical need → ophthalmology referral."}'),
  ('b59a4a0d-2e','{"options": ["Patient autonomy", "Duty of care and competence", "Collegiality", "Fee-sharing rules"], "correct": 1, "explanation": "Accepting a patient but NEGLECTING necessary exams breaches the DUTY OF CARE and COMPETENCE (failing the standard of a diligent optometrist) — the basis of negligence/malpractice. Incomplete work-up = breach of duty of care."}'),
  ('cce8c3ed-2f','{"options": ["Proceed to please the patient", "Refuse until the patient is fit for examination", "Perform partial exam only", "Ask another patient to decide"], "correct": 1, "explanation": "An INTOXICATED patient demanding refraction should be REFUSED until fit for examination (unreliable results, patient safety) — don''t proceed to please them or do a partial exam. Examine only when the patient is fit."}'),
  ('5a5784b5-2a','{"options": ["Stay quiet to avoid conflict", "Report the misrepresentation to PRC", "Advise patients not to go", "Ignore unless asked directly"], "correct": 1, "explanation": "A colleague MISREPRESENTING himself as an ''ophthalmologist'' (a different, medical/surgical profession) must be REPORTED to the PRC — misrepresentation of credentials is illegal/unethical. False credentials → report."}'),
  ('9b27ce1b-2r','{"options": ["Attempt carefully", "Refer to ophthalmologist for proper management", "Use improvised tools", "Send patient home without advice"], "correct": 1, "explanation": "FOREIGN BODY removal beyond optometry scope warrants REFERRAL to an ophthalmologist for proper management — don''t improvise tools or send the patient away untreated. Out-of-scope procedure → refer."}'),
  ('efae3376-38','{"options": ["Collegiality", "CPD requirement", "Patient’s right to informed consent regarding fees", "Advertising rules"], "correct": 2, "explanation": "Charging separately for each minor procedure WITHOUT prior notice violates the patient''s RIGHT TO INFORMED CONSENT regarding FEES (financial transparency) — patients must understand costs beforehand. Surprise fees = informed-consent (financial) breach."}'),
  ('7acd0c21-2e','{"options": ["Write it quietly", "Charge a higher fee for the risk", "Refuse and explain it is fraudulent and unethical", "Provide only if close friend"], "correct": 2, "explanation": "Writing a FAKE prescription for a reimbursement claim = FRAUD; REFUSE and explain it''s fraudulent/unethical (even for a friend, regardless of fee). Falsifying documents = fraud, always refuse."}'),
  ('428a493f-1w','{"options": ["The optometrist must accept loss", "The optometrist has the right to fair compensation", "Payment is optional", "Only the supplier can demand payment"], "correct": 1, "explanation": "An optometrist has a RIGHT to FAIR COMPENSATION for services rendered — a patient refusing to pay after receiving spectacles doesn''t make the optometrist absorb the loss or render payment ''optional.'' Right to fair payment for services."}'),
  ('f0be6fee-2p','{"options": ["Acceptable promotion", "Misrepresentation and unethical advertising", "Encouraged to attract clients", "Protected under innovation rights"], "correct": 1, "explanation": "EXAGGERATING results of a new vision-therapy technology in ads = MISREPRESENTATION / unethical advertising (claims must be truthful/evidence-based) — not protected by ''innovation rights.'' Overstated efficacy claims = unethical."}'),
  ('87ec2dec-25','{"options": ["Collegiality", "Confidentiality", "Fee agreements", "Patient autonomy"], "correct": 1, "explanation": "Publicly revealing a (celebrity) patient''s diagnosis breaches CONFIDENTIALITY — patient privacy applies regardless of fame. Disclosing diagnosis = confidentiality breach."}'),
  ('54774e8e-2g','{"options": ["Allowed for education", "Ethical if identity hidden", "Breach of confidentiality", "Permissible if deleted later"], "correct": 2, "explanation": "Posting a patient''s retinal IMAGE on social media WITHOUT consent is a BREACH OF CONFIDENTIALITY (identifiable medical data) — not justified by ''education,'' hidden identity, or later deletion. No-consent posting = confidentiality breach."}'),
  ('b7b748cb-1x','{"options": ["Right to choose patients", "Unethical discrimination", "Freedom of association", "Strategic decision"], "correct": 1, "explanation": "Refusing patients by POLITICAL affiliation is unethical DISCRIMINATION — care must be non-discriminatory; it''s not a legitimate ''right to choose'' or ''freedom of association'' in professional practice. Discriminatory refusal = unethical."}'),
  ('30aed278-29','{"options": ["Acceptable flexibility", "Unethical discrimination in fees", "Professional right", "Encouraged by law"], "correct": 1, "explanation": "Charging different fees based on a patient''s SOCIAL STATUS is unethical fee DISCRIMINATION (fees should be fair/consistent for like services) — not a ''professional right.'' Status-based fee discrimination = unethical."}'),
  ('c4025e2a-1g','{"options": ["Patient consented orally", "You exercised diligence expected of a competent optometrist", "The patient is partly at fault", "Fees were low"], "correct": 1, "explanation": "A negligence defense rests on showing you EXERCISED the DILIGENCE/standard of care expected of a competent optometrist (met the standard, no breach) — not on the patient''s oral consent, partial fault, or low fees. Defense = met the standard of care."}'),
  ('63b8a585-1n','{"options": ["Motivational marketing", "False claim, unethical and illegal", "Innovative service", "Freedom of advertisement"], "correct": 1, "explanation": "Guaranteeing an ''instant cure'' for GLAUCOMA is a FALSE, unethical, and ILLEGAL claim (glaucoma is managed, not instantly cured) — barred under RA 8050/ethics. False cure guarantee = illegal/unethical."}'),
  ('60093e12-1j','{"options": ["RA 7722", "RA 8050 – Revised Optometry Law of 1995", "RA 10912", "RA 9165"], "correct": 1, "explanation": "RA 8050 is the REVISED OPTOMETRY LAW OF 1995. (RA 7722 = Higher Education Act/CHED; RA 10912 = CPD Act; RA 9165 = Dangerous Drugs Act.) Optometry law = RA 8050."}'),
  ('45725320-17','{"options": ["Obtain barangay clearance", "Secure a valid PRC license and registration", "Join the local chapter of IPAO", "Announce availability in the newspaper"], "correct": 1, "explanation": "Before practicing, an optometrist must secure a VALID PRC LICENSE and registration (the legal prerequisite). Barangay clearance/IPAO membership/newspaper notice are not the licensing requirement. Practice = PRC license first."}'),
  ('9917892f-2c','{"options": ["Department of Health", "Professional Regulation Commission (PRC)", "Department of Education", "Department of Trade"], "correct": 1, "explanation": "The PROFESSIONAL REGULATION COMMISSION (PRC) — through the Board of Optometry — regulates/supervises optometry under RA 8050. Not DOH/DepEd/DTI. Regulator = PRC."}'),
  ('e395bf85-12','{"options": ["Provide free eyeglasses", "Regulate advertisements of spectacles", "Upgrade and regulate the practice of optometry", "Limit the number of practitioners"], "correct": 2, "explanation": "RA 8050''s primary objective is to UPGRADE and REGULATE the practice of optometry (standards, licensure, scope) — not to give free eyeglasses, regulate ads, or cap practitioner numbers. Purpose = elevate/regulate the profession."}'),
  ('c36e0d0e-s','{"options": ["Completed apprenticeship", "Are members of private organizations", "Passed the licensure examination and registered with PRC", "Paid city business taxes may practice optometry in the Philippines."], "correct": 2, "explanation": "Under RA 8050, only those who PASSED the LICENSURE exam and REGISTERED with the PRC may practice optometry — not apprenticeship, private-org membership, or paying business taxes. Legal practice = licensed + registered."}'),
  ('c1b93a64-1n','{"options": ["Selling ready-made eyeglasses", "Performing refraction without a license", "Selling frames only", "Dispensing contact lens solutions"], "correct": 1, "explanation": "Performing REFRACTION WITHOUT a license is illegal practice under RA 8050 (refraction is a regulated optometric act). Selling ready-made glasses/frames or CL solutions are retail acts, not the regulated clinical act. Unlicensed refraction = illegal practice."}'),
  ('3795c97a-22','{"options": ["Collegial loyalty", "Illegal practice of optometry", "Patient negligence", "Advertising violation"], "correct": 1, "explanation": "LENDING your license to an unqualified person = ILLEGAL PRACTICE of optometry (enabling unlicensed practice) — punishable, not ''loyalty.'' License lending = illegal practice."}'),
  ('f1d237ac-24','{"options": ["Warning only", "Fine and/or imprisonment", "Suspension of clinic permit", "Community service"], "correct": 1, "explanation": "The minimum penalty for ILLEGAL PRACTICE under RA 8050 includes a FINE AND/OR IMPRISONMENT (a penal sanction) — not merely a warning, permit suspension, or community service. Illegal practice = fine and/or jail."}'),
  ('8cc214b6-1p','{"options": ["3 members appointed by CHED", "Chairperson and 4 members appointed by the President", "Only PRC commissioners", "IPAO representatives"], "correct": 1, "explanation": "The source keys the Board of Optometry as a CHAIRPERSON + 4 MEMBERS (5), appointed by the President. NOTE: RA 8050 (1995) originally specified a Chairman + TWO members (3 total); verify whether a later amendment expanded it. Either way, the Board is presidentially appointed via PRC. [Confirm current composition.]"}'),
  ('5f307d6a-1x','{"options": ["Dispensing drugs for systemic conditions", "Prescribing ophthalmic lenses and contact lenses", "Performing ocular surgeries", "Practicing medicine"], "correct": 1, "explanation": "Within RA 8050 scope: PRESCRIBING ophthalmic lenses and contact lenses (and refraction, detecting abnormalities, using DPAs). NOT systemic-drug dispensing, surgery, or practicing medicine. Optometry scope = refraction + optical/CL prescribing + diagnostics."}'),
  ('e6aea346-1e','{"options": ["Late in filing taxes", "Guilty of immoral or dishonorable conduct", "Running for office", "A member of multiple associations"], "correct": 1, "explanation": "The PRC may REVOKE a license for IMMORAL or DISHONORABLE conduct (and other grounds like fraud/incompetence) — not for late taxes, running for office, or multiple memberships. Revocation ground = moral/professional misconduct."}'),
  ('8b6adba1-13','{"options": ["Optional", "Mandatory", "Discouraged", "Required only during inspections"], "correct": 1, "explanation": "Displaying the PRC license in the clinic is MANDATORY (proof of legitimacy to the public) — not optional or inspection-only. PRC license must be displayed."}'),
  ('09ea2a71-1i','{"options": ["Refraction and prescription of lenses", "Detection of eye abnormalities", "Performing retinal surgery", "Fitting contact lenses"], "correct": 2, "explanation": "NOT in optometry scope = answer. Optometry covers refraction/prescribing, detecting abnormalities, and fitting contact lenses; RETINAL SURGERY (any intraocular surgery) is OUTSIDE the scope (ophthalmology). Surgery = beyond optometry."}'),
  ('96e8cb01-1m','{"options": ["DOH", "PRC through the Professional Regulatory Board of Optometry", "Local government units", "IPAO"], "correct": 1, "explanation": "The optometry LICENSURE EXAM is conducted by the PRC through the Professional Regulatory Board of Optometry — not DOH/LGUs/IPAO. Boards = PRC + the Board of Optometry."}'),
  ('235d0035-1e','{"options": ["Refraction", "Ocular assessment", "Use of unlicensed assistants to perform optometry", "Fitting spectacles"], "correct": 2, "explanation": "PROHIBITED under RA 8050 = using UNLICENSED ASSISTANTS to perform optometric (regulated) acts. Refraction, ocular assessment, and fitting by the licensed optometrist are permitted; delegating them to the unlicensed is illegal. No unlicensed practice by proxy."}'),
  ('b22c9fcf-22','{"options": ["Maintain clinic business permit", "Ensure optometrists remain updated and competent", "Compete internationally", "Avoid taxation"], "correct": 1, "explanation": "CPD (formerly CPE) is required under RA 8050/RA 10912 to ensure optometrists stay UPDATED and COMPETENT (lifelong learning for quality care) — not for permits, international competition, or taxes. CPD = maintain competence."}'),
  ('c893b10e-1y','{"options": ["Warning only", "Revocation or suspension of license", "Free CPD requirement", "Community service"], "correct": 1, "explanation": "Conviction of a crime involving MORAL TURPITUDE can lead to REVOCATION or SUSPENSION of the license (a serious disciplinary ground) — not a mere warning or community service. Moral turpitude → license revocation/suspension."}'),
  ('b00c78ef-59','{"options": ["Proof of Business Name Registration", "Risk Management Plan", "Standard Operating Procedure", "Marketing and Promotion Plan"], "correct": 0, "explanation": "VERIFY (corrupted item): the intended answer is the Social Security Act (RA 11199, formerly RA 8282), which mandates SSS registration and contributions. The printed options here were mis-copied from the previous question, so none match; check the source."}'),
  ('7fedca1b-71','{"options": ["Board, President of the Phils.", "Board, Commission", "Accredited Organization, Board", "Accredited Organization, Commission"], "correct": 1, "explanation": "The Code of Ethics is prescribed by the integrated/accredited national optometry organization and ADOPTED/promulgated by the BOARD (of Optometry) upon approval of the COMMISSION (PRC). So ''Board, Commission.'' Code of Ethics = Board promulgates, Commission approves."}'),
  ('b0102c72-18','{"options": ["Dr. Teodoro Herbosa", "Dr. Christine Rodriguez", "Dr. Charlie L. Ho", "Dr. Francisco Tiongson Duque III"], "correct": 0, "explanation": "As of August 2025 the DOH Secretary is Dr. TEODORO HERBOSA. (Francisco Duque III was a prior secretary.) Current DOH Secretary (2025) = Herbosa. [Time-sensitive fact — verify for exam date.]"}'),
  ('de1f27fa-5g','{"options": ["India", "Africa", "Asia", "Vietnam"], "correct": 0, "explanation": "Per WHO, INDIA has the highest number of blind people (largest burden of blindness by country) — driven by cataract and refractive error in a huge population. Highest blind population = India."}'),
  ('215ef17a-4g','{"options": ["Department of Health", "World Health Organization", "Occupational Safety and Health", "United Nations"], "correct": 1, "explanation": "The agency focused on identifying OCCUPATIONAL health problems and practical solutions for workers is, per the source, the WHO (which addresses occupational health globally; the ILO and OSH bodies also do). The keyed answer is WHO. [Note: OSH/ILO are the dedicated occupational bodies — source keys WHO.]"}'),
  ('c407cab2-29','{"options": ["condition is termed as:", "Pandemic", "Endemic", "Epidemic", "Contagious"], "correct": 2, "explanation": "A disease consistently present at LOW frequency in a community AT ALL TIMES = ENDEMIC (constant baseline presence). Epidemic = sudden rise above baseline; pandemic = multi-country epidemic; contagious = transmissible. Constant low-level = endemic."}'),
  ('d56f16b5-2p','{"options": ["Regular use of sunglasses", "Vitamin A supplementation", "Limiting screen time", "Providing magnifying glasses"], "correct": 1, "explanation": "A key public-health measure against CHILDHOOD blindness is VITAMIN A SUPPLEMENTATION (prevents xerophthalmia/keratomalacia, a leading preventable cause). Sunglasses/screen-time/magnifiers don''t prevent childhood blindness. Childhood blindness prevention = Vitamin A."}'),
  ('91fb96eb-77','{"options": ["20/40 ; 20/80", "20/200 ; 20/400", "6/30 ; 6/60", "6/60 ; 6;300"], "correct": 1, "explanation": "ICD-11 SEVERE distance vision impairment = best-corrected VA WORSE than 20/200 (6/60) but BETTER than 20/400 (3/60). (Moderate = worse than 20/70 to 20/200; blindness = worse than 20/400.) Severe category = 20/200 to 20/400."}'),
  ('6b24903e-3d','{"options": ["Pag-IBIG Fund", "PhilHealth", "Department of Health (DOH) insurance", "Social Security System (SSS) Health Insurance"], "correct": 1, "explanation": "The Universal Health Care Act (RA 11223) automatically enrolls all Filipinos in PhilHealth (the National Health Insurance Program). Not Pag-IBIG/SSS. UHC = automatic PhilHealth coverage."}'),
  ('ee80cb5d-4i','{"options": ["Tuberculosis", "Malaria", "Cholera", "Smallpox"], "correct": 2, "explanation": "In the early 20th-century American colonial period, a major Philippine public-health focus was CHOLERA (and other epidemic diseases) — large cholera outbreaks drove sanitation campaigns. Colonial-era public health = cholera control."}'),
  ('aad38b8e-34','{"options": ["Treating a child diagnosed with amblyopia after screening.", "Offering free corrective lenses to children with refractive errors.", "Screening children for vision problems before they show symptoms, to prevent future complications.", "Recommending surgery for individuals with cataracts."], "correct": 2, "explanation": "PRIMARY prevention = preventing disease BEFORE it occurs: SCREENING asymptomatic children to catch problems early/prevent complications fits (screening as early detection/prevention). Treating amblyopia or cataract surgery are secondary/tertiary (after disease). Screening before symptoms = primary prevention. [Note: screening is often classed as secondary prevention; the source labels this primary.]"}'),
  ('5232a467-19','{"options": ["Through taxes paid by businesses only", "Contributions from members and their employers", "Donations from international organizations", "A government budget allocation every year"], "correct": 1, "explanation": "PhilHealth is funded primarily by CONTRIBUTIONS from MEMBERS and their EMPLOYERS (premium contributions) — plus government subsidy for indigents. Not business taxes only, donations, or a sole annual budget line. PhilHealth = member + employer premiums."}'),
  ('0293b58d-2r','{"options": ["Rinse the eye with clean water for at least 20 minutes", "Cover the eye with clean cloth and seek medical attention", "Rub the eye to remove the ammonia", "Blow the eye until the ammonia dries out"], "correct": 0, "explanation": "A chemical (ammonia, an ALKALI) eye burn requires IMMEDIATE copious IRRIGATION with clean water for ≥20 minutes FIRST (dilute/remove the chemical before anything else) — alkali burns penetrate fast and are sight-threatening. Don''t rub or delay. Chemical burn = irrigate immediately."}'),
  ('4a60f8c0-2c','{"options": ["polio?", "The elimination of contaminated water with poliovirus", "The successful surgical treatment for the patients", "The increase sales of surgical face masks", "The launch of the national vaccination program"], "correct": 4, "explanation": "The Philippines'' major public-health win against POLIO was the LAUNCH of the NATIONAL VACCINATION (immunization) program — mass oral polio vaccination led toward polio-free status. Polio control = vaccination program."}'),
  ('ba04d303-1t','{"options": ["Acceptable if PRC application is pending", "Unethical and illegal under RA 8050", "Acceptable if supervised by an ophthalmologist", "No regulation against it"], "correct": 1, "explanation": "Advertising as ''Dr. [Name], Optometrist'' WITHOUT a valid PRC license is UNETHICAL and ILLEGAL under RA 8050 (holding out as a licensed practitioner without a license) — a pending application or ''supervision'' doesn''t legitimize it. No license = can''t advertise as one."}'),
  ('bdf361e4-2i','{"options": ["PRC regulations only", "FDA regulations only", "Both FDA and PRC ethical standards", "None, if drops are over-the-counter"], "correct": 3, "explanation": "Selling a clinic''s OWN brand of ophthalmic drops WITHOUT FDA registration violates BOTH FDA regulations (unregistered health product) AND PRC/ethical standards. Even ''OTC'' drops require FDA registration to be sold. Unregistered drug sale = FDA + ethics violation. [Source keys ''none if OTC'' — but unregistered products are still illegal; verify.]"}')
)
UPDATE question_reviews r
SET payload = r.payload || d.patch::jsonb
FROM d
WHERE r.question_id = d.qid;
